// AccountTransfer.jsx
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useContext } from "react";
import {
  ArrowRight, ArrowRightLeft, Calendar, ChevronDown, FileText,
  Filter, Plus, RefreshCw, X, AlertCircle, CheckCircle,
} from "lucide-react";
import {
  COLLECTIONS,
  listCollection,
  runFirestoreTransaction,
  getDocById,
} from "../lib/firestore.js";
import { db } from "../firebase.js";
import { doc, serverTimestamp, updateDoc, addDoc, collection } from "firebase/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

const formatMoney = (v) =>
  `Rs.${Number(v || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const formatDate = (v) => {
  if (!v) return "-";
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return "-";
  return d.toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" });
};

const AccountTransfer = () => {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [accounts, setAccounts] = useState([]);
  const [transfers, setTransfers] = useState([]);
  const [loadingAccounts, setLoadingAccounts] = useState(false);
  const [loadingTransfers, setLoadingTransfers] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [saving, setSaving] = useState(false);

  const [filterFromAccount, setFilterFromAccount] = useState("");
  const [filterToAccount, setFilterToAccount] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const [formData, setFormData] = useState({
    fromAccountId: "",
    toAccountId: "",
    amount: "",
    description: "",
    referenceNo: "",
    transferDate: new Date().toISOString().split("T")[0],
  });

  /* ---------- LOAD ACCOUNTS ---------- */
  const loadAccounts = useCallback(async () => {
    try {
      setLoadingAccounts(true);
      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });
      setAccounts(
        rows.map((a) => ({
          id: a.id,
          name: a.AccountName || a.name || "Unknown",
          balance: Number(a.StoredBalance ?? a.balance ?? 0),
          type: a.AccountType || a.type || "",
        }))
      );
    } catch (err) {
      console.error(err);
      setError(err.message);
    } finally {
      setLoadingAccounts(false);
    }
  }, []);

  /* ---------- LOAD TRANSFERS ---------- */
  const loadTransfers = useCallback(async () => {
    try {
      setLoadingTransfers(true);
      setError("");
      const rows = await listCollection(COLLECTIONS.ACCOUNT_TRANSFERS, {
        where: [["IsDelete", "==", 0]],
      });
      const normalized = rows
        .map((r) => ({
          TransferID: r.id,
          FromAccountID: r.FromAccountID || r.fromAccountId,
          FromAccountName: r.FromAccountName || r.fromAccountName || "-",
          ToAccountID: r.ToAccountID || r.toAccountId,
          ToAccountName: r.ToAccountName || r.toAccountName || "-",
          Amount: Number(r.Amount || r.amount || 0),
          Description: r.Description || r.description || "",
          ReferenceNo: r.ReferenceNo || r.referenceNo || "",
          TransferDate: r.TransferDate || r.transferDate,
        }))
        .sort((a, b) => new Date(b.TransferDate || 0) - new Date(a.TransferDate || 0));
      setTransfers(normalized);
    } catch (err) {
      console.error(err);
      setTransfers([]);
      setError(err.message);
    } finally {
      setLoadingTransfers(false);
    }
  }, []);

  useEffect(() => {
    loadAccounts();
  }, [loadAccounts]);

  useEffect(() => {
    loadTransfers();
  }, [loadTransfers]);

  /* ---------- FILTERS (client-side) ---------- */
  const filteredTransfers = useMemo(() => {
    return transfers.filter((t) => {
      if (filterFromAccount && String(t.FromAccountID) !== String(filterFromAccount)) return false;
      if (filterToAccount && String(t.ToAccountID) !== String(filterToAccount)) return false;
      if (fromDate) {
        const d = new Date(t.TransferDate || 0).getTime();
        if (Number.isFinite(d) && d < new Date(fromDate).getTime()) return false;
      }
      if (toDate) {
        const d = new Date(t.TransferDate || 0).getTime();
        const end = new Date(toDate);
        end.setHours(23, 59, 59, 999);
        if (Number.isFinite(d) && d > end.getTime()) return false;
      }
      return true;
    });
  }, [transfers, filterFromAccount, filterToAccount, fromDate, toDate]);

  const summary = useMemo(() => {
    const total = filteredTransfers.reduce((s, t) => s + Number(t.Amount || 0), 0);
    return { count: filteredTransfers.length, total };
  }, [filteredTransfers]);

  const clearFilters = () => {
    setFilterFromAccount("");
    setFilterToAccount("");
    setFromDate("");
    setToDate("");
  };

  const openModal = () => {
    setError("");
    setSuccessMessage("");
    setFormData({
      fromAccountId: "",
      toAccountId: "",
      amount: "",
      description: "",
      referenceNo: "",
      transferDate: new Date().toISOString().split("T")[0],
    });
    setShowModal(true);
  };

  const closeModal = () => {
    if (saving) return;
    setShowModal(false);
  };

  /* ---------- SUBMIT — ATOMIC TRANSFER ---------- */
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccessMessage("");

    const fromId = formData.fromAccountId;
    const toId = formData.toAccountId;
    const amount = Number(formData.amount);

    if (!fromId || !toId) return setError("Select both accounts.");
    if (fromId === toId) return setError("Accounts must be different.");
    if (!amount || amount <= 0) return setError("Enter a valid amount.");

    try {
      setSaving(true);

      const fromAccount = await getDocById(COLLECTIONS.ACCOUNTS, fromId);
      const toAccount = await getDocById(COLLECTIONS.ACCOUNTS, toId);

      if (!fromAccount || !toAccount) throw new Error("Account not found.");

      const fromBalance = Number(fromAccount.StoredBalance || 0);
      if (fromBalance < amount) {
        throw new Error(
          `Insufficient funds in ${fromAccount.AccountName || "source"} (${formatMoney(fromBalance)}).`
        );
      }

      const transferDate = formData.transferDate;
      const description = formData.description?.trim() || "";
      const referenceNo = formData.referenceNo?.trim() || "";

      /*
       * Atomic write:
       *   1. Decrement From.StoredBalance
       *   2. Increment To.StoredBalance
       *   3. Create AccountTransfers doc
       *   4. Create 2 AccountTransactions (debit from, credit to)
       */
      await runFirestoreTransaction(async (tx) => {
        // 1+2. Balances
        tx.update(doc(db, COLLECTIONS.ACCOUNTS, fromId), {
          StoredBalance: fromBalance - amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });
        tx.update(doc(db, COLLECTIONS.ACCOUNTS, toId), {
          StoredBalance: Number(toAccount.StoredBalance || 0) + amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        // 3. Transfer record
        const transferRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSFERS));
        tx.set(transferRef, {
          FromAccountID: fromId,
          FromAccountName: fromAccount.AccountName || "",
          ToAccountID: toId,
          ToAccountName: toAccount.AccountName || "",
          Amount: amount,
          Description: description,
          ReferenceNo: referenceNo,
          TransferDate: transferDate,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
          IsDelete: 0,
        });

        // 4a. Debit from
        const debitRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS));
        tx.set(debitRef, {
          AccountID: fromId,
          AccountName: fromAccount.AccountName || "",
          AccountType: fromAccount.AccountType || "",
          DetailType: fromAccount.DetailType || "",
          TransactionDate: transferDate,
          TransactionType: "Transfer Out",
          Description: description || `Transfer to ${toAccount.AccountName}`,
          ReferenceNo: referenceNo,
          Debit: amount,
          Credit: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        // 4b. Credit to
        const creditRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS));
        tx.set(creditRef, {
          AccountID: toId,
          AccountName: toAccount.AccountName || "",
          AccountType: toAccount.AccountType || "",
          DetailType: toAccount.DetailType || "",
          TransactionDate: transferDate,
          TransactionType: "Transfer In",
          Description: description || `Transfer from ${fromAccount.AccountName}`,
          ReferenceNo: referenceNo,
          Debit: 0,
          Credit: amount,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });
      });

      setSuccessMessage("Transfer completed successfully.");
      setShowModal(false);
      await loadAccounts();
      await loadTransfers();
    } catch (err) {
      console.error(err);
      setError(err.message || "Transfer failed");
    } finally {
      setSaving(false);
    }
  };

  /* ---------- RENDER ---------- */
  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
      {/* HEADER — unchanged structure */}
      <div className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Account Transfers</h1>
          <p className="mt-1 text-sm text-gray-500">Transfer funds between accounts</p>
        </div>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={openModal}
            disabled={loadingAccounts || accounts.length < 2}
            className="inline-flex items-center gap-2 rounded-xl bg-amber-500 px-5 py-3 text-sm font-semibold text-white shadow-sm hover:bg-amber-600 disabled:opacity-50"
          >
            <Plus size={18} /> New Transfer
          </button>
          <button
            type="button"
            className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-5 py-3 text-sm font-semibold text-gray-700 shadow-sm hover:bg-gray-50"
          >
            <FileText size={18} /> Transfer Cheques
          </button>
        </div>
      </div>

      {successMessage && (
        <div className="mb-5 flex items-center justify-between rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-green-700">
          <div className="flex items-center gap-2"><CheckCircle size={18} /><span className="text-sm font-medium">{successMessage}</span></div>
          <button onClick={() => setSuccessMessage("")}><X size={18} /></button>
        </div>
      )}

      {error && (
        <div className="mb-5 flex items-center justify-between rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">
          <div className="flex items-center gap-2"><AlertCircle size={18} /><span className="text-sm font-medium">{error}</span></div>
          <button onClick={() => setError("")}><X size={18} /></button>
        </div>
      )}

      <div className="mb-6 max-w-md rounded-2xl border border-gray-200 bg-white p-6 shadow-sm">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-gray-600">Total Transfers</p>
            <p className="mt-2 text-2xl font-bold text-gray-900">{formatMoney(summary.total)}</p>
            <p className="mt-1 text-xs text-gray-500">{summary.count} transfer{summary.count === 1 ? "" : "s"}</p>
          </div>
          <div className="text-gray-400"><ArrowRightLeft size={22} /></div>
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
        <div className="flex flex-col gap-4 border-b border-gray-200 px-6 py-5 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-xl font-bold text-gray-900">Transfer History</h2>
            <p className="mt-1 text-sm text-gray-500">View and filter account transfers</p>
          </div>
          <div className="flex gap-2">
            <button onClick={clearFilters} className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50">
              <Filter size={15} /> Clear Filters
            </button>
            <button onClick={loadTransfers} disabled={loadingTransfers} className="inline-flex items-center gap-2 rounded-xl border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50">
              <RefreshCw size={15} className={loadingTransfers ? "animate-spin" : ""} /> Refresh
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="grid grid-cols-1 gap-4 border-b border-gray-200 px-6 py-4 md:grid-cols-2 xl:grid-cols-4">
          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-700">From Account</label>
            <div className="relative">
              <select value={filterFromAccount} onChange={(e) => setFilterFromAccount(e.target.value)} className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-3 py-2.5 pr-10 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100">
                <option value="">All accounts</option>
                {accounts.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
              </select>
              <ChevronDown size={16} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-700">To Account</label>
            <div className="relative">
              <select value={filterToAccount} onChange={(e) => setFilterToAccount(e.target.value)} className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-3 py-2.5 pr-10 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100">
                <option value="">All accounts</option>
                {accounts.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
              </select>
              <ChevronDown size={16} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-700">From Date</label>
            <div className="relative">
              <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} className="w-full rounded-lg border border-gray-300 px-3 py-2.5 pr-10 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              <Calendar size={16} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-gray-700">To Date</label>
            <div className="relative">
              <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} className="w-full rounded-lg border border-gray-300 px-3 py-2.5 pr-10 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              <Calendar size={16} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full">
            <thead className="border-b border-gray-200 bg-white">
              <tr>
                {["Date", "From Account", "", "To Account", "Description", "Reference", "Amount"].map((h, i) => (
                  <th key={i} className={`px-6 py-4 text-xs font-semibold uppercase tracking-wide text-gray-500 ${h === "Amount" ? "text-right" : "text-left"}`}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {loadingTransfers && (
                <tr><td colSpan={7} className="px-6 py-12 text-center text-sm text-gray-500"><RefreshCw size={18} className="mr-2 inline animate-spin" />Loading transfers...</td></tr>
              )}
              {!loadingTransfers && filteredTransfers.length === 0 && (
                <tr><td colSpan={7} className="px-6 py-16 text-center">
                  <ArrowRightLeft size={24} className="mx-auto mb-3 text-gray-400" />
                  <p className="font-medium text-gray-700">No transfers found</p>
                  <p className="mt-1 text-sm text-gray-500">Adjust filters or create a new transfer.</p>
                </td></tr>
              )}
              {!loadingTransfers && filteredTransfers.map((row) => (
                <tr key={row.TransferID} className="hover:bg-gray-50">
                  <td className="whitespace-nowrap px-6 py-4 text-sm text-gray-700">
                    <div className="flex items-center gap-2"><Calendar size={14} className="text-gray-400" />{formatDate(row.TransferDate)}</div>
                  </td>
                  <td className="px-6 py-4 text-sm font-semibold text-gray-900">{row.FromAccountName}</td>
                  <td className="px-2 text-gray-400"><ArrowRight size={16} /></td>
                  <td className="px-6 py-4 text-sm font-semibold text-gray-900">{row.ToAccountName}</td>
                  <td className="max-w-xs px-6 py-4 text-sm text-gray-600"><div className="truncate" title={row.Description}>{row.Description || "-"}</div></td>
                  <td className="px-6 py-4 text-sm text-gray-500">{row.ReferenceNo || "-"}</td>
                  <td className="whitespace-nowrap px-6 py-4 text-right text-sm font-bold text-gray-900">{formatMoney(row.Amount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL — same structure as original, save handler now writes to Firestore */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b px-5 py-4">
              <div>
                <h2 className="text-lg font-bold text-gray-900">Account Transfer</h2>
                <p className="text-xs text-gray-500">Transfer funds between accounts</p>
              </div>
              <button onClick={closeModal} className="rounded-lg p-2 text-gray-400 hover:bg-gray-100"><X size={18} /></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4 px-5 py-4">
              <Field label="From Account *">
                <select value={formData.fromAccountId} onChange={(e) => setFormData((p) => ({ ...p, fromAccountId: e.target.value }))} required className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100">
                  <option value="">Select source</option>
                  {accounts.map((a) => <option key={a.id} value={a.id}>{a.name} — {formatMoney(a.balance)}</option>)}
                </select>
              </Field>

              <Field label="To Account *">
                <select value={formData.toAccountId} onChange={(e) => setFormData((p) => ({ ...p, toAccountId: e.target.value }))} required className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100">
                  <option value="">Select destination</option>
                  {accounts.filter((a) => String(a.id) !== String(formData.fromAccountId)).map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
                </select>
              </Field>

              <Field label="Amount *">
                <input type="number" min="0.01" step="0.01" value={formData.amount} onChange={(e) => setFormData((p) => ({ ...p, amount: e.target.value }))} required placeholder="0.00" className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              </Field>

              <Field label="Transfer Date *">
                <input type="date" value={formData.transferDate} onChange={(e) => setFormData((p) => ({ ...p, transferDate: e.target.value }))} required className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              </Field>

              <Field label="Reference">
                <input type="text" value={formData.referenceNo} onChange={(e) => setFormData((p) => ({ ...p, referenceNo: e.target.value }))} className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              </Field>

              <Field label="Description">
                <textarea rows={3} value={formData.description} onChange={(e) => setFormData((p) => ({ ...p, description: e.target.value }))} className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-amber-500 focus:ring-2 focus:ring-amber-100" />
              </Field>

              {error && <div className="rounded-lg bg-red-50 px-3 py-2.5 text-sm text-red-600">{error}</div>}

              <div className="flex justify-end gap-3 border-t pt-4">
                <button type="button" onClick={closeModal} disabled={saving} className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50">Cancel</button>
                <button type="submit" disabled={saving} className="rounded-lg bg-amber-500 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-50">
                  {saving ? "Processing..." : "Complete Transfer"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const Field = ({ label, children }) => (
  <div>
    <label className="mb-1.5 block text-sm font-medium text-gray-700">{label}</label>
    {children}
  </div>
);

export default AccountTransfer;