// SRNote.jsx — Firestore version
import React, { useEffect, useMemo, useState } from "react";
import {
  Search, RotateCcw, Save, X, Trash2, FileText, User, MapPin,
  CalendarDays, Package, RefreshCw, AlertCircle, CheckCircle2,
} from "lucide-react";
import { doc, collection, writeBatch, serverTimestamp, increment } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection, createDoc } from "../lib/firestore";

const SALES_RETURNS = COLLECTIONS?.SALES_RETURNS ?? "SalesReturns";
const SALES = COLLECTIONS?.SALES ?? "Sales";
const PRODUCT_STOCK = COLLECTIONS?.PRODUCT_STOCK ?? "ProductStock";

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

const emptyForm = {
  returnno: "", returndate: new Date().toISOString().slice(0, 10),
  invoiceno: "", customercode: "", customername: "", location: "", remark: "",
};

export default function SRNote() {
  const [form, setForm] = useState(emptyForm);
  const [invoiceLoading, setInvoiceLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [invoiceFound, setInvoiceFound] = useState(false);
  const [invoiceData, setInvoiceData] = useState(null);
  const [invoiceDocId, setInvoiceDocId] = useState("");
  const [items, setItems] = useState([]);
  const [invoiceError, setInvoiceError] = useState("");
  const [saveMessage, setSaveMessage] = useState("");
  const [saveError, setSaveError] = useState("");
  const [showInvoiceSearch, setShowInvoiceSearch] = useState(false);
  const [invoiceSearch, setInvoiceSearch] = useState("");
  const [invoiceResults, setInvoiceResults] = useState([]);

  useEffect(() => { getNextReturnNumber(); }, []);

  const getNextReturnNumber = async () => {
    try {
      const rows = await listCollection(SALES_RETURNS);
      let max = 0;
      rows.forEach((r) => {
        const m = String(pick(r, "ReturnNo", "returnno") || "").match(/(\d+)$/);
        if (m) { const n = Number(m[1]); if (n > max) max = n; }
      });
      setForm((p) => ({ ...p, returnno: `SRN${String(max + 1).padStart(5, "0")}` }));
    } catch (err) {
      console.error(err);
      setForm((p) => ({ ...p, returnno: `SRN-${Date.now()}` }));
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((p) => ({ ...p, [name]: value }));
  };

  const retrieveInvoice = async () => {
    const invoiceNo = form.invoiceno.trim();
    if (!invoiceNo) { setInvoiceError("Please enter an invoice number."); return; }

    setInvoiceLoading(true); setInvoiceError(""); setSaveMessage(""); setSaveError("");
    setInvoiceFound(false); setItems([]);

    try {
      // Find sale by Receipt
      const salesRows = await listCollection(SALES, { where: [["IsDelete", "==", 0]] });
      const sale = salesRows.find((s) => String(pick(s, "Receipt", "receipt")) === invoiceNo);

      if (!sale) throw new Error("Invoice not found.");

      setInvoiceDocId(sale.id);
      setInvoiceData(sale);

      // Load prior returns for this invoice
      const priorReturns = await listCollection(SALES_RETURNS, {
        where: [["Invoiceno", "==", invoiceNo], ["IsDelete", "==", 0]],
      });

      const returnedByProduct = {};
      priorReturns.forEach((r) => {
        (r.items || []).forEach((it) => {
          const code = it.productcode || it.ProductCode;
          if (!code) return;
          returnedByProduct[code] = (returnedByProduct[code] || 0) + toNum(it.qty || it.Qty);
        });
      });

      setForm((p) => ({
        ...p,
        invoiceno: invoiceNo,
        customercode: pick(sale, "CustomerCode", "customercode") || "",
        customername: pick(sale, "Customer", "CustomerName", "customername") || "",
        location: String(pick(sale, "LocationID", "location") || p.location),
      }));

      const items = Array.isArray(sale.itemsList) ? sale.itemsList : Array.isArray(sale.items) ? sale.items : [];

      const mapped = items.map((item, index) => {
        const code = pick(item, "ProductCode", "productcode", "ItemCode");
        const soldQty = toNum(pick(item, "Qty", "Quantity"));
        const alreadyRet = returnedByProduct[code] || 0;
        const avail = Math.max(soldQty - alreadyRet, 0);
        return {
          id: `${code}-${index}`,
          productcode: code,
          productname: pick(item, "Descrip", "ProductName", "productname", "ItemName") || "",
          soldqty: soldQty,
          returnedqty: alreadyRet,
          availableqty: avail,
          returnqty: 0,
          sellingprice: toNum(pick(item, "Price", "UnitPrice", "SellingPrice")),
          discountpercentage: toNum(pick(item, "FixedDiscountPercentage", "DiscountPercentage")),
          barcode: pick(item, "BarCode", "barcode") || "",
        };
      });

      setItems(mapped);
      setInvoiceFound(true);

      if (mapped.length === 0) setInvoiceError("Invoice was found, but there are no products available for return.");
    } catch (err) {
      console.error(err);
      setInvoiceFound(false); setInvoiceData(null); setItems([]);
      setInvoiceError(err.message || "Unable to retrieve invoice.");
    } finally {
      setInvoiceLoading(false);
    }
  };

  const searchInvoices = async (value) => {
    setInvoiceSearch(value);
    if (value.trim().length < 2) { setInvoiceResults([]); return; }
    try {
      const rows = await listCollection(SALES, { where: [["IsDelete", "==", 0]] });
      const q = value.trim().toLowerCase();
      const filtered = rows
        .filter((r) => {
          const receipt = String(pick(r, "Receipt", "receipt")).toLowerCase();
          const customer = String(pick(r, "Customer", "CustomerName")).toLowerCase();
          return receipt.includes(q) || customer.includes(q);
        })
        .slice(0, 20)
        .map((r) => ({
          Receipt: pick(r, "Receipt", "receipt"),
          Customer: pick(r, "Customer", "CustomerName"),
        }));
      setInvoiceResults(filtered);
    } catch (err) {
      console.error(err);
      setInvoiceResults([]);
    }
  };

  const selectInvoice = (invoice) => {
    setForm((p) => ({ ...p, invoiceno: invoice.Receipt }));
    setShowInvoiceSearch(false); setInvoiceSearch(""); setInvoiceResults([]);
  };

  const changeReturnQty = (id, value) => {
    let qty = Number(value);
    if (Number.isNaN(qty)) qty = 0;
    if (qty < 0) qty = 0;
    setItems((prev) => prev.map((item) => {
      if (item.id !== id) return item;
      if (qty > item.availableqty) qty = item.availableqty;
      return { ...item, returnqty: qty };
    }));
  };

  const removeItem = (id) => {
    setItems((prev) => prev.map((item) => item.id === id ? { ...item, returnqty: 0 } : item));
  };

  const totals = useMemo(() => {
    let totalQty = 0, grossAmount = 0, discountAmount = 0;
    items.forEach((item) => {
      const qty = Number(item.returnqty || 0);
      const price = Number(item.sellingprice || 0);
      const disc = Number(item.discountpercentage || 0);
      const gross = qty * price;
      const discount = (gross * disc) / 100;
      totalQty += qty; grossAmount += gross; discountAmount += discount;
    });
    return { totalQty, grossAmount, discountAmount, netAmount: grossAmount - discountAmount };
  }, [items]);

  const saveSalesReturn = async () => {
    setSaveMessage(""); setSaveError("");
    if (!form.returnno) { setSaveError("Return number is required."); return; }
    if (!form.invoiceno) { setSaveError("Invoice number is required."); return; }
    if (!form.location) { setSaveError("Please select a location."); return; }

    const selected = items.filter((it) => Number(it.returnqty || 0) > 0);
    if (selected.length === 0) { setSaveError("Please enter return quantity for at least one product."); return; }
    for (const it of selected) {
      if (it.returnqty > it.availableqty) { setSaveError(`${it.productname}: return qty exceeds available.`); return; }
    }

    setSaving(true);
    try {
      const details = selected.map((it) => ({
        productcode: it.productcode, productname: it.productname,
        qty: Number(it.returnqty), sellingprice: Number(it.sellingprice),
        discountpercentage: Number(it.discountpercentage || 0),
      }));

      const batch = writeBatch(db);
      const ref = doc(collection(db, SALES_RETURNS));
      batch.set(ref, {
        ReturnNo: form.returnno, ReturnDate: form.returndate,
        Invoiceno: form.invoiceno,
        CustomerCode: form.customercode || null,
        CustomerName: form.customername || null,
        LocationID: form.location,
        TotalQty: totals.totalQty, TotalAmount: totals.grossAmount,
        TotalDiscount: totals.discountAmount, NetAmount: totals.netAmount,
        Remark: form.remark || null,
        items: details,
        CreatedAt: serverTimestamp(),
        IsDelete: 0,
      });

      // Decrement stock per returned item
      const stockRows = await listCollection(PRODUCT_STOCK, {
        where: [["LocationID", "==", Number(form.location)], ["IsDelete", "==", 0]],
      });
      const stockMap = {};
      stockRows.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) stockMap[c] = s.id; });

      details.forEach((d) => {
        if (stockMap[d.productcode]) {
          batch.update(doc(db, PRODUCT_STOCK, stockMap[d.productcode]), {
            Stock: increment(-d.qty),
            UpdatedAt: serverTimestamp(),
          });
        }
      });

      await batch.commit();

      setSaveMessage(`Sales Return ${form.returnno} saved successfully.`);
      setItems([]); setInvoiceFound(false); setInvoiceData(null);
      setForm({ ...emptyForm, returnno: "" });
      await getNextReturnNumber();
    } catch (err) {
      console.error(err);
      setSaveError(err.message || "Failed to save Sales Return.");
    } finally {
      setSaving(false);
    }
  };

  const clearPage = async () => {
    setForm(emptyForm); setItems([]); setInvoiceData(null);
    setInvoiceFound(false); setInvoiceError(""); setSaveError(""); setSaveMessage("");
    await getNextReturnNumber();
  };

  const money = (v) => Number(v || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mx-auto max-w-[1500px] space-y-5">
        <div className="rounded-2xl bg-white shadow-sm border border-slate-200">
          <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex items-center gap-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-indigo-600 text-white shadow-sm"><RotateCcw size={24} /></div>
              <div>
                <h1 className="text-2xl font-bold text-slate-800">Sales Return Note</h1>
                <p className="text-sm text-slate-500">Return products from an existing sales invoice</p>
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={clearPage}
                className="inline-flex items-center gap-2 rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">
                <RefreshCw size={17} /> New
              </button>
              <button type="button" onClick={() => setShowInvoiceSearch(true)}
                className="inline-flex items-center gap-2 rounded-xl bg-slate-800 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-900">
                <Search size={17} /> Find Invoice
              </button>
            </div>
          </div>
        </div>

        {saveMessage && <div className="flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700"><CheckCircle2 size={20} />{saveMessage}</div>}
        {saveError && <div className="flex items-center gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700"><AlertCircle size={20} />{saveError}</div>}
        {invoiceError && <div className="flex items-center gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-medium text-amber-700"><AlertCircle size={20} />{invoiceError}</div>}

        <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-200 px-5 py-4">
            <h2 className="flex items-center gap-2 text-base font-bold text-slate-800"><FileText size={19} className="text-indigo-600" />Return Details</h2>
          </div>
          <div className="grid grid-cols-1 gap-4 p-5 md:grid-cols-2 xl:grid-cols-4">
            <div>
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Return No</label>
              <input value={form.returnno} readOnly className="w-full rounded-xl border border-slate-200 bg-slate-100 px-3.5 py-3 text-sm font-semibold text-slate-700 outline-none" />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Return Date</label>
              <div className="relative">
                <CalendarDays size={17} className="absolute left-3 top-3.5 text-slate-400" />
                <input type="date" name="returndate" value={form.returndate} onChange={handleChange}
                  className="w-full rounded-xl border border-slate-300 bg-white py-3 pl-10 pr-3 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
              </div>
            </div>
            <div className="xl:col-span-2">
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Original Invoice No</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <FileText size={17} className="absolute left-3 top-3.5 text-slate-400" />
                  <input name="invoiceno" value={form.invoiceno} onChange={handleChange}
                    onKeyDown={(e) => { if (e.key === "Enter") retrieveInvoice(); }}
                    placeholder="Enter invoice number"
                    className="w-full rounded-xl border border-slate-300 bg-white py-3 pl-10 pr-3 text-sm font-medium outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
                </div>
                <button type="button" onClick={retrieveInvoice} disabled={invoiceLoading}
                  className="inline-flex min-w-[110px] items-center justify-center gap-2 rounded-xl bg-indigo-600 px-4 py-3 text-sm font-bold text-white transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-60">
                  {invoiceLoading ? <><RefreshCw size={17} className="animate-spin" />Loading</> : <><Search size={17} />Retrieve</>}
                </button>
              </div>
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Customer Code</label>
              <div className="relative">
                <User size={17} className="absolute left-3 top-3.5 text-slate-400" />
                <input name="customercode" value={form.customercode} onChange={handleChange}
                  className="w-full rounded-xl border border-slate-300 py-3 pl-10 pr-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
              </div>
            </div>
            <div className="md:col-span-1 xl:col-span-2">
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Customer Name</label>
              <input name="customername" value={form.customername} onChange={handleChange}
                className="w-full rounded-xl border border-slate-300 px-3.5 py-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500">Location</label>
              <div className="relative">
                <MapPin size={17} className="absolute left-3 top-3.5 text-slate-400" />
                <input name="location" value={form.location} onChange={handleChange}
                  className="w-full rounded-xl border border-slate-300 px-3.5 py-3 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
              </div>
            </div>
          </div>
        </div>

        {invoiceFound && invoiceData && (
          <div className="rounded-2xl border border-indigo-100 bg-indigo-50/50 p-4">
            <div className="flex flex-wrap items-center gap-x-8 gap-y-3 text-sm">
              <div><span className="text-slate-500">Invoice:</span> <span className="font-bold text-slate-800">{form.invoiceno}</span></div>
              <div><span className="text-slate-500">Customer:</span> <span className="font-bold text-slate-800">{form.customername || "-"}</span></div>
              <div><span className="text-slate-500">Location:</span> <span className="font-bold text-slate-800">{form.location}</span></div>
              <div className="ml-auto inline-flex items-center gap-2 rounded-full bg-emerald-100 px-3 py-1.5 text-xs font-bold text-emerald-700"><CheckCircle2 size={15} />Invoice Loaded</div>
            </div>
          </div>
        )}

        <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="flex flex-col gap-2 border-b border-slate-200 px-5 py-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h2 className="flex items-center gap-2 text-base font-bold text-slate-800"><Package size={19} className="text-indigo-600" />Invoice Products</h2>
              <p className="mt-1 text-xs text-slate-500">Enter the quantity being returned for each product.</p>
            </div>
            {invoiceFound && <div className="rounded-lg bg-slate-100 px-3 py-2 text-xs font-semibold text-slate-600">{items.length} product{items.length !== 1 ? "s" : ""}</div>}
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-[1000px] w-full">
              <thead>
                <tr className="bg-slate-50 text-left">
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">#</th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">Product</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Sold Qty</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Already Returned</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Available</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Return Qty</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Price</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Discount</th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">Amount</th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase tracking-wide text-slate-500">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.length === 0 ? (
                  <tr><td colSpan="10" className="px-6 py-16 text-center">
                    <div className="mx-auto flex max-w-md flex-col items-center">
                      <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-slate-100"><Package size={25} className="text-slate-400" /></div>
                      <h3 className="font-bold text-slate-700">No invoice products</h3>
                      <p className="mt-1 text-sm text-slate-400">Enter an invoice number and click Retrieve.</p>
                    </div>
                  </td></tr>
                ) : items.map((item, index) => {
                  const qty = Number(item.returnqty || 0);
                  const gross = qty * Number(item.sellingprice || 0);
                  const discount = (gross * Number(item.discountpercentage || 0)) / 100;
                  const amount = gross - discount;
                  return (
                    <tr key={item.id} className={qty > 0 ? "bg-indigo-50/40" : "hover:bg-slate-50"}>
                      <td className="px-4 py-3 text-sm font-semibold text-slate-400">{index + 1}</td>
                      <td className="px-4 py-3">
                        <div className="font-semibold text-slate-800">{item.productname}</div>
                        <div className="mt-0.5 text-xs text-slate-400">{item.productcode}</div>
                      </td>
                      <td className="px-4 py-3 text-right text-sm font-semibold text-slate-700">{item.soldqty}</td>
                      <td className="px-4 py-3 text-right text-sm text-slate-500">{item.returnedqty}</td>
                      <td className="px-4 py-3 text-right"><span className="rounded-lg bg-emerald-50 px-2.5 py-1 text-sm font-bold text-emerald-700">{item.availableqty}</span></td>
                      <td className="px-4 py-3">
                        <input type="number" min="0" max={item.availableqty} step="0.01" value={item.returnqty}
                          onChange={(e) => changeReturnQty(item.id, e.target.value)}
                          className="ml-auto block w-28 rounded-lg border border-indigo-300 bg-white px-3 py-2 text-right text-sm font-bold text-indigo-700 outline-none focus:border-indigo-600 focus:ring-2 focus:ring-indigo-100" />
                      </td>
                      <td className="px-4 py-3 text-right text-sm text-slate-700">{money(item.sellingprice)}</td>
                      <td className="px-4 py-3 text-right text-sm text-slate-500">{item.discountpercentage}%</td>
                      <td className="px-4 py-3 text-right text-sm font-bold text-slate-800">{money(amount)}</td>
                      <td className="px-4 py-3 text-center">
                        <button type="button" onClick={() => removeItem(item.id)} disabled={qty === 0}
                          className="rounded-lg p-2 text-slate-400 transition hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-30">
                          <Trash2 size={17} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
          <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm lg:col-span-2">
            <label className="mb-2 block text-xs font-bold uppercase tracking-wide text-slate-500">Remark</label>
            <textarea name="remark" value={form.remark} onChange={handleChange} rows={5}
              placeholder="Enter return reason or additional remarks..."
              className="w-full resize-none rounded-xl border border-slate-300 px-4 py-3 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
            <div className="mt-4 rounded-xl bg-slate-50 p-4">
              <div className="flex gap-3">
                <AlertCircle size={18} className="mt-0.5 shrink-0 text-slate-400" />
                <p className="text-xs leading-5 text-slate-500">The returned quantity will be deducted from the stock of the selected location when the Sales Return is saved.</p>
              </div>
            </div>
          </div>
          <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
            <h2 className="mb-4 text-base font-bold text-slate-800">Return Summary</h2>
            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm">
                <span className="text-slate-500">Total Items</span>
                <span className="font-bold text-slate-800">{items.filter((it) => it.returnqty > 0).length}</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-slate-500">Total Quantity</span>
                <span className="font-bold text-slate-800">{totals.totalQty}</span>
              </div>
              <div className="border-t border-slate-100 pt-3">
                <div className="flex items-center justify-between text-sm">
                  <span className="text-slate-500">Gross Amount</span>
                  <span className="font-semibold text-slate-700">{money(totals.grossAmount)}</span>
                </div>
              </div>
              <div className="flex items-center justify-between text-sm">
                <span className="text-slate-500">Discount</span>
                <span className="font-semibold text-red-600">- {money(totals.discountAmount)}</span>
              </div>
              <div className="mt-3 rounded-xl bg-indigo-600 p-4 text-white">
                <div className="text-xs font-semibold uppercase tracking-wide text-indigo-200">Net Return Amount</div>
                <div className="mt-1 text-2xl font-black">{money(totals.netAmount)}</div>
              </div>
            </div>
            <div className="mt-5 grid grid-cols-2 gap-2">
              <button type="button" onClick={clearPage} disabled={saving}
                className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm font-bold text-slate-700 transition hover:bg-slate-50 disabled:opacity-50">
                <X size={17} /> Cancel
              </button>
              <button type="button" onClick={saveSalesReturn} disabled={saving || items.length === 0}
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-emerald-600 px-4 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50">
                {saving ? <><RefreshCw size={17} className="animate-spin" />Saving...</> : <><Save size={17} />Save SRN</>}
              </button>
            </div>
          </div>
        </div>
      </div>

      {showInvoiceSearch && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm">
          <div className="w-full max-w-2xl overflow-hidden rounded-2xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <div>
                <h2 className="font-bold text-slate-800">Find Invoice</h2>
                <p className="mt-0.5 text-xs text-slate-500">Search an existing sales invoice.</p>
              </div>
              <button type="button" onClick={() => { setShowInvoiceSearch(false); setInvoiceSearch(""); setInvoiceResults([]); }}
                className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><X size={20} /></button>
            </div>
            <div className="p-5">
              <div className="relative">
                <Search size={18} className="absolute left-3 top-3.5 text-slate-400" />
                <input autoFocus value={invoiceSearch} onChange={(e) => searchInvoices(e.target.value)}
                  placeholder="Search invoice number..."
                  className="w-full rounded-xl border border-slate-300 py-3 pl-10 pr-4 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100" />
              </div>
              <div className="mt-4 max-h-80 overflow-y-auto rounded-xl border border-slate-200">
                {invoiceResults.length === 0 ? (
                  <div className="px-5 py-10 text-center text-sm text-slate-400">Enter an invoice number to search.</div>
                ) : invoiceResults.map((invoice, index) => (
                  <button key={`${invoice.Receipt}-${index}`} type="button" onClick={() => selectInvoice(invoice)}
                    className="flex w-full items-center justify-between border-b border-slate-100 px-4 py-3 text-left last:border-b-0 hover:bg-indigo-50">
                    <div>
                      <div className="font-bold text-slate-800">{invoice.Receipt}</div>
                      <div className="mt-0.5 text-xs text-slate-500">{invoice.Customer || "Customer"}</div>
                    </div>
                    <Search size={16} className="text-slate-400" />
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}