// src/pos/Location.js
// ============================================================
// Location Master — React + Firestore
// ------------------------------------------------------------
// Reads:
//   • Location  (all non-deleted rows)
//   • Company   (for the picker modal + display fallback)
// Writes:
//   • Firestore (create / update / soft delete)
//
// Preserves:
//   • Full permission gating (View / Add / Edit / Delete)
//   • F12 company picker (with search + click-outside to close)
//   • Auto-generated 2-digit LocationCode ("01", "02", …)
//   • VAT / Active radio toggles (0/1 numbers)
//   • Search across Code / Name / Company / Mobile
//   • Soft delete (IsDelete=1, IsActive=0) matching the SQL
//     server behaviour
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import {
  listCollection,
  createDoc,
  updateDocById,
  softDeleteDoc,
  nextLocationCode,
} from "../lib/firestore";

const EMPTY_FORM = {
  CompanyID:    "",
  CompanyName:  "",
  LocationCode: "",
  LocationName: "",
  Address1:     "",
  Mobile:       "",
  Email:        "",
  IsVat:        "0",
  IsActive:     "1",
};

export default function Location() {
  const { user } = useContext(AuthContext);
  const { can, loading: permissionsLoading } = usePermissions();

  // ============================================================
  // PERMISSIONS
  // ============================================================
  const canViewLocation   = can("Location", "View");
  const canAddLocation    = can("Location", "Add");
  const canEditLocation   = can("Location", "Edit");
  const canDeleteLocation = can("Location", "Delete");

  // ============================================================
  // STATE
  // ============================================================
  const [form, setForm]             = useState(EMPTY_FORM);
  const [locations, setLocations]   = useState([]);
  const [companies, setCompanies]   = useState([]);
  const [editingId, setEditingId]   = useState(null);  // Firestore doc id

  const [loading, setLoading]               = useState(false);
  const [loadingCompanies, setLoadingCompanies] = useState(false);
  const [saving, setSaving]                 = useState(false);
  const [deletingId, setDeletingId]         = useState(null);

  const [search, setSearch]                 = useState("");
  const [companySearch, setCompanySearch]   = useState("");
  const [showCompanyModal, setShowCompanyModal] = useState(false);

  const [message, setMessage] = useState("");
  const [error,   setError]   = useState("");

  // ============================================================
  // LOAD COMPANIES (for the picker + name resolution)
  // ============================================================
  const loadCompanies = async () => {
    try {
      setLoadingCompanies(true);
      const rows = await listCollection("Company", {
        where: [["IsDelete", "==", 0]],
      });
      rows.sort((a, b) =>
        String(a.CompanyCode || "").localeCompare(String(b.CompanyCode || ""))
      );
      setCompanies(rows);
    } catch (err) {
      console.error("LOAD COMPANIES ERROR:", err);
      setError(err?.message || "Error loading companies.");
      setCompanies([]);
    } finally {
      setLoadingCompanies(false);
    }
  };

  // ============================================================
  // LOAD LOCATIONS
  // ============================================================
  const loadLocations = async () => {
    try {
      setLoading(true);
      setError("");

      const rows = await listCollection("Location", {
        where: [["IsDelete", "==", 0]],
      });
      rows.sort((a, b) =>
        String(a.LocationCode || "").localeCompare(String(b.LocationCode || ""))
      );
      setLocations(rows);
    } catch (err) {
      console.error("LOAD LOCATIONS ERROR:", err);
      setError(err?.message || "Error loading locations.");
      setLocations([]);
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // INITIAL LOAD
  // ============================================================
  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewLocation) return;
    (async () => {
      await Promise.all([loadLocations(), loadCompanies()]);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewLocation]);

  // ============================================================
  // COMPANY LOOKUP MAP  (CompanyID → display text)
  // ============================================================
  const companyByDocId = useMemo(() => {
    const m = new Map();
    for (const c of companies) {
      const text = c.CompanyCode
        ? `${c.CompanyCode} - ${c.CompanyName}`
        : c.CompanyName;
      m.set(c.id, text);
    }
    return m;
  }, [companies]);

  const resolveCompanyDisplay = (location) => {
    if (!location) return "";
    // Denormalized name takes priority (migration may have written it)
    if (location.CompanyName) return location.CompanyName;
    // Fall back to lookup by CompanyID
    return companyByDocId.get(location.CompanyID) || location.CompanyID || "";
  };

  // ============================================================
  // INPUT
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setMessage("");
    setError("");
  };

  const resetForm = () => {
    setForm(EMPTY_FORM);
    setEditingId(null);
    setCompanySearch("");
    setMessage("");
    setError("");
  };

  // ============================================================
  // GENERATE LOCATION CODE  ("01", "02", …)
  // ============================================================
  const generateLocationCode = async () => {
    try {
      const next = await nextLocationCode();
      return next || "01";
    } catch (err) {
      console.error("GENERATE LOCATION CODE ERROR:", err);
      return "01";
    }
  };

  // ============================================================
  // NEW LOCATION
  // ============================================================
  const handleNew = async () => {
    if (!canAddLocation) {
      setError("You do not have permission to create locations.");
      return;
    }
    try {
      setSaving(true);
      const newCode = await generateLocationCode();
      setForm({ ...EMPTY_FORM, LocationCode: newCode });
      setEditingId(null);
      setMessage(`New location code generated: ${newCode}`);
    } catch (err) {
      console.error("NEW LOCATION ERROR:", err);
      setForm(EMPTY_FORM);
      setEditingId(null);
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // COMPANY MODAL
  // ============================================================
  const openCompanyModal = async () => {
    // Read-only users cannot pick a company to save
    if (!canAddLocation && !canEditLocation) return;
    setCompanySearch("");
    if (companies.length === 0) await loadCompanies();
    setShowCompanyModal(true);
  };

  const handleCompanyKeyDown = async (e) => {
    if (e.key === "F12") {
      e.preventDefault();
      await openCompanyModal();
    }
  };

  const handleCompanySelect = (company) => {
    if (!company?.id) {
      setError("Selected company has no id.");
      return;
    }
    const display = company.CompanyCode
      ? `${company.CompanyCode} - ${company.CompanyName}`
      : company.CompanyName;

    setForm((prev) => ({
      ...prev,
      CompanyID:   company.id,
      CompanyName: display,
    }));
    setShowCompanyModal(false);
    setMessage("");
    setError("");
  };

  const clearCompany = () => {
    setForm((prev) => ({ ...prev, CompanyID: "", CompanyName: "" }));
  };

  // ============================================================
  // SAVE / UPDATE
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    // Permission gates
    if (editingId && !canEditLocation) {
      setError("You do not have permission to edit locations.");
      return;
    }
    if (!editingId && !canAddLocation) {
      setError("You do not have permission to create locations.");
      return;
    }

    // Validation
    if (!form.CompanyID || !String(form.CompanyID).trim()) {
      setError("Please select a Company before saving.");
      await openCompanyModal();
      return;
    }
    if (!form.LocationCode.trim()) {
      setError("Location Code is required.");
      return;
    }
    if (!form.LocationName.trim()) {
      setError("Location Name is required.");
      return;
    }

    try {
      setSaving(true);

      const payload = {
        CompanyID:    form.CompanyID.trim(),
        CompanyName:  form.CompanyName.trim(),  // denormalized for display
        LocationCode: form.LocationCode.trim(),
        LocationName: form.LocationName.trim(),
        Address1:     form.Address1.trim() || null,
        Mobile:       form.Mobile.trim()   || null,
        Email:        form.Email.trim()    || null,
        IsVat:        Number(form.IsVat),
        IsActive:     Number(form.IsActive),
        IsDelete:     0,
      };

      if (editingId) {
        await updateDocById("Location", editingId, payload, {
          username: user?.username,
        });
        setMessage("Location updated successfully.");
      } else {
        // Duplicate LocationCode check (only on create)
        const existing = await listCollection("Location", {
          where: [
            ["IsDelete", "==", 0],
            ["LocationCode", "==", payload.LocationCode],
          ],
          limit: 1,
        });
        if (existing.length > 0) {
          setError(`Location Code "${payload.LocationCode}" already exists.`);
          return;
        }

        await createDoc("Location", payload, { username: user?.username });
        setMessage("Location saved successfully.");
      }

      await loadLocations();
      resetForm();
    } catch (err) {
      console.error("SAVE LOCATION ERROR:", err);
      setError(err?.message || "Error saving location.");
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // EDIT
  // ============================================================
  const handleEdit = (location) => {
    if (!canEditLocation) {
      setError("You do not have permission to edit locations.");
      return;
    }
    if (!location?.id) {
      setError("Invalid LocationID.");
      return;
    }

    const companyID = location.CompanyID ?? "";
    const displayCompany = resolveCompanyDisplay(location);

    setEditingId(location.id);
    setForm({
      CompanyID:    String(companyID),
      CompanyName:  displayCompany || "",
      LocationCode: location.LocationCode || "",
      LocationName: location.LocationName || "",
      Address1:     location.Address1     || "",
      Mobile:       location.Mobile       || "",
      Email:        location.Email        || "",
      IsVat:        location.IsVat ? "1" : "0",
      IsActive:     location.IsActive === 0 ? "0" : "1",
    });
    setMessage(`Editing ${location.LocationCode}`);
    setError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE (soft — IsDelete=1, IsActive=0)
  // ============================================================
  const handleDelete = async (location) => {
    if (!canDeleteLocation) {
      setError("You do not have permission to delete locations.");
      return;
    }
    if (!location?.id) {
      setError("Invalid LocationID.");
      return;
    }

    const displayName =
      location.LocationName || location.LocationCode || "this location";
    if (!window.confirm(`Are you sure you want to delete "${displayName}"?`)) return;

    try {
      setDeletingId(location.id);
      setMessage("");
      setError("");

      await softDeleteDoc("Location", location.id, {
        username: user?.username,
      });
      setMessage("Location deleted successfully.");

      if (editingId === location.id) resetForm();
      await loadLocations();
    } catch (err) {
      console.error("DELETE LOCATION ERROR:", err);
      setError(err?.message || "Error deleting location.");
    } finally {
      setDeletingId(null);
    }
  };

  // ============================================================
  // SEARCH
  // ============================================================
  const searchText = search.trim().toLowerCase();
  const filteredLocations = useMemo(() => {
    if (!searchText) return locations;
    return locations.filter((location) => {
      const code       = String(location.LocationCode || "").toLowerCase();
      const name       = String(location.LocationName || "").toLowerCase();
      const companyID  = String(location.CompanyID    || "").toLowerCase();
      const companyTxt = resolveCompanyDisplay(location).toLowerCase();
      const address    = String(location.Address1     || "").toLowerCase();
      const mobile     = String(location.Mobile       || "").toLowerCase();
      return [code, name, companyID, companyTxt, address, mobile]
        .join(" ")
        .includes(searchText);
    });
  }, [locations, searchText]);

  // ============================================================
  // COMPANY SEARCH IN MODAL
  // ============================================================
  const filteredCompanies = useMemo(() => {
    const s = companySearch.trim().toLowerCase();
    if (!s) return companies;
    return companies.filter((c) => {
      const fields = [c.id, c.CompanyCode, c.CompanyName];
      return fields.join(" ").toLowerCase().includes(s);
    });
  }, [companies, companySearch]);

  // ============================================================
  // COMPUTED
  // ============================================================
  const isEditing    = Boolean(editingId);
  const saveAllowed  = (isEditing && canEditLocation) || (!isEditing && canAddLocation);
  const readOnlyEdit = isEditing && !canEditLocation;

  // ============================================================
  // ACCESS GATE
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewLocation) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Location Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Location</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="max-w-7xl mx-auto">

        {/* HEADER */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-5 mb-5">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-800">
                Location Master
              </h1>
              <p className="text-sm text-gray-500 mt-1">
                Create and manage company locations
              </p>
            </div>

            <div className="flex items-center gap-2">
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}
              {canAddLocation && (
                <button
                  type="button"
                  onClick={handleNew}
                  disabled={saving}
                  className="px-5 py-2.5 rounded-lg bg-blue-600 text-white font-semibold hover:bg-blue-700 disabled:opacity-50"
                >
                  + New
                </button>
              )}
              <button
                type="button"
                onClick={loadLocations}
                disabled={loading}
                className="px-5 py-2.5 rounded-lg bg-gray-700 text-white font-semibold hover:bg-gray-800 disabled:opacity-50"
              >
                {loading ? "Loading…" : "Refresh"}
              </button>
            </div>
          </div>
        </div>

        {/* MESSAGES */}
        {message && (
          <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
            ✓ {message}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            ⚠ {error}
          </div>
        )}

        {/* FORM */}
        <form
          onSubmit={handleSubmit}
          className="bg-white rounded-xl shadow-sm border border-gray-200 p-5 mb-5"
        >
          {isEditing && (
            <div className="mb-5 rounded-lg bg-yellow-50 border border-yellow-200 px-4 py-3">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-semibold text-yellow-800">Editing Location</p>
                  <p className="text-sm text-yellow-700">
                    Doc ID: {editingId.slice(0, 8)}…
                  </p>
                </div>
                <button
                  type="button"
                  onClick={resetForm}
                  className="text-sm font-semibold text-yellow-800 hover:text-yellow-900"
                >
                  Cancel Edit
                </button>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">

            {/* COMPANY (F12 picker) */}
            <div className="lg:col-span-2">
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Company <span className="text-red-500">*</span>
              </label>

              <div className="flex gap-2">
                <input
                  type="text"
                  name="CompanyID"
                  value={form.CompanyName || ""}
                  readOnly
                  onKeyDown={handleCompanyKeyDown}
                  onClick={openCompanyModal}
                  placeholder={
                    saveAllowed ? "Press F12 to select company" : "Company (read-only)"
                  }
                  className={`flex-1 border rounded-lg px-3 py-2.5 bg-white cursor-pointer outline-none focus:ring-2 ${
                    !form.CompanyID
                      ? "border-red-300 focus:ring-red-200"
                      : "border-gray-300 focus:ring-blue-200"
                  }`}
                />

                {saveAllowed && (
                  <>
                    <button
                      type="button"
                      onClick={openCompanyModal}
                      className="px-4 py-2.5 rounded-lg bg-blue-600 text-white font-semibold hover:bg-blue-700"
                      title="Select Company - F12"
                    >
                      F12
                    </button>
                    {form.CompanyID && (
                      <button
                        type="button"
                        onClick={clearCompany}
                        className="px-4 py-2.5 rounded-lg bg-red-500 text-white font-semibold hover:bg-red-600"
                      >
                        Clear
                      </button>
                    )}
                  </>
                )}
              </div>

              {!form.CompanyID && (
                <p className="text-xs text-red-500 mt-1">Please select a company.</p>
              )}
              {form.CompanyID && (
                <p className="text-xs text-green-600 mt-1">
                  Company ID: {form.CompanyID}
                </p>
              )}
            </div>

            {/* LOCATION CODE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Location Code <span className="text-red-500">*</span>
              </label>
              <div className="flex gap-2">
                <input
                  type="text"
                  name="LocationCode"
                  value={form.LocationCode}
                  onChange={handleChange}
                  maxLength={15}
                  disabled={isEditing}
                  placeholder="01"
                  className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200 disabled:bg-gray-100"
                />
                {!isEditing && canAddLocation && (
                  <button
                    type="button"
                    onClick={handleNew}
                    disabled={saving}
                    className="px-4 py-2.5 rounded-lg bg-indigo-600 text-white font-semibold hover:bg-indigo-700 disabled:opacity-50"
                  >
                    New
                  </button>
                )}
              </div>
            </div>

            {/* LOCATION NAME */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Location Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                name="LocationName"
                value={form.LocationName}
                onChange={handleChange}
                maxLength={50}
                placeholder="Location Name"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* ADDRESS */}
            <div className="lg:col-span-2">
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Address
              </label>
              <input
                type="text"
                name="Address1"
                value={form.Address1}
                onChange={handleChange}
                maxLength={50}
                placeholder="Address"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* MOBILE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Mobile
              </label>
              <input
                type="text"
                name="Mobile"
                value={form.Mobile}
                onChange={handleChange}
                maxLength={50}
                placeholder="Mobile Number"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* EMAIL */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Email
              </label>
              <input
                type="email"
                name="Email"
                value={form.Email}
                onChange={handleChange}
                maxLength={50}
                placeholder="Email"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            {/* VAT */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                VAT
              </label>
              <div className="flex gap-5">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsVat"
                    value="1"
                    checked={form.IsVat === "1"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Yes</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsVat"
                    value="0"
                    checked={form.IsVat === "0"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">No</span>
                </label>
              </div>
            </div>

            {/* ACTIVE */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Status
              </label>
              <div className="flex gap-5">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsActive"
                    value="1"
                    checked={form.IsActive === "1"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Active</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="IsActive"
                    value="0"
                    checked={form.IsActive === "0"}
                    onChange={handleChange}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">Inactive</span>
                </label>
              </div>
            </div>
          </div>

          {/* ACTION BUTTONS */}
          <div className="flex flex-wrap justify-end items-center gap-3 mt-6 pt-5 border-t border-gray-200">
            <button
              type="button"
              onClick={resetForm}
              disabled={saving}
              className="px-6 py-2.5 rounded-lg bg-gray-200 text-gray-800 font-semibold hover:bg-gray-300 disabled:opacity-50"
            >
              Clear
            </button>

            {saveAllowed && (
              <button
                type="submit"
                disabled={saving || !form.CompanyID}
                className={`px-7 py-2.5 rounded-lg text-white font-semibold ${
                  saving || !form.CompanyID
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-green-600 hover:bg-green-700"
                }`}
              >
                {saving
                  ? "Saving…"
                  : isEditing
                  ? "Update Location"
                  : "Save Location"}
              </button>
            )}

            {readOnlyEdit && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!isEditing && !canAddLocation && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You do not have permission to create new locations.
              </div>
            )}
          </div>
        </form>

        {/* SEARCH + LIST */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-5">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-5">
            <div>
              <h2 className="text-lg font-bold text-gray-800">Location List</h2>
              <p className="text-sm text-gray-500">
                {filteredLocations.length} location
                {filteredLocations.length === 1 ? "" : "s"}
              </p>
            </div>
            <div className="w-full md:w-96">
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search code, name, company, mobile…"
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full min-w-[900px] border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">#</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Code</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Location</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Company</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">Mobile</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">VAT</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">Status</th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">Actions</th>
                </tr>
              </thead>

              <tbody>
                {loading && locations.length === 0 ? (
                  <tr>
                    <td colSpan="8" className="text-center py-10 text-gray-500">
                      Loading locations…
                    </td>
                  </tr>
                ) : filteredLocations.length === 0 ? (
                  <tr>
                    <td colSpan="8" className="text-center py-10 text-gray-500">
                      No locations found.
                    </td>
                  </tr>
                ) : (
                  filteredLocations.map((location, index) => {
                    const isActive = location.IsActive !== 0;
                    const isVat    = location.IsVat === 1 || location.IsVat === true;

                    return (
                      <tr
                        key={location.id || index}
                        className="border-b border-gray-100 hover:bg-gray-50"
                      >
                        <td className="px-4 py-3 text-sm text-gray-600">
                          {index + 1}
                        </td>

                        <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                          {location.LocationCode || "-"}
                        </td>

                        <td className="px-4 py-3">
                          <div className="font-semibold text-gray-800">
                            {location.LocationName || "-"}
                          </div>
                          {location.Address1 && (
                            <div className="text-xs text-gray-500 mt-1">
                              {location.Address1}
                            </div>
                          )}
                        </td>

                        <td className="px-4 py-3 text-sm text-gray-700">
                          {resolveCompanyDisplay(location) || "-"}
                        </td>

                        <td className="px-4 py-3 text-sm text-gray-700">
                          {location.Mobile || "-"}
                        </td>

                        <td className="px-4 py-3 text-center">
                          <span
                            className={`inline-flex px-2.5 py-1 rounded-full text-xs font-semibold ${
                              isVat
                                ? "bg-blue-100 text-blue-700"
                                : "bg-gray-100 text-gray-600"
                            }`}
                          >
                            {isVat ? "VAT" : "Non-VAT"}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-center">
                          <span
                            className={`inline-flex px-2.5 py-1 rounded-full text-xs font-semibold ${
                              isActive
                                ? "bg-green-100 text-green-700"
                                : "bg-red-100 text-red-700"
                            }`}
                          >
                            {isActive ? "Active" : "Inactive"}
                          </span>
                        </td>

                        <td className="px-4 py-3">
                          <div className="flex justify-center gap-2">
                            {canEditLocation && (
                              <button
                                type="button"
                                onClick={() => handleEdit(location)}
                                disabled={deletingId !== null}
                                className="px-3 py-1.5 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700 disabled:opacity-50"
                              >
                                Edit
                              </button>
                            )}
                            {canDeleteLocation && (
                              <button
                                type="button"
                                onClick={() => handleDelete(location)}
                                disabled={deletingId !== null}
                                className="px-3 py-1.5 rounded-lg bg-red-600 text-white text-xs font-semibold hover:bg-red-700 disabled:opacity-50"
                              >
                                {deletingId === location.id ? "Deleting…" : "Delete"}
                              </button>
                            )}
                            {!canEditLocation && !canDeleteLocation && (
                              <span className="text-xs text-slate-400">
                                No actions
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>

      {/* ============================================================
          COMPANY PICKER MODAL
      ============================================================ */}
      {showCompanyModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
          onMouseDown={(e) => {
            if (e.target === e.currentTarget) setShowCompanyModal(false);
          }}
        >
          <div className="w-full max-w-4xl max-h-[90vh] bg-white rounded-xl shadow-2xl flex flex-col">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200">
              <div>
                <h2 className="text-xl font-bold text-gray-800">Select Company</h2>
                <p className="text-sm text-gray-500 mt-1">
                  Select a company for this location
                </p>
              </div>
              <button
                type="button"
                onClick={() => setShowCompanyModal(false)}
                className="w-9 h-9 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 text-xl"
              >
                ×
              </button>
            </div>

            <div className="p-4 border-b border-gray-200">
              <input
                type="text"
                autoFocus
                value={companySearch}
                onChange={(e) => setCompanySearch(e.target.value)}
                placeholder="Search Company ID, Code or Name…"
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              {loadingCompanies ? (
                <div className="text-center py-10 text-gray-500">
                  Loading companies…
                </div>
              ) : filteredCompanies.length === 0 ? (
                <div className="text-center py-10 text-gray-500">
                  No companies found.
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="bg-gray-50 border-b border-gray-200">
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company ID
                        </th>
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company Code
                        </th>
                        <th className="text-left px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Company Name
                        </th>
                        <th className="text-center px-4 py-3 text-xs font-bold text-gray-600 uppercase">
                          Action
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredCompanies.map((company, index) => (
                        <tr
                          key={company.id || index}
                          className="border-b border-gray-100 hover:bg-blue-50"
                        >
                          <td className="px-4 py-3 text-sm text-gray-500 font-mono">
                            {company.id.slice(0, 12)}…
                          </td>
                          <td className="px-4 py-3 text-sm font-semibold text-gray-800">
                            {company.CompanyCode || "-"}
                          </td>
                          <td className="px-4 py-3 text-sm text-gray-800">
                            {company.CompanyName || "-"}
                          </td>
                          <td className="px-4 py-3 text-center">
                            <button
                              type="button"
                              onClick={() => handleCompanySelect(company)}
                              className="px-4 py-1.5 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700"
                            >
                              Select
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            <div className="flex justify-end px-5 py-4 border-t border-gray-200">
              <button
                type="button"
                onClick={() => setShowCompanyModal(false)}
                className="px-5 py-2.5 rounded-lg bg-gray-200 text-gray-800 font-semibold hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}