// Stadjustapprove.jsx — Firestore version
import React, { useCallback, useContext, useEffect, useMemo, useState } from "react";
import { CheckCircle, Eye, RefreshCw, Search, X, Clock, Package, AlertTriangle } from "lucide-react";
import { doc, collection, serverTimestamp, increment } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection, getDocById, runFirestoreTransaction } from "../lib/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

const SESSIONS = COLLECTIONS?.STOCK_COUNT_SESSIONS ?? "StockCountSessions";
const ADJUSTMENTS = COLLECTIONS?.STOCK_ADJUSTMENTS ?? "StockAdjustments";
const PRODUCT_STOCK = COLLECTIONS?.PRODUCT_STOCK ?? "ProductStock";

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

function StockAdjustment() {
  const { user } = useContext(AuthContext);
  const [activeTab, setActiveTab] = useState("pending");
  const [pending, setPending] = useState([]);
  const [approved, setApproved] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [approving, setApproving] = useState(false);
  const [selected, setSelected] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [error, setError] = useState("");

  const username = user?.username || user?.Username || user?.U || "";

  const loadPending = useCallback(async () => {
    try {
      setLoading(true); setError("");
      const rows = await listCollection(SESSIONS, { where: [["Status", "==", "Finished"]] });
      setPending(
        rows.map((r) => {
          const items = Array.isArray(r.items) ? r.items : [];
          const systemStock = items.reduce((s, it) => s + toNum(it.SystemStock), 0);
          const physical = items.reduce((s, it) => s + toNum(it.StoreCount) + toNum(it.RackCount), 0);
          return {
            StockCountSessionID: r.id,
            SessionNo: pick(r, "SessionNo", "sessionNo"),
            Username: pick(r, "Username", "CreatedBy"),
            LocationID: pick(r, "LocationID", "locationID"),
            SystemStock: systemStock,
            PhysicalTotal: physical,
            Variance: physical - systemStock,
            CreatedDate: pick(r, "StartedAt", "CreatedAt"),
            Status: "Finished",
          };
        })
      );
    } catch (err) {
      console.error(err);
      setError(err.message || "Failed to load pending.");
      setPending([]);
    } finally { setLoading(false); }
  }, []);

  const loadApproved = useCallback(async () => {
    try {
      setLoading(true); setError("");
      const rows = await listCollection(ADJUSTMENTS, { where: [["IsDelete", "==", 0]] });
      setApproved(
        rows.map((r) => ({
          StockAdjustmentID: r.id,
          DocumentNo: pick(r, "DocumentNo", "documentNo"),
          Username: pick(r, "CreatedBy", "Username"),
          LocationID: pick(r, "LocationID", "locationID"),
          TotalQty: toNum(pick(r, "TotalQty", "totalQty")),
          ApprovedBy: pick(r, "ApprovedBy", "approvedBy"),
          ApprovedDate: pick(r, "ApprovedAt", "approvedAt"),
          Status: pick(r, "Status", "status") || "Approved",
        }))
      );
    } catch (err) {
      console.error(err);
      setError(err.message || "Failed to load approved.");
      setApproved([]);
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { loadPending(); loadApproved(); }, [loadPending, loadApproved]);

  const handleRefresh = async () => {
    if (activeTab === "pending") await loadPending();
    else await loadApproved();
  };

  const filteredRows = useMemo(() => {
    const src = activeTab === "pending" ? pending : approved;
    const k = search.trim().toLowerCase();
    if (!k) return src;
    return src.filter((r) =>
      [r.SessionNo, r.DocumentNo, r.Username, r.Status, r.StockAdjustmentID, r.StockCountSessionID]
        .some((v) => String(v || "").toLowerCase().includes(k))
    );
  }, [activeTab, pending, approved, search]);

  const viewPending = async (row) => {
    try {
      setLoading(true);
      const sessionData = await getDocById(SESSIONS, row.StockCountSessionID);
      if (!sessionData) throw new Error("Session not found");
      const items = Array.isArray(sessionData.items) ? sessionData.items : [];
      const details = items.map((it, i) => {
        const physical = toNum(it.StoreCount) + toNum(it.RackCount);
        return {
          StockCountSessionDetID: `${row.StockCountSessionID}-${i}`,
          ProductCode: it.ProductCode,
          ProductName: it.ProductName,
          SystemStock: toNum(it.SystemStock),
          StoreCount: toNum(it.StoreCount),
          RackCount: toNum(it.RackCount),
          PhysicalTotal: physical,
          Variance: physical - toNum(it.SystemStock),
          Status: "OK",
        };
      });
      setSelected({
        type: "pending",
        session: {
          StockCountSessionID: row.StockCountSessionID,
          SessionNo: row.SessionNo,
          TotalItems: details.length,
          CompletedItems: details.length,
          MissingItems: 0,
          TotalVariance: details.reduce((s, d) => s + d.Variance, 0),
        },
        details,
      });
      setShowModal(true);
    } catch (err) {
      alert(err.message || "Failed to load session");
    } finally { setLoading(false); }
  };

  const viewApproved = async (row) => {
    try {
      setLoading(true);
      const data = await getDocById(ADJUSTMENTS, row.StockAdjustmentID);
      if (!data) throw new Error("Adjustment not found");
      setSelected({
        type: "approved",
        adjustment: {
          StockAdjustmentID: row.StockAdjustmentID,
          DocumentNo: row.DocumentNo,
          LocationID: row.LocationID,
          TotalQty: row.TotalQty,
          Status: row.Status,
        },
        details: (data.items || []).map((it, i) => ({
          StockAdjustmentDetID: `${row.StockAdjustmentID}-${i}`,
          ProductCode: it.ProductCode,
          ProductName: it.ProductName,
          Stock: toNum(it.PreviousStock),
          Qty: toNum(it.AdjustmentQty),
          CostPrice: toNum(it.CostPrice),
          SellingPrice: toNum(it.SellingPrice),
        })),
      });
      setShowModal(true);
    } catch (err) {
      alert(err.message || "Failed to load adjustment");
    } finally { setLoading(false); }
  };

  const handleApprove = async (row) => {
    const sessionId = row.StockCountSessionID;
    if (!sessionId) { alert("Invalid session ID"); return; }
    if (!window.confirm(`Approve Session ${row.SessionNo}?\n\nThis will update actual stock.`)) return;

    try {
      setApproving(true); setError("");

      const result = await runFirestoreTransaction(async (tx) => {
        // 1. Read session fresh
        const sessionRef = doc(db, SESSIONS, sessionId);
        const sessionSnap = await tx.get(sessionRef);
        if (!sessionSnap.exists()) throw new Error("Session not found");
        const sessionData = sessionSnap.data();
        if (sessionData.Status !== "Finished") throw new Error("Session is not in Finished state");

        const items = Array.isArray(sessionData.items) ? sessionData.items : [];
        const locationID = Number(pick(sessionData, "LocationID", "locationID") || 0);

        // 2. Read all ProductStock docs for this location upfront
        const stockRows = await listCollection(PRODUCT_STOCK, {
          where: [["LocationID", "==", locationID], ["IsDelete", "==", 0]],
        });
        const stockMap = {};
        stockRows.forEach((s) => {
          const code = pick(s, "ProductCode", "productcode");
          if (code) stockMap[code] = s.id;
        });

        // 3. Apply stock increments
        const adjustmentItems = [];
        const totalQty = { value: 0 };
        items.forEach((it) => {
          const code = it.ProductCode;
          const systemStock = toNum(it.SystemStock);
          const physical = toNum(it.StoreCount) + toNum(it.RackCount);
          const variance = physical - systemStock;
          if (variance === 0) return;

          if (stockMap[code]) {
            tx.update(doc(db, PRODUCT_STOCK, stockMap[code]), {
              Stock: increment(variance),
              UpdatedAt: serverTimestamp(),
            });
          }

          adjustmentItems.push({
            ProductCode: code,
            ProductName: it.ProductName,
            PreviousStock: systemStock,
            AdjustmentQty: variance,
            CostPrice: 0, SellingPrice: 0,
          });
          totalQty.value += Math.abs(variance);
        });

        // 4. Create adjustment doc
        const existing = await listCollection(ADJUSTMENTS);
        let max = 0;
        existing.forEach((r) => {
          const m = String(pick(r, "DocumentNo", "documentNo") || "").match(/(\d+)$/);
          if (m) { const n = Number(m[1]); if (n > max) max = n; }
        });
        const docNo = `SA${String(max + 1).padStart(5, "0")}`;

        const adjRef = doc(collection(db, ADJUSTMENTS));
        tx.set(adjRef, {
          DocumentNo: docNo,
          LocationID: locationID,
          SourceSessionNo: row.SessionNo,
          TotalQty: totalQty.value,
          Status: "Approved",
          items: adjustmentItems,
          ApprovedBy: username,
          ApprovedAt: serverTimestamp(),
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        // 5. Mark session approved
        tx.update(sessionRef, {
          Status: "Approved",
          ApprovedAt: serverTimestamp(),
          ApprovedBy: username,
          StockAdjustmentID: adjRef.id,
        });

        return { docNo };
      });

      alert(`Stock count approved. Adjustment ${result.docNo} created.`);
      setShowModal(false); setSelected(null);
      await loadPending();
      await loadApproved();
    } catch (err) {
      console.error(err);
      alert(err.message || "Approval failed");
    } finally { setApproving(false); }
  };

  const getStatusClass = (s) => {
    const v = String(s || "").toLowerCase();
    if (v === "approved") return "bg-green-100 text-green-700";
    if (v === "finished" || v === "pending") return "bg-yellow-100 text-yellow-700";
    if (v === "rejected") return "bg-red-100 text-red-700";
    return "bg-gray-100 text-gray-700";
  };

  const formatDate = (v) => {
    if (!v) return "-";
    if (typeof v === "string") return v;
    if (v.toDate) return v.toDate().toLocaleString();
    if (typeof v.seconds === "number") return new Date(v.seconds * 1000).toLocaleString();
    const d = new Date(v); return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleString();
  };

  const closeModal = () => { if (approving) return; setShowModal(false); setSelected(null); };

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="max-w-[1600px] mx-auto">
        <div className="bg-white rounded-2xl shadow-sm border p-5 mb-5">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Stock Adjustment</h1>
              <p className="text-gray-500 text-sm mt-1">Review stock counts and approve physical stock adjustments.</p>
            </div>
            <button type="button" onClick={handleRefresh} disabled={loading}
              className="flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg bg-gray-800 text-white hover:bg-gray-900 disabled:opacity-50">
              <RefreshCw size={18} className={loading ? "animate-spin" : ""} /> Refresh
            </button>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border mb-5">
          <div className="flex border-b">
            <button type="button" onClick={() => { setActiveTab("pending"); setSearch(""); }}
              className={"flex items-center gap-2 px-6 py-4 font-medium border-b-2 " + (activeTab === "pending" ? "border-yellow-500 text-yellow-600" : "border-transparent text-gray-500")}>
              <Clock size={18} /> Pending Approval
              <span className="px-2 py-0.5 rounded-full bg-yellow-100 text-yellow-700 text-xs">{pending.length}</span>
            </button>
            <button type="button" onClick={() => { setActiveTab("approved"); setSearch(""); }}
              className={"flex items-center gap-2 px-6 py-4 font-medium border-b-2 " + (activeTab === "approved" ? "border-green-500 text-green-600" : "border-transparent text-gray-500")}>
              <CheckCircle size={18} /> Approved
              <span className="px-2 py-0.5 rounded-full bg-green-100 text-green-700 text-xs">{approved.length}</span>
            </button>
          </div>
          <div className="p-4">
            <div className="relative">
              <Search size={19} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input type="text" value={search} onChange={(e) => setSearch(e.target.value)}
                placeholder={activeTab === "pending" ? "Search session number, username..." : "Search document number..."}
                className="w-full pl-10 pr-4 py-2.5 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
          </div>
        </div>

        {error && <div className="mb-5 p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 flex items-center gap-3"><AlertTriangle size={20} /><span>{error}</span></div>}

        <div className="bg-white rounded-2xl shadow-sm border overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50">
                {activeTab === "pending" ? (
                  <tr>
                    <th className="px-4 py-4 text-left">#</th>
                    <th className="px-4 py-4 text-left">Session No</th>
                    <th className="px-4 py-4 text-left">Username</th>
                    <th className="px-4 py-4 text-left">Location</th>
                    <th className="px-4 py-4 text-right">System Qty</th>
                    <th className="px-4 py-4 text-right">Physical Qty</th>
                    <th className="px-4 py-4 text-right">Variance</th>
                    <th className="px-4 py-4 text-left">Created</th>
                    <th className="px-4 py-4 text-center">Status</th>
                    <th className="px-4 py-4 text-center">Action</th>
                  </tr>
                ) : (
                  <tr>
                    <th className="px-4 py-4 text-left">#</th>
                    <th className="px-4 py-4 text-left">Document No</th>
                    <th className="px-4 py-4 text-left">Username</th>
                    <th className="px-4 py-4 text-left">Location</th>
                    <th className="px-4 py-4 text-right">Total Qty</th>
                    <th className="px-4 py-4 text-left">Approved By</th>
                    <th className="px-4 py-4 text-left">Approved Date</th>
                    <th className="px-4 py-4 text-center">Status</th>
                    <th className="px-4 py-4 text-center">Action</th>
                  </tr>
                )}
              </thead>
              <tbody>
                {loading ? (
                  <tr><td colSpan="10" className="py-12 text-center"><RefreshCw size={28} className="mx-auto animate-spin text-gray-400" /><p className="mt-3 text-gray-500">Loading...</p></td></tr>
                ) : filteredRows.length === 0 ? (
                  <tr><td colSpan="10" className="py-12 text-center text-gray-500"><Package size={40} className="mx-auto text-gray-300" /><p className="mt-3">No records found.</p></td></tr>
                ) : filteredRows.map((row, i) => (
                  <tr key={activeTab === "pending" ? row.StockCountSessionID : row.StockAdjustmentID} className="border-t hover:bg-gray-50">
                    <td className="px-4 py-4">{i + 1}</td>
                    {activeTab === "pending" ? (
                      <>
                        <td className="px-4 py-4 font-semibold">{row.SessionNo}</td>
                        <td className="px-4 py-4">{row.Username || "-"}</td>
                        <td className="px-4 py-4">{row.LocationID ?? "-"}</td>
                        <td className="px-4 py-4 text-right">{row.SystemStock ?? 0}</td>
                        <td className="px-4 py-4 text-right">{row.PhysicalTotal ?? 0}</td>
                        <td className="px-4 py-4 text-right font-semibold">{row.Variance ?? 0}</td>
                        <td className="px-4 py-4">{formatDate(row.CreatedDate)}</td>
                        <td className="px-4 py-4 text-center"><span className={"px-3 py-1 rounded-full text-xs font-semibold " + getStatusClass(row.Status)}>{row.Status}</span></td>
                        <td className="px-4 py-4">
                          <div className="flex justify-center gap-2">
                            <button type="button" onClick={() => viewPending(row)} className="p-2 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-100" title="View"><Eye size={18} /></button>
                            <button type="button" onClick={() => handleApprove(row)} disabled={approving} className="p-2 rounded-lg bg-green-50 text-green-600 hover:bg-green-100 disabled:opacity-50" title="Approve"><CheckCircle size={18} /></button>
                          </div>
                        </td>
                      </>
                    ) : (
                      <>
                        <td className="px-4 py-4 font-semibold">{row.DocumentNo}</td>
                        <td className="px-4 py-4">{row.Username || "-"}</td>
                        <td className="px-4 py-4">{row.LocationID ?? "-"}</td>
                        <td className="px-4 py-4 text-right font-semibold">{row.TotalQty ?? 0}</td>
                        <td className="px-4 py-4">{row.ApprovedBy || "-"}</td>
                        <td className="px-4 py-4">{formatDate(row.ApprovedDate)}</td>
                        <td className="px-4 py-4 text-center"><span className={"px-3 py-1 rounded-full text-xs font-semibold " + getStatusClass(row.Status)}>{row.Status}</span></td>
                        <td className="px-4 py-4 text-center">
                          <button type="button" onClick={() => viewApproved(row)} className="p-2 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-100"><Eye size={18} /></button>
                        </td>
                      </>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {showModal && selected?.type === "pending" && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col">
            <div className="flex items-center justify-between px-6 py-4 border-b">
              <div>
                <h2 className="text-xl font-bold text-gray-800">Stock Count Approval</h2>
                <p className="text-sm text-gray-500 mt-1">Session: {selected.session.SessionNo}</p>
              </div>
              <button type="button" onClick={closeModal} disabled={approving} className="p-2 rounded-lg hover:bg-gray-100"><X size={22} /></button>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3 p-5 bg-gray-50 border-b">
              {[
                ["Session ID", selected.session.StockCountSessionID],
                ["Total Items", selected.session.TotalItems],
                ["Completed", selected.session.CompletedItems],
                ["Missing", selected.session.MissingItems],
                ["Variance", selected.session.TotalVariance],
              ].map(([l, v]) => (
                <div key={l} className="bg-white border rounded-xl p-3">
                  <div className="text-xs text-gray-500">{l}</div>
                  <div className="font-bold text-gray-800 mt-1">{v ?? "-"}</div>
                </div>
              ))}
            </div>
            <div className="flex-1 overflow-auto p-5">
              <div className="overflow-x-auto border rounded-xl">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 sticky top-0">
                    <tr>
                      <th className="px-3 py-3 text-left">#</th>
                      <th className="px-3 py-3 text-left">Product Code</th>
                      <th className="px-3 py-3 text-left">Product Name</th>
                      <th className="px-3 py-3 text-right">System</th>
                      <th className="px-3 py-3 text-right">Store</th>
                      <th className="px-3 py-3 text-right">Rack</th>
                      <th className="px-3 py-3 text-right">Physical</th>
                      <th className="px-3 py-3 text-right">Variance</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selected.details.map((item, i) => (
                      <tr key={item.StockCountSessionDetID || i} className="border-t hover:bg-gray-50">
                        <td className="px-3 py-3">{i + 1}</td>
                        <td className="px-3 py-3 font-medium">{item.ProductCode || "-"}</td>
                        <td className="px-3 py-3">{item.ProductName || "-"}</td>
                        <td className="px-3 py-3 text-right">{item.SystemStock ?? 0}</td>
                        <td className="px-3 py-3 text-right">{item.StoreCount ?? 0}</td>
                        <td className="px-3 py-3 text-right">{item.RackCount ?? 0}</td>
                        <td className="px-3 py-3 text-right font-semibold">{item.PhysicalTotal}</td>
                        <td className={"px-3 py-3 text-right font-bold " + (item.Variance > 0 ? "text-green-600" : item.Variance < 0 ? "text-red-600" : "text-gray-600")}>{item.Variance}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            <div className="flex items-center justify-between gap-3 px-6 py-4 border-t bg-gray-50">
              <div className="text-sm text-gray-500">Approval will update actual stock.</div>
              <div className="flex gap-3">
                <button type="button" onClick={closeModal} disabled={approving} className="px-5 py-2.5 rounded-lg border bg-white hover:bg-gray-100">Close</button>
                <button type="button" onClick={() => handleApprove(selected.session)} disabled={approving}
                  className="px-5 py-2.5 rounded-lg bg-green-600 text-white hover:bg-green-700 disabled:opacity-50 flex items-center gap-2">
                  {approving ? <><RefreshCw size={18} className="animate-spin" />Approving...</> : <><CheckCircle size={18} />Approve</>}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showModal && selected?.type === "approved" && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col">
            <div className="flex items-center justify-between px-6 py-4 border-b">
              <div>
                <h2 className="text-xl font-bold text-gray-800">Approved Stock Adjustment</h2>
                <p className="text-sm text-gray-500 mt-1">Document: {selected.adjustment.DocumentNo}</p>
              </div>
              <button type="button" onClick={closeModal} className="p-2 rounded-lg hover:bg-gray-100"><X size={22} /></button>
            </div>
            <div className="flex-1 overflow-auto p-5">
              <div className="overflow-x-auto border rounded-xl">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 sticky top-0">
                    <tr>
                      <th className="px-3 py-3 text-left">#</th>
                      <th className="px-3 py-3 text-left">Product Code</th>
                      <th className="px-3 py-3 text-left">Product Name</th>
                      <th className="px-3 py-3 text-right">Previous Stock</th>
                      <th className="px-3 py-3 text-right">Adjustment Qty</th>
                      <th className="px-3 py-3 text-right">New Stock</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selected.details.map((it, i) => (
                      <tr key={it.StockAdjustmentDetID || i} className="border-t hover:bg-gray-50">
                        <td className="px-3 py-3">{i + 1}</td>
                        <td className="px-3 py-3 font-medium">{it.ProductCode || "-"}</td>
                        <td className="px-3 py-3">{it.ProductName || "-"}</td>
                        <td className="px-3 py-3 text-right">{it.Stock}</td>
                        <td className={"px-3 py-3 text-right font-semibold " + (it.Qty > 0 ? "text-green-600" : it.Qty < 0 ? "text-red-600" : "")}>{it.Qty}</td>
                        <td className="px-3 py-3 text-right font-bold">{it.Stock + it.Qty}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            <div className="flex justify-end px-6 py-4 border-t bg-gray-50">
              <button type="button" onClick={closeModal} className="px-5 py-2.5 rounded-lg border bg-white hover:bg-gray-100">Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default StockAdjustment;