// Accounts.jsx
import React, { useEffect, useMemo, useState } from "react";
import {
  Plus, Download, Upload, Search, Filter, ChevronDown, X, Pencil,
  RefreshCw, CheckCircle2, User, Building2, CreditCard, WalletCards, Receipt,
} from "lucide-react";
import {
  COLLECTIONS,
  listCollection,
  createDoc,
  updateDocById,
} from "../lib/firestore.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";
import { useContext } from "react";

const ACCOUNT_TYPES = [
  { value: "cash", label: "Cash on Hand", icon: WalletCards },
  { value: "card_sale", label: "Card Sale", icon: CreditCard },
  { value: "third_party_check", label: "Third-Party Check", icon: Receipt },
  { value: "bank_account", label: "Bank Account", icon: Building2 },
  { value: "credit_card", label: "Credit Card", icon: CreditCard },
  { value: "expenses", label: "Expenses", icon: WalletCards },
  { value: "active_account", label: "Active Account", icon: Building2 },
  { value: "owner_account", label: "Owner Account", icon: User },
  { value: "other", label: "Other", icon: WalletCards },
];

const formatMoney = (value) => {
  const amount = Number(value || 0);
  return `Rs.${amount.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

const getTypeLabel = (type) => ACCOUNT_TYPES.find((t) => t.value === type)?.label || type || "-";

/* ---------- SUMMARY COMPUTED CLIENT-SIDE ---------- */
const computeReconciliation = (accounts, transactions) => {
  const byAccount = new Map();

  accounts.forEach((a) => {
    byAccount.set(a.id, {
      accountId: a.id,
      accountName: a.AccountName || a.name || "",
      accountType: a.AccountType || a.type || "",
      storedBalance: Number(a.StoredBalance ?? a.balance ?? 0),
      calculatedBalance: 0,
      totalCredits: 0,
      totalDebits: 0,
      variance: 0,
    });
  });

  transactions.forEach((t) => {
    const acctId = t.AccountID;
    if (!acctId || !byAccount.has(acctId)) return;
    const row = byAccount.get(acctId);
    row.totalCredits += Number(t.Credit || 0);
    row.totalDebits += Number(t.Debit || 0);
  });

  const rows = Array.from(byAccount.values()).map((r) => {
    r.calculatedBalance = r.totalCredits - r.totalDebits;
    r.variance = r.storedBalance - r.calculatedBalance;
    return r;
  });

  const withVariance = rows.filter((r) => Math.abs(r.variance) > 0.01).length;
  const totalVariance = rows.reduce((s, r) => s + r.variance, 0);

  return { rows, summary: { totalAccounts: rows.length, withVariance, totalVariance } };
};

/* ---------- ACCOUNT MODAL ---------- */
function AccountModal({ account, onClose, onSave, saving }) {
  const [form, setForm] = useState({
    name: account?.AccountName || account?.name || "",
    type: account?.AccountType || account?.type || "",
    detailType: account?.DetailType || account?.detailType || "",
    description: account?.Description || account?.description || "",
  });
  const isEdit = Boolean(account);
  const set = (k, v) => setForm((p) => ({ ...p, [k]: v }));

  const submit = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return alert("Please enter account name.");
    if (!form.type) return alert("Please select account type.");
    onSave(form);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-[510px] rounded-2xl bg-white shadow-2xl">
        <div className="flex items-start justify-between px-6 pt-6">
          <div>
            <h2 className="text-xl font-bold text-gray-900">{isEdit ? "Edit Account" : "Create New Account"}</h2>
            <p className="mt-1 text-sm text-gray-500">{isEdit ? "Update account information" : "Add a new account to your system"}</p>
          </div>
          <button onClick={onClose} className="rounded-full p-1 text-gray-500 hover:bg-gray-100"><X size={20} /></button>
        </div>

        <form onSubmit={submit} className="space-y-5 px-6 pb-6 pt-5">
          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">Account Name</label>
            <input type="text" value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="Enter account name" className="h-11 w-full rounded-xl border border-gray-200 px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100" />
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">Account Type</label>
            <div className="relative">
              <select value={form.type} onChange={(e) => set("type", e.target.value)} className="h-11 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100">
                <option value="">Select account type</option>
                {ACCOUNT_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
              </select>
              <ChevronDown size={18} className="pointer-events-none absolute right-3 top-3 text-gray-500" />
            </div>
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">Detail Type</label>
            <input type="text" value={form.detailType} onChange={(e) => set("detailType", e.target.value)} placeholder="e.g. Current, Savings, Cash" className="h-11 w-full rounded-xl border border-gray-200 px-3 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100" />
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium text-gray-900">Description</label>
            <textarea value={form.description} onChange={(e) => set("description", e.target.value)} placeholder="Account description" rows={3} className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-orange-500 focus:ring-2 focus:ring-orange-100" />
          </div>

          <div className="flex justify-end gap-2 pt-1">
            <button type="button" onClick={onClose} disabled={saving} className="rounded-xl border border-gray-200 px-5 py-2.5 text-sm font-medium text-gray-800 hover:bg-gray-50">Cancel</button>
            <button type="submit" disabled={saving} className="rounded-xl bg-orange-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-orange-600 disabled:opacity-60">
              {saving ? "Saving..." : isEdit ? "Update Account" : "Create Account"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/* ---------- MAIN PAGE ---------- */
export default function Accounts() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [activeTab, setActiveTab] = useState("accounts");
  const [accounts, setAccounts] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [editingAccount, setEditingAccount] = useState(null);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  /* ---------- LOAD ACCOUNTS ---------- */
  const loadAccounts = async () => {
    try {
      setLoading(true);
      setError("");
      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });
      setAccounts(
        rows.map((a) => ({
          id: a.id,
          name: a.AccountName || a.name || "",
          type: a.AccountType || a.type || "",
          detailType: a.DetailType || a.detailType || "",
          description: a.Description || a.description || "",
          balance: Number(a.StoredBalance ?? a.balance ?? 0),
          status: a.IsActive === false ? "Inactive" : "Active",
          createdBy: a.CreatedBy || "-",
          typeLabel: getTypeLabel(a.AccountType || a.type),
        }))
      );
    } catch (err) {
      console.error("LOAD ACCOUNTS ERROR:", err);
      setError(err.message || "Cannot load accounts");
    } finally {
      setLoading(false);
    }
  };

  /* ---------- LOAD TRANSACTIONS (for reconciliation) ---------- */
  const loadTransactions = async () => {
    try {
      setLoading(true);
      const rows = await listCollection(COLLECTIONS.ACCOUNT_TRANSACTIONS, {
        where: [["IsDelete", "==", 0]],
      });
      setTransactions(rows);
    } catch (err) {
      console.error("LOAD TRANSACTIONS ERROR:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAccounts();
  }, []);

  /* ---------- RECONCILIATION SUMMARY ---------- */
  const reconciliation = useMemo(
    () => computeReconciliation(accounts, transactions),
    [accounts, transactions]
  );

  /* ---------- FILTER ---------- */
  const filteredAccounts = useMemo(() => {
    const q = search.trim().toLowerCase();
    return accounts.filter((a) => {
      const matchesSearch = !q || a.name?.toLowerCase().includes(q) || a.typeLabel?.toLowerCase().includes(q) || a.detailType?.toLowerCase().includes(q);
      const matchesType = typeFilter === "all" || a.type === typeFilter;
      return matchesSearch && matchesType;
    });
  }, [accounts, search, typeFilter]);

  /* ---------- CREATE ---------- */
  const createAccount = async (form) => {
    try {
      setSaving(true);
      await createDoc(
        COLLECTIONS.ACCOUNTS,
        {
          AccountName: form.name.trim(),
          AccountType: form.type,
          DetailType: form.detailType.trim(),
          Description: form.description.trim(),
          StoredBalance: 0,
          IsActive: true,
        },
        { username }
      );
      setShowModal(false);
      await loadAccounts();
      alert("Account created successfully.");
    } catch (err) {
      console.error("CREATE ACCOUNT ERROR:", err);
      alert(err.message || "Failed to create account");
    } finally {
      setSaving(false);
    }
  };

  /* ---------- UPDATE ---------- */
  const updateAccount = async (form) => {
    if (!editingAccount) return;
    try {
      setSaving(true);
      await updateDocById(
        COLLECTIONS.ACCOUNTS,
        editingAccount.id,
        {
          AccountName: form.name.trim(),
          AccountType: form.type,
          DetailType: form.detailType.trim(),
          Description: form.description.trim(),
        },
        { username }
      );
      setShowModal(false);
      setEditingAccount(null);
      await loadAccounts();
      alert("Account updated successfully.");
    } catch (err) {
      console.error("UPDATE ACCOUNT ERROR:", err);
      alert(err.message || "Failed to update account");
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAccount = async (form) => {
    if (editingAccount) await updateAccount(form);
    else await createAccount(form);
  };

  /* ---------- TOGGLE STATUS ---------- */
  const toggleStatus = async (account) => {
    const isActive = account.status !== "Active";
    try {
      setLoading(true);
      await updateDocById(
        COLLECTIONS.ACCOUNTS,
        account.id,
        { IsActive: isActive },
        { username }
      );
      await loadAccounts();
    } catch (err) {
      console.error("STATUS ERROR:", err);
      alert(err.message || "Failed to update status");
      setLoading(false);
    }
  };

  /* ---------- TEMPLATE ---------- */
  const downloadTemplate = () => {
    const csv = [
      "Account Name,Account Type,Detail Type,Description",
      "HNB OUTLET,Bank Account,HNB BANK,Main bank account",
      "Cash Counter 01,Cash on Hand,Cash,Main cash counter",
      "Main Bank Account,Bank Account,Savings,Business bank",
    ].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "accounts_template.csv";
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    alert(`Selected file: ${file.name}\n\nCSV/Excel import can be wired to a Cloud Function.`);
    event.target.value = "";
  };

  /* ---------- TAB ---------- */
  const changeTab = (tab) => {
    setActiveTab(tab);
    if (tab === "reconciliation" && transactions.length === 0) {
      loadTransactions();
    }
  };

  /* ---------- RENDER ---------- */
  return (
    <div className="min-h-screen bg-white px-6 py-6 md:px-8">
      <div>
        <h1 className="text-3xl font-bold text-gray-950">Accounts Management</h1>
        <p className="mt-1 text-base text-gray-500">Manage your business accounts and track balances</p>
      </div>

      <div className="mt-5 inline-flex rounded-xl bg-gray-100 p-1">
        <button onClick={() => changeTab("accounts")} className={`rounded-lg px-4 py-2 text-sm font-medium ${activeTab === "accounts" ? "bg-white text-gray-950 shadow-sm" : "text-gray-600 hover:text-gray-900"}`}>Accounts</button>
        <button onClick={() => changeTab("reconciliation")} className={`rounded-lg px-4 py-2 text-sm font-medium ${activeTab === "reconciliation" ? "bg-white text-gray-950 shadow-sm" : "text-gray-600 hover:text-gray-900"}`}>Account Reconciliation</button>
      </div>

      {error && (
        <div className="mt-5 flex items-center justify-between rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          <span>{error}</span>
          <button onClick={() => setError("")} className="font-bold">×</button>
        </div>
      )}

      {activeTab === "accounts" && (
        <>
          <div className="mt-6 flex flex-wrap gap-2">
            <button onClick={downloadTemplate} className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50"><Download size={17} /> Download Template</button>
            <label className="flex cursor-pointer items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50">
              <Upload size={17} /> Import Accounts
              <input type="file" accept=".csv,.xlsx,.xls" onChange={handleImport} className="hidden" />
            </label>
            <button onClick={() => { setEditingAccount(null); setShowModal(true); }} className="flex items-center gap-2 rounded-xl bg-orange-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-orange-600"><Plus size={18} /> Add Account</button>
            <button onClick={loadAccounts} disabled={loading} className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-medium hover:bg-gray-50 disabled:opacity-50"><RefreshCw size={17} className={loading ? "animate-spin" : ""} /> Refresh</button>
          </div>

          <div className="mt-6 rounded-2xl border border-gray-300 bg-white p-6 shadow-sm">
            <div className="mb-6 flex items-center gap-2"><Filter size={21} /><h2 className="text-xl font-bold text-gray-900">Filters</h2></div>
            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="mb-2 block text-sm font-medium text-gray-900">Account Type</label>
                <div className="relative">
                  <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} className="h-11 w-full appearance-none rounded-xl border border-gray-200 bg-white px-3 text-sm outline-none focus:border-orange-500">
                    <option value="all">All Types</option>
                    {ACCOUNT_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
                  </select>
                  <ChevronDown size={18} className="pointer-events-none absolute right-3 top-3 text-gray-500" />
                </div>
              </div>
              <div>
                <label className="mb-2 block text-sm font-medium text-gray-900">Search</label>
                <div className="relative">
                  <Search size={18} className="absolute left-3 top-3 text-gray-500" />
                  <input type="text" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search accounts..." className="h-11 w-full rounded-xl border border-gray-200 pl-10 pr-3 text-sm outline-none focus:border-orange-500" />
                </div>
              </div>
            </div>
          </div>

          <div className="mt-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {ACCOUNT_TYPES.map((type) => {
              const typeAccounts = accounts.filter((a) => a.type === type.value);
              const total = typeAccounts.reduce((s, a) => s + Number(a.balance || 0), 0);
              const Icon = type.icon;
              return (
                <div key={type.value} className="rounded-xl border border-gray-300 bg-white p-6 shadow-sm">
                  <div className="mb-3 flex items-center justify-between">
                    <span className="text-sm font-medium text-gray-800">{type.label}</span>
                    <Icon size={18} className="text-gray-500" />
                  </div>
                  <div className={`text-2xl font-bold ${total < 0 ? "text-red-600" : "text-gray-950"}`}>{formatMoney(total)}</div>
                  <div className="mt-1 text-xs text-gray-500">{typeAccounts.length} {typeAccounts.length === 1 ? "account" : "accounts"}</div>
                </div>
              );
            })}
          </div>

          <div className="mt-6">
            {loading && accounts.length === 0 ? (
              <div className="rounded-2xl border border-gray-300 bg-white py-16 text-center">
                <RefreshCw size={30} className="mx-auto animate-spin text-orange-500" />
                <p className="mt-3 text-sm text-gray-500">Loading accounts...</p>
              </div>
            ) : (
              <div className="rounded-2xl border border-gray-300 bg-white shadow-sm">
                <div className="px-6 pb-3 pt-6">
                  <h2 className="text-2xl font-bold text-gray-950">All Accounts ({filteredAccounts.length})</h2>
                  <p className="mt-1 text-sm text-gray-500">View and manage all your business accounts</p>
                </div>
                <div className="overflow-x-auto px-5 pb-5">
                  <table className="w-full min-w-[1000px] border-collapse">
                    <thead><tr className="border-b border-gray-300">
                      {["Account Name", "Type", "Bank/Details", "Balance", "Status", "Created By", "Actions"].map((h) => (
                        <th key={h} className="px-4 py-4 text-left text-sm font-medium text-gray-600">{h}</th>
                      ))}
                    </tr></thead>
                    <tbody>
                      {filteredAccounts.map((a) => (
                        <tr key={a.id} className="border-b border-gray-200 hover:bg-gray-50">
                          <td className="px-4 py-4">
                            <div className="font-medium text-gray-900">{a.name}</div>
                            {a.description && <div className="mt-1 max-w-[280px] truncate text-xs text-gray-500">{a.description}</div>}
                          </td>
                          <td className="px-4 py-4"><span className="rounded-full bg-gray-100 px-3 py-1 text-xs font-medium text-gray-700">{a.typeLabel}</span></td>
                          <td className="px-4 py-4 text-sm text-gray-700">{a.detailType || "-"}</td>
                          <td className={`px-4 py-4 text-sm font-semibold ${Number(a.balance) < 0 ? "text-red-600" : "text-gray-900"}`}>{formatMoney(a.balance)}</td>
                          <td className="px-4 py-4"><span className={`rounded-full px-3 py-1 text-xs font-medium ${a.status === "Active" ? "bg-orange-500 text-white" : "bg-gray-200 text-gray-600"}`}>{a.status}</span></td>
                          <td className="px-4 py-4 text-sm italic text-gray-500">{a.createdBy}</td>
                          <td className="px-4 py-4">
                            <div className="flex items-center gap-2">
                              <button onClick={() => { setEditingAccount(a); setShowModal(true); }} title="Edit" className="rounded-xl border border-gray-200 p-2 hover:bg-gray-100"><Pencil size={16} /></button>
                              <button onClick={() => toggleStatus(a)} className="rounded-xl border border-gray-200 px-3 py-2 text-xs font-medium hover:bg-gray-100">{a.status === "Active" ? "Deactivate" : "Activate"}</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                      {filteredAccounts.length === 0 && <tr><td colSpan="7" className="px-4 py-12 text-center text-sm text-gray-500">No accounts found.</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        </>
      )}

      {activeTab === "reconciliation" && (
        <div className="mt-6">
          <div className="flex flex-col justify-between gap-4 md:flex-row md:items-center">
            <div>
              <h1 className="text-2xl font-bold text-gray-950">Account Balance Reconciliation</h1>
              <p className="text-sm text-gray-500">Compare stored vs calculated account balances</p>
            </div>
            <button onClick={() => { loadAccounts(); loadTransactions(); }} disabled={loading} className="flex items-center justify-center gap-2 rounded-xl border border-gray-200 bg-white px-5 py-2.5 text-sm font-medium hover:bg-gray-50 disabled:opacity-50">
              <RefreshCw size={17} className={loading ? "animate-spin" : ""} /> Refresh
            </button>
          </div>

          <div className="mt-5 grid gap-4 md:grid-cols-3">
            <div className="rounded-xl border border-gray-300 bg-white p-6"><p className="text-sm text-gray-500">Total Accounts</p><p className="mt-2 text-3xl font-bold text-gray-950">{reconciliation.summary.totalAccounts}</p></div>
            <div className="rounded-xl border border-gray-300 bg-white p-6"><p className="text-sm text-gray-500">With Variance</p><p className="mt-2 text-3xl font-bold text-orange-500">{reconciliation.summary.withVariance}</p></div>
            <div className="rounded-xl border border-gray-300 bg-white p-6"><p className="text-sm text-gray-500">Total Variance</p><p className="mt-2 text-3xl font-bold text-red-500">{formatMoney(reconciliation.summary.totalVariance)}</p></div>
          </div>

          <div className={`mt-4 flex items-center gap-2 rounded-xl border px-4 py-4 text-sm ${reconciliation.summary.withVariance === 0 ? "border-green-200 bg-green-50 text-green-700" : "border-red-200 bg-red-50 text-red-700"}`}>
            <CheckCircle2 size={19} />
            {reconciliation.summary.withVariance === 0 ? "All account balances reconciled!" : `${reconciliation.summary.withVariance} account(s) have balance variance.`}
          </div>

          <div className="mt-4 rounded-2xl border border-gray-300 bg-white shadow-sm">
            <div className="px-6 pb-4 pt-6">
              <h2 className="text-2xl font-bold text-gray-950">Account Balance Comparison</h2>
              <p className="mt-1 text-sm text-gray-500">Formula: Credits - Debits = Calculated Balance</p>
            </div>
            <div className="overflow-x-auto px-5 pb-5">
              <table className="w-full min-w-[1000px] border-collapse">
                <thead><tr className="border-b border-gray-300">
                  {["Account", "Stored Balance", "Calculated Balance", "Variance", "Total Credits", "Total Debits"].map((h) => (
                    <th key={h} className="px-4 py-4 text-left text-sm font-medium text-gray-600">{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {reconciliation.rows.map((r) => (
                    <tr key={r.accountId} className="border-b border-gray-200 hover:bg-gray-50">
                      <td className="px-4 py-4"><div className="font-medium text-gray-900">{r.accountName}</div><div className="text-xs text-gray-500">{r.accountType}</div></td>
                      <td className="px-4 py-4 font-mono text-sm">{formatMoney(r.storedBalance)}</td>
                      <td className="px-4 py-4 font-mono text-sm">{formatMoney(r.calculatedBalance)}</td>
                      <td className={`px-4 py-4 font-mono text-sm font-medium ${Math.abs(r.variance) > 0.01 ? "text-red-500" : "text-green-600"}`}>{formatMoney(r.variance)}</td>
                      <td className="px-4 py-4 font-mono text-sm text-green-600">{formatMoney(r.totalCredits)}</td>
                      <td className="px-4 py-4 font-mono text-sm text-red-500">{formatMoney(r.totalDebits)}</td>
                    </tr>
                  ))}
                  {reconciliation.rows.length === 0 && <tr><td colSpan="6" className="px-4 py-12 text-center text-sm text-gray-500">No reconciliation data found.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {showModal && (
        <AccountModal
          account={editingAccount}
          onClose={() => { if (saving) return; setShowModal(false); setEditingAccount(null); }}
          onSave={handleSaveAccount}
          saving={saving}
        />
      )}
    </div>
  );
}