// ProductPriceChange.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - Products           (product master; doc ID is the canonical
//                         product ID used as InvProductMasterID)
//   - ProductPriceTiers  (quantity-based price tiers; each doc
//                         references a Products doc via ProductID)
//
// Two behavioural notes:
//   1. Tier edits (CashPrice / CreditPrice) now persist on blur.
//      The original only updated React state and never saved.
//   2. addTier now receives the correct product from the row
//      that triggered it. The original always used products[0].
// ============================================================

import React, { useContext, useEffect, useMemo, useState } from "react";

import {
  doc,
  updateDoc,
  serverTimestamp,
} from "firebase/firestore";

import { db } from "../firebase.js";
import {
  COLLECTIONS,
  listCollection,
  createDoc,
} from "../lib/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS  (rename here if your Firestore differs)
====================================================== */

const PRODUCTS = COLLECTIONS?.PRODUCTS ?? "Products";
const PRODUCT_PRICE_TIERS =
  COLLECTIONS?.PRODUCT_PRICE_TIERS ?? "ProductPriceTiers";

/* ======================================================
   HELPERS
====================================================== */

const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

/* ======================================================
   NORMALIZERS
====================================================== */

// Products: use doc id as the canonical ID field, so the rest of
// the component can keep referring to product.InvProductMasterID.
const normalizeProduct = (raw) => ({
  ...raw,
  InvProductMasterID: raw.InvProductMasterID ?? raw.id ?? "",
  ProductCode: pick(raw, "ProductCode", "productcode") || "",
  ProductName: pick(raw, "ProductName", "productname") || "",
  BarCode: pick(raw, "BarCode", "barcode") || "",
  CostPrice: toNumber(pick(raw, "CostPrice", "costprice")),
  SellingPrice: toNumber(
    pick(raw, "SellingPrice", "sellingprice")
  ),
  WholesalePrice: toNumber(
    pick(raw, "WholesalePrice", "wholesaleprice")
  ),
  MaximumPrice: toNumber(
    pick(raw, "MaximumPrice", "maximumprice")
  ),
  Stock: toNumber(pick(raw, "Stock", "stock")),
  LocationID: pick(raw, "LocationID", "locationID", "locationid") || "",
});

const normalizeTier = (raw) => ({
  ...raw,
  ProductPriceTierID:
    raw.ProductPriceTierID ?? raw.id ?? "",
  ProductID: raw.ProductID ?? raw.productID ?? "",
  ProductCode: pick(raw, "ProductCode", "productcode") || "",
  QtyFrom: toNumber(pick(raw, "QtyFrom", "qtyFrom", "qtyfrom")),
  QtyTo:
    raw.QtyTo === null || raw.QtyTo === undefined
      ? null
      : toNumber(pick(raw, "QtyTo", "qtyTo", "qtyto")),
  CashPrice: toNumber(pick(raw, "CashPrice", "cashPrice", "cashprice")),
  CreditPrice: toNumber(
    pick(raw, "CreditPrice", "creditPrice", "creditprice")
  ),
});

/* ======================================================
   COMPONENT
====================================================== */

export default function ProductPriceChange() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const [priceMode, setPriceMode] = useState("retail");
  const [tiers, setTiers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  /* ======================================================
     LOAD PRODUCTS + TIERS  (Firestore)
  ====================================================== */

  const loadProducts = async () => {
    try {
      setLoading(true);
      setMessage("");

      const [productRows, tierRows] = await Promise.all([
        listCollection(PRODUCTS, {
          where: [["IsDelete", "==", 0]],
        }),
        listCollection(PRODUCT_PRICE_TIERS),
      ]);

      setProducts(productRows.map(normalizeProduct));
      setTiers(tierRows.map(normalizeTier));
    } catch (error) {
      console.error("PRODUCT PRICE LOAD ERROR:", error);
      setMessage(
        error.message ||
          "Unable to load products from Firestore."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProducts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ======================================================
     UPDATE PRODUCT FIELD
     ------------------------------------------------------
     Persists on blur, matching the original UX. Uses the
     product's Firestore doc id (stored on the normalized row
     as InvProductMasterID).
  ====================================================== */

  const updateProduct = async (productID, field, value) => {
    if (!productID) return;

    try {
      await updateDoc(doc(db, PRODUCTS, String(productID)), {
        [field]: Number(value) || 0,
        UpdatedAt: serverTimestamp(),
        UpdatedBy: username,
      });
    } catch (error) {
      console.error("PRICE UPDATE ERROR:", error);
      setMessage(
        error.message || "Unable to save product price."
      );
    }
  };

  /* ======================================================
     UPDATE TIER  (local state — instant feedback)
  ====================================================== */

  const updateTier = (tierID, field, value) => {
    setTiers((prev) =>
      prev.map((tier) =>
        tier.ProductPriceTierID === tierID
          ? { ...tier, [field]: value }
          : tier
      )
    );
  };

  /* ======================================================
     SAVE TIER  (persist on blur)
     ------------------------------------------------------
     The original file updated React state on every change
     but never persisted anything — tier edits were silently
     lost on refresh. This closes that gap.
  ====================================================== */

  const saveTier = async (tierID, field, value) => {
    if (!tierID) return;

    try {
      await updateDoc(
        doc(db, PRODUCT_PRICE_TIERS, String(tierID)),
        {
          [field]: Number(value) || 0,
          UpdatedAt: serverTimestamp(),
          UpdatedBy: username,
        }
      );
    } catch (error) {
      console.error("TIER UPDATE ERROR:", error);
      setMessage(
        error.message || "Unable to save tier price."
      );
    }
  };

  /* ======================================================
     ADD TIER
     ------------------------------------------------------
     Fixed: the original always used products[0], so every
     click added a tier to the first product regardless of
     which row was clicked. Now the correct product is passed
     in from the row.
  ====================================================== */

  const addTier = async (product) => {
    if (!product) {
      setMessage("Select a product first.");
      return;
    }

    try {
      await createDoc(
        PRODUCT_PRICE_TIERS,
        {
          ProductID: product.InvProductMasterID,
          ProductCode: product.ProductCode,
          QtyFrom: 1,
          QtyTo: 99,
          CashPrice: product.SellingPrice || 0,
          CreditPrice: product.SellingPrice || 0,
          LocationID: product.LocationID || 0,

          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        },
        { username }
      );

      await loadProducts();
    } catch (error) {
      console.error("ADD TIER ERROR:", error);
      setMessage(
        error.message || "Unable to add price tier."
      );
    }
  };

  /* ======================================================
     FILTER
  ====================================================== */

  const filteredProducts = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return products;

    return products.filter((product) => {
      const text = `${product.ProductCode || ""} ${
        product.ProductName || ""
      } ${product.BarCode || ""}`.toLowerCase();

      return text.includes(q);
    });
  }, [products, search]);

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-white p-6">
      {/* HEADER */}
      <div className="flex items-start justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">
            Product Management
          </h1>
          <p className="text-gray-500 mt-1">
            Manage your product inventory
          </p>
        </div>

        <div className="flex gap-2">
          <button className="px-5 py-3 border border-gray-200 rounded-xl bg-white hover:bg-gray-50">
            ✎ Quick Edit Mode
          </button>

          <button className="px-5 py-3 rounded-xl bg-orange-500 text-white font-semibold">
            ◇ Exit Price Change
          </button>

          <button className="px-5 py-3 rounded-xl bg-orange-500 text-white font-semibold">
            ＋ Add Product
          </button>

          <button className="px-5 py-3 rounded-xl border border-gray-200 bg-white">
            ⚖ Scale Download
          </button>
        </div>
      </div>

      {message && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {message}
        </div>
      )}

      {/* MAIN CARD */}
      <div className="border border-gray-300 rounded-2xl overflow-hidden">
        {/* CARD HEADER */}
        <div className="p-6">
          <div className="flex items-center justify-between">
            <h2 className="text-2xl font-bold">
              📦 Products ({filteredProducts.length})
            </h2>

            <button
              onClick={loadProducts}
              disabled={loading}
              className="px-4 py-2 rounded-lg border border-gray-200 hover:bg-gray-50 disabled:opacity-50 text-sm font-semibold"
            >
              {loading ? "Refreshing..." : "↻ Refresh"}
            </button>
          </div>

          {/* SEARCH */}
          <div className="flex gap-4 mt-5">
            <div className="relative w-96">
              <span className="absolute left-3 top-3 text-gray-400">
                🔍
              </span>
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search products..."
                className="w-full border border-gray-200 rounded-xl pl-10 pr-4 py-3 outline-none focus:ring-2 focus:ring-orange-400"
              />
            </div>

            <select className="border border-gray-200 rounded-xl px-5 py-3">
              <option>All Types</option>
            </select>

            <select className="border border-gray-200 rounded-xl px-5 py-3">
              <option>All</option>
            </select>
          </div>

          {/* TABS */}
          <div className="flex justify-between items-center mt-6">
            <div className="flex gap-2">
              <button
                onClick={() => setPriceMode("retail")}
                className={`px-5 py-3 rounded-xl font-semibold ${
                  priceMode === "retail"
                    ? "bg-orange-500 text-white"
                    : "border bg-white"
                }`}
              >
                Retail Prices
              </button>

              <button
                onClick={() => setPriceMode("wholesale")}
                className={`px-5 py-3 rounded-xl font-semibold ${
                  priceMode === "wholesale"
                    ? "bg-orange-500 text-white"
                    : "border bg-white"
                }`}
              >
                Wholesale Prices
              </button>
            </div>

            <button className="px-5 py-3 rounded-xl bg-gray-100">
              📄 Excel Bulk Update
            </button>
          </div>

          {/* MODE MESSAGE */}
          <div className="mt-4 bg-orange-50 border-l-4 border-orange-500 p-3 text-sm text-gray-600">
            {priceMode === "retail"
              ? "Retail Mode - Changes sync to Wholesale"
              : "Wholesale Price Mode"}
          </div>
        </div>

        {/* TABLE */}
        <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
          <table className="min-w-[1500px] w-full border-collapse">
            <thead>
              {/* GROUP HEADERS */}
              <tr>
                <th
                  colSpan="6"
                  className="bg-blue-100 border px-4 py-4 text-gray-600"
                >
                  Product Master
                </th>

                <th
                  colSpan="4"
                  className="bg-green-100 border px-4 py-4 text-gray-600"
                >
                  Quantity Price Tiers
                </th>
              </tr>

              {/* COLUMN HEADERS */}
              <tr>
                <th className="bg-blue-50 border p-3">Code</th>
                <th className="bg-blue-50 border p-3">Product</th>
                <th className="bg-blue-50 border p-3">Cost</th>
                <th className="bg-blue-50 border p-3">MRP</th>
                <th className="bg-blue-50 border p-3">Stock</th>
                <th className="bg-blue-50 border p-3">
                  Q1 Base
                  <div className="text-xs">Cash / Credit</div>
                </th>
                <th className="bg-green-50 border p-3">
                  Q100
                  <div className="text-xs">Cash / Credit</div>
                </th>
                <th className="bg-green-50 border p-3">
                  Q5000
                  <div className="text-xs">Cash / Credit</div>
                </th>
                <th className="bg-green-50 border p-3">
                  Q10000
                  <div className="text-xs">Cash / Credit</div>
                </th>
                <th className="bg-green-50 border p-3">＋</th>
              </tr>
            </thead>

            <tbody>
              {loading && products.length === 0 ? (
                <tr>
                  <td
                    colSpan="10"
                    className="px-4 py-16 text-center text-gray-500"
                  >
                    Loading products...
                  </td>
                </tr>
              ) : filteredProducts.length === 0 ? (
                <tr>
                  <td
                    colSpan="10"
                    className="px-4 py-16 text-center text-gray-500"
                  >
                    No products found.
                  </td>
                </tr>
              ) : (
                filteredProducts.map((product) => {
                  const productTiers = tiers.filter(
                    (t) =>
                      String(t.ProductID) ===
                      String(product.InvProductMasterID)
                  );

                  return (
                    <tr
                      key={product.InvProductMasterID}
                      className="hover:bg-gray-50"
                    >
                      {/* CODE */}
                      <td className="border p-3">
                        {product.ProductCode}
                      </td>

                      {/* PRODUCT */}
                      <td className="border p-3">
                        <div className="font-medium">
                          {product.ProductName}
                        </div>
                      </td>

                      {/* COST */}
                      <td className="border p-2">
                        <input
                          type="number"
                          defaultValue={product.CostPrice}
                          onBlur={(e) =>
                            updateProduct(
                              product.InvProductMasterID,
                              "CostPrice",
                              e.target.value
                            )
                          }
                          className="w-20 border rounded p-2 text-right"
                        />
                      </td>

                      {/* MRP */}
                      <td className="border p-2">
                        <input
                          type="number"
                          defaultValue={
                            product.MaximumPrice ||
                            product.SellingPrice
                          }
                          onBlur={(e) =>
                            updateProduct(
                              product.InvProductMasterID,
                              "MaximumPrice",
                              e.target.value
                            )
                          }
                          className="w-20 border rounded p-2 text-right"
                        />
                      </td>

                      {/* STOCK */}
                      <td className="border p-3 text-center">
                        {product.Stock ?? "-"}
                      </td>

                      {/* BASE PRICE */}
                      <td className="border p-2">
                        <div className="flex gap-1">
                          <input
                            type="number"
                            value={product.SellingPrice || ""}
                            onChange={(e) => {
                              const value = e.target.value;

                              setProducts((prev) =>
                                prev.map((p) =>
                                  p.InvProductMasterID ===
                                  product.InvProductMasterID
                                    ? {
                                        ...p,
                                        SellingPrice: value,
                                      }
                                    : p
                                )
                              );
                            }}
                            onBlur={(e) =>
                              updateProduct(
                                product.InvProductMasterID,
                                "SellingPrice",
                                e.target.value
                              )
                            }
                            className="w-20 border rounded p-2"
                          />

                          <input
                            type="number"
                            value={product.WholesalePrice || ""}
                            readOnly={priceMode === "retail"}
                            onBlur={(e) =>
                              updateProduct(
                                product.InvProductMasterID,
                                "WholesalePrice",
                                e.target.value
                              )
                            }
                            onChange={(e) => {
                              const value = e.target.value;

                              setProducts((prev) =>
                                prev.map((p) =>
                                  p.InvProductMasterID ===
                                  product.InvProductMasterID
                                    ? {
                                        ...p,
                                        WholesalePrice: value,
                                      }
                                    : p
                                )
                              );
                            }}
                            className="w-20 border rounded p-2"
                          />
                        </div>
                      </td>

                      {/* Q100 */}
                      <TierCell
                        tiers={productTiers}
                        quantity={100}
                        updateTier={updateTier}
                        saveTier={saveTier}
                      />

                      {/* Q5000 */}
                      <TierCell
                        tiers={productTiers}
                        quantity={5000}
                        updateTier={updateTier}
                        saveTier={saveTier}
                      />

                      {/* Q10000 */}
                      <TierCell
                        tiers={productTiers}
                        quantity={10000}
                        updateTier={updateTier}
                        saveTier={saveTier}
                      />

                      {/* ADD */}
                      <td className="border text-center">
                        <button
                          onClick={() => addTier(product)}
                          className="text-orange-500 text-2xl font-bold"
                          title="Add a new tier for this product"
                        >
                          +
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* ======================================================
   TIER CELL
====================================================== */

function TierCell({ tiers, quantity, updateTier, saveTier }) {
  const tier = tiers.find(
    (t) =>
      Number(t.QtyFrom) <= quantity &&
      (t.QtyTo == null || Number(t.QtyTo) >= quantity)
  );

  if (!tier) {
    return (
      <td className="border text-center text-gray-400 text-sm">
        —
      </td>
    );
  }

  return (
    <td className="border p-2">
      <div className="flex gap-1">
        <input
          type="number"
          value={tier.CashPrice}
          onChange={(e) =>
            updateTier(
              tier.ProductPriceTierID,
              "CashPrice",
              e.target.value
            )
          }
          onBlur={(e) =>
            saveTier(
              tier.ProductPriceTierID,
              "CashPrice",
              e.target.value
            )
          }
          className="w-20 border rounded p-2"
        />

        <input
          type="number"
          value={tier.CreditPrice}
          onChange={(e) =>
            updateTier(
              tier.ProductPriceTierID,
              "CreditPrice",
              e.target.value
            )
          }
          onBlur={(e) =>
            saveTier(
              tier.ProductPriceTierID,
              "CreditPrice",
              e.target.value
            )
          }
          className="w-20 border rounded p-2"
        />
      </div>
    </td>
  );
}