// src/pos/customer.js
// ============================================================
// Customer Master — React + Firestore
// ------------------------------------------------------------
// Reads:  Firestore  Customers collection
// Writes: Firestore  Customers collection (no server needed)
//
// Preserves:
//   • Full permission gating (View / Add / Edit / Delete)
//   • Field-level permission masking on Credit Limit
//   • Retail / Wholesale customer type
//   • Cash / Credit pay type
//   • Auto-generated CUS##### code when empty
//   • Soft "deactivate" on delete (IsActive = 0, doc kept)
// ============================================================
import React, { useContext, useEffect, useState } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import {
  listCollection,
  createDoc,
  updateDocById,
} from "../lib/firestore";

const emptyForm = {
  customerCode:   "",
  customerName:   "",
  customerType:   "",
  nic:            "",
  phone:          "",
  address:        "",
  email:          "",
  creditLimit:    "0",
  openingBalance: "0",
  PayType:        "",
};

export default function Customer() {
  const { user } = useContext(AuthContext);
  const { can, canField, loading: permissionsLoading } = usePermissions();

  // =====================================================
  // PERMISSIONS
  // =====================================================
  const canViewCustomer      = can("Customer", "View");
  const canAddCustomer       = can("Customer", "Add");
  const canEditCustomer      = can("Customer", "Edit");
  const canDeleteCustomer    = can("Customer", "Delete");
  const canViewCreditLimit   = canField("Customer", "CreditLimit");

  // =====================================================
  // STATE
  // =====================================================
  const [customers, setCustomers] = useState([]);
  const [form, setForm]           = useState(emptyForm);
  const [editingId, setEditingId] = useState(null); // Firestore doc id
  const [search, setSearch]       = useState("");

  const [loading, setLoading] = useState(false);
  const [saving, setSaving]   = useState(false);
  const [message, setMessage] = useState("");
  const [error,   setError]   = useState("");

  // =====================================================
  // LOAD CUSTOMERS
  // =====================================================
  const loadCustomers = async () => {
    try {
      setLoading(true);
      setError("");

      const rows = await listCollection("Customers", {
        where: [["IsDelete", "==", 0]],
      });

      rows.sort((a, b) =>
        String(a.CustomerName || "").localeCompare(String(b.CustomerName || ""))
      );
      setCustomers(rows);
    } catch (err) {
      console.error("LOAD CUSTOMERS ERROR:", err);
      setError(err?.message || "Unable to load customers.");
      setCustomers([]);
    } finally {
      setLoading(false);
    }
  };

  // =====================================================
  // INITIAL LOAD
  // =====================================================
  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewCustomer) return;
    loadCustomers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewCustomer]);

  // =====================================================
  // INPUT
  // =====================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setMessage("");
    setError("");
  };

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
    setMessage("");
    setError("");
  };

  const handleNew = () => {
    if (!canAddCustomer) {
      setError("You do not have permission to create customers.");
      return;
    }
    resetForm();
  };

  // =====================================================
  // GENERATE CUSTOMER CODE  (CUS00001, CUS00002, …)
  // =====================================================
  const generateCustomerCode = async () => {
    const rows = await listCollection("Customers");
    let max = 0;
    for (const r of rows) {
      const m = String(r.CustomerCode || "").match(/(\d+)$/);
      if (m) {
        const n = parseInt(m[1], 10);
        if (n > max) max = n;
      }
    }
    return `CUS${String(max + 1).padStart(5, "0")}`;
  };

  // =====================================================
  // VALIDATION
  // =====================================================
  const validateForm = () => {
    if (!form.customerName.trim()) {
      setError("Customer name is required");
      return false;
    }
    if (form.customerType !== "Retail" && form.customerType !== "Wholesale") {
      setError("Customer type must be Retail or Wholesale");
      return false;
    }
    return true;
  };

  // =====================================================
  // SAVE / UPDATE
  // =====================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    // Permission gates
    if (editingId && !canEditCustomer) {
      setError("You do not have permission to edit customers.");
      return;
    }
    if (!editingId && !canAddCustomer) {
      setError("You do not have permission to create customers.");
      return;
    }

    if (!validateForm()) return;

    try {
      setSaving(true);

      // =====================================================
      // UPDATE
      // =====================================================
      if (editingId) {
        const payload = {
          CustomerCode: form.customerCode.trim(),
          CustomerName: form.customerName.trim(),
          CustomerType: form.customerType,
          NIC:          form.nic.trim()     || null,
          Phone:        form.phone.trim()   || null,
          Address:      form.address.trim() || null,
          Email:        form.email.trim()   || null,
          PayType:      form.PayType,

          // Only send CreditLimit when the user is allowed to see it,
          // so we never silently overwrite the value with 0.
          ...(canViewCreditLimit && {
            CreditLimit: Number(form.creditLimit) || 0,
          }),

          // Note: OpeningBalance is intentionally NOT sent on update —
          // matches the original behaviour, where it was write-once on create.
        };

        await updateDocById("Customers", editingId, payload, {
          username: user?.username,
        });
        setMessage("Customer updated successfully.");
      }

      // =====================================================
      // CREATE
      // =====================================================
      else {
        // Auto-generate a customer code if the user left it blank
        const code = form.customerCode.trim() || (await generateCustomerCode());

        // Duplicate code check
        const existing = await listCollection("Customers", {
          where: [
            ["IsDelete", "==", 0],
            ["CustomerCode", "==", code],
          ],
          limit: 1,
        });
        if (existing.length > 0) {
          setError(`Customer code "${code}" already exists.`);
          return;
        }

        const payload = {
          CustomerCode: code,
          CustomerName: form.customerName.trim(),
          CustomerType: form.customerType,
          NIC:          form.nic.trim()     || null,
          Phone:        form.phone.trim()   || null,
          Address:      form.address.trim() || null,
          Email:        form.email.trim()   || null,
          PayType:      form.PayType,

          ...(canViewCreditLimit && {
            CreditLimit: Number(form.creditLimit) || 0,
          }),

          OpeningBalance: Number(form.openingBalance) || 0,
          CurrentBalance: Number(form.openingBalance) || 0, // mirror SQL behaviour

          IsActive: 1,
          IsDelete: 0,

          LoyaltyEnabled: 1,
          LoyaltyPoints:  0,
        };

        await createDoc("Customers", payload, {
          customId: code,
          username: user?.username,
        });
        setMessage("Customer created successfully.");
      }

      resetForm();
      await loadCustomers();
    } catch (err) {
      console.error("SAVE CUSTOMER ERROR:", err);
      setError(err?.message || "Unable to save customer.");
    } finally {
      setSaving(false);
    }
  };

  // =====================================================
  // EDIT
  // =====================================================
  const handleEdit = (customer) => {
    if (!canEditCustomer) {
      setError("You do not have permission to edit customers.");
      return;
    }

    setEditingId(customer.id);
    setForm({
      customerCode:   customer.CustomerCode  ?? "",
      customerName:   customer.CustomerName  ?? "",
      customerType:   customer.CustomerType  ?? "",
      nic:            customer.NIC           ?? "",
      phone:          customer.Phone         ?? "",
      address:        customer.Address       ?? "",
      email:          customer.Email         ?? "",
      creditLimit:    customer.CreditLimit   ?? "0",
      // Firestore copy may store OpeningBalance OR CurrentBalance;
      // prefer the explicit OpeningBalance field.
      openingBalance: customer.OpeningBalance ?? customer.CurrentBalance ?? "0",
      PayType:        customer.PayType       ?? "",
    });
    setMessage(`Editing ${customer.CustomerCode}`);
    setError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // =====================================================
  // DEACTIVATE (soft delete — matches your original
  // "Deactivate customer" confirmation message)
  // =====================================================
  const handleDelete = async (customer) => {
    if (!canDeleteCustomer) {
      setError("You do not have permission to deactivate customers.");
      return;
    }
    if (!customer?.id) {
      setError("Invalid customer.");
      return;
    }

    if (!window.confirm(`Deactivate customer "${customer.CustomerName}"?`)) return;

    try {
      setError("");
      setMessage("");

      // Only flip IsActive — keep the document so historical invoices
      // and loyalty rows still resolve.
      await updateDocById("Customers", customer.id, { IsActive: 0 }, {
        username: user?.username,
      });
      setMessage("Customer deactivated successfully.");
      await loadCustomers();
    } catch (err) {
      console.error("DEACTIVATE CUSTOMER ERROR:", err);
      setError(err?.message || "Unable to deactivate customer.");
    }
  };

  // =====================================================
  // SEARCH
  // =====================================================
  const searchText = search.toLowerCase().trim();
  const filteredCustomers = customers.filter((customer) => {
    if (!searchText) return true;
    const fields = [
      customer.CustomerCode,
      customer.CustomerName,
      customer.CustomerType,
      customer.NIC,
      customer.Phone,
      customer.PayType,
    ];
    return fields.join(" ").toLowerCase().includes(searchText);
  });

  // =====================================================
  // HELPERS
  // =====================================================
  const money = (value) => Number(value || 0).toFixed(2);

  // =====================================================
  // COMPUTED
  // =====================================================
  const isEditing    = Boolean(editingId);
  const saveAllowed  = (isEditing && canEditCustomer) || (!isEditing && canAddCustomer);
  const readOnlyEdit = isEditing && !canEditCustomer;

  // =====================================================
  // ACCESS GATE
  // =====================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewCustomer) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Customer Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Customer</code>
          </p>
        </div>
      </div>
    );
  }

  // =====================================================
  // RENDER
  // =====================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">

      {/* HEADER */}
      <div className="bg-white rounded-xl shadow-md p-5 mb-5">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-gray-800">
              Customer Master
            </h1>
            <p className="text-gray-500 mt-1">
              Manage Retail and Wholesale customers
            </p>
          </div>

          <div className="flex items-center gap-3">
            {readOnlyEdit && (
              <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                READ ONLY
              </span>
            )}

            {canAddCustomer && (
              <button
                type="button"
                onClick={handleNew}
                className="bg-gray-600 hover:bg-gray-700 text-white px-5 py-2.5 rounded-lg font-semibold"
              >
                + New Customer
              </button>
            )}
          </div>
        </div>
      </div>

      {/* MESSAGES */}
      {error && (
        <div className="mb-4 bg-red-100 border border-red-300 text-red-700 px-4 py-3 rounded-lg">
          {error}
        </div>
      )}
      {message && (
        <div className="mb-4 bg-green-100 border border-green-300 text-green-700 px-4 py-3 rounded-lg">
          {message}
        </div>
      )}

      {/* CUSTOMER FORM */}
      <div className="bg-white rounded-xl shadow-md p-5 mb-6">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-xl font-bold text-gray-800">
            {isEditing ? "Edit Customer" : "Add Customer"}
          </h2>
          {isEditing && (
            <span className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-sm font-semibold">
              Editing
            </span>
          )}
        </div>

        <form onSubmit={handleSubmit}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">

            {/* Customer Code */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Customer Code
              </label>
              <input
                type="text"
                name="customerCode"
                value={form.customerCode}
                onChange={handleChange}
                placeholder="Auto generated if empty"
                disabled={isEditing}
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100 disabled:text-gray-500"
              />
            </div>

            {/* Customer Name */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Customer Name *
              </label>
              <input
                type="text"
                name="customerName"
                value={form.customerName}
                onChange={handleChange}
                placeholder="Enter customer name"
                required
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Customer Type */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Customer Type *
              </label>
              <select
                name="customerType"
                value={form.customerType}
                onChange={handleChange}
                required
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 bg-white outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="">Select Customer Type</option>
                <option value="Retail">Retail</option>
                <option value="Wholesale">Wholesale</option>
              </select>
            </div>

            {/* NIC */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                NIC
              </label>
              <input
                type="text"
                name="nic"
                value={form.nic}
                onChange={handleChange}
                placeholder="Enter NIC"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Phone */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Phone
              </label>
              <input
                type="text"
                name="phone"
                value={form.phone}
                onChange={handleChange}
                placeholder="Enter phone"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Email */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Email
              </label>
              <input
                type="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                placeholder="Enter email"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            {/* Credit Limit — only when the user can view it */}
            {canViewCreditLimit && (
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">
                  Credit Limit
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  name="creditLimit"
                  value={form.creditLimit}
                  onChange={handleChange}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            )}

            {/* Opening Balance — only shown when creating */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Opening Balance
              </label>
              <input
                type="number"
                step="0.01"
                name="openingBalance"
                value={form.openingBalance}
                onChange={handleChange}
                disabled={isEditing}
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100 disabled:text-gray-500"
              />
            </div>

            {/* Pay Type */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Pay Type *
              </label>
              <select
                name="PayType"
                value={form.PayType}
                onChange={handleChange}
                required
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 bg-white outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="">Select Pay Type</option>
                <option value="Cash">Cash</option>
                <option value="Credit">Credit</option>
              </select>
            </div>

            {/* Address */}
            <div className="md:col-span-2 lg:col-span-3">
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Address
              </label>
              <textarea
                name="address"
                value={form.address}
                onChange={handleChange}
                rows="3"
                placeholder="Enter customer address"
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>
          </div>

          {/* Credit hidden-by-permission notice */}
          {!canViewCreditLimit && (
            <div className="mt-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-xs font-medium text-amber-700">
              Credit Limit is hidden by your permission level.
            </div>
          )}

          {/* BUTTONS */}
          <div className="flex flex-wrap gap-3 mt-6">
            {saveAllowed && (
              <button
                type="submit"
                disabled={saving}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white px-6 py-2.5 rounded-lg font-semibold"
              >
                {saving
                  ? "Saving…"
                  : isEditing
                  ? "Update Customer"
                  : "Save Customer"}
              </button>
            )}

            <button
              type="button"
              onClick={resetForm}
              className="bg-gray-500 hover:bg-gray-600 text-white px-6 py-2.5 rounded-lg font-semibold"
            >
              Clear
            </button>

            {readOnlyEdit && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!isEditing && !canAddCustomer && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                You do not have permission to create new customers.
              </div>
            )}
          </div>
        </form>
      </div>

      {/* CUSTOMER LIST */}
      <div className="bg-white rounded-xl shadow-md">
        <div className="p-5 border-b">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h2 className="text-xl font-bold text-gray-800">Customer List</h2>
              <p className="text-gray-500 text-sm mt-1">
                {filteredCustomers.length} customer(s)
              </p>
            </div>

            <div className="w-full md:w-80">
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search customer..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          {loading && customers.length === 0 ? (
            <div className="p-10 text-center text-gray-500">
              Loading customers…
            </div>
          ) : filteredCustomers.length === 0 ? (
            <div className="p-10 text-center text-gray-500">
              No customers found
            </div>
          ) : (
            <table className="min-w-full">
              <thead className="bg-gray-100">
                <tr>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">#</th>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">Code</th>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">Customer Name</th>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">Type</th>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">NIC</th>
                  <th className="px-4 py-3 text-left text-sm font-bold text-gray-700">Phone</th>

                  {canViewCreditLimit && (
                    <th className="px-4 py-3 text-right text-sm font-bold text-gray-700">
                      Credit Limit
                    </th>
                  )}

                  <th className="px-4 py-3 text-right text-sm font-bold text-gray-700">Opening Balance</th>
                  <th className="px-4 py-3 text-center text-sm font-bold text-gray-700">Pay Type</th>
                  <th className="px-4 py-3 text-center text-sm font-bold text-gray-700">Status</th>
                  <th className="px-4 py-3 text-center text-sm font-bold text-gray-700">Actions</th>
                </tr>
              </thead>

              <tbody>
                {filteredCustomers.map((customer, index) => {
                  const isActive =
                    customer.IsActive === 1 ||
                    customer.IsActive === true ||
                    customer.IsActive === "1" ||
                    customer.IsActive === undefined; // treat missing as active

                  return (
                    <tr
                      key={customer.id}
                      className="border-b hover:bg-gray-50"
                    >
                      <td className="px-4 py-3 text-sm">{index + 1}</td>

                      <td className="px-4 py-3 text-sm font-semibold">
                        {customer.CustomerCode}
                      </td>

                      <td className="px-4 py-3 text-sm">
                        {customer.CustomerName}
                      </td>

                      <td className="px-4 py-3">
                        {customer.CustomerType === "Wholesale" ? (
                          <span className="inline-flex px-3 py-1 rounded-full bg-purple-100 text-purple-700 text-xs font-bold">
                            Wholesale
                          </span>
                        ) : (
                          <span className="inline-flex px-3 py-1 rounded-full bg-blue-100 text-blue-700 text-xs font-bold">
                            Retail
                          </span>
                        )}
                      </td>

                      <td className="px-4 py-3 text-sm">{customer.NIC || "-"}</td>
                      <td className="px-4 py-3 text-sm">{customer.Phone || "-"}</td>

                      {canViewCreditLimit && (
                        <td className="px-4 py-3 text-sm text-right">
                          {money(customer.CreditLimit)}
                        </td>
                      )}

                      <td className="px-4 py-3 text-sm text-right">
                        {money(customer.OpeningBalance ?? customer.CurrentBalance)}
                      </td>

                      <td className="px-4 py-3 text-center">
                        {customer.PayType === "Cash" ? (
                          <span className="inline-flex px-3 py-1 rounded-full bg-green-100 text-green-700 text-xs font-bold">
                            Cash
                          </span>
                        ) : customer.PayType === "Credit" ? (
                          <span className="inline-flex px-3 py-1 rounded-full bg-blue-100 text-blue-700 text-xs font-bold">
                            Credit
                          </span>
                        ) : (
                          <span className="inline-flex px-3 py-1 rounded-full bg-gray-100 text-gray-500 text-xs font-bold">
                            -
                          </span>
                        )}
                      </td>

                      <td className="px-4 py-3 text-center">
                        {isActive ? (
                          <span className="text-green-600 font-semibold text-sm">
                            Active
                          </span>
                        ) : (
                          <span className="text-red-600 font-semibold text-sm">
                            Inactive
                          </span>
                        )}
                      </td>

                      <td className="px-4 py-3">
                        <div className="flex justify-center gap-2">
                          {canEditCustomer && (
                            <button
                              type="button"
                              onClick={() => handleEdit(customer)}
                              className="bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-1.5 rounded-md text-sm font-semibold"
                            >
                              Edit
                            </button>
                          )}

                          {canDeleteCustomer && isActive && (
                            <button
                              type="button"
                              onClick={() => handleDelete(customer)}
                              className="bg-red-500 hover:bg-red-600 text-white px-3 py-1.5 rounded-md text-sm font-semibold"
                            >
                              Deactivate
                            </button>
                          )}

                          {!canEditCustomer && !canDeleteCustomer && (
                            <span className="text-xs text-slate-400">No actions</span>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}