// SORDER.jsx — Firestore version
import React, { useEffect, useMemo, useState } from "react";
import { doc, collection, writeBatch, serverTimestamp } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection } from "../lib/firestore";

const SALES_ORDERS = COLLECTIONS?.SALES_ORDERS ?? "SalesOrders";
const CUSTOMERS = COLLECTIONS?.CUSTOMERS ?? "Customers";
const PO_COLL = COLLECTIONS?.PO ?? "PO";
const GRNS = COLLECTIONS?.GRN ?? "GRN";

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

export default function SalesOrder() {
  const [customers, setCustomers] = useState([]);
  const [customerCode, setCustomerCode] = useState("");
  const [customerName, setCustomerName] = useState("");
  const [soDate, setSoDate] = useState(new Date().toISOString().substring(0, 10));
  const [remark, setRemark] = useState("");
  const [discount, setDiscount] = useState(0);
  const [items, setItems] = useState([]);
  const [showPOModal, setShowPOModal] = useState(false);
  const [poSearch, setPOSearch] = useState("");
  const [poItems, setPOItems] = useState([]);
  const [loadingPO, setLoadingPO] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => { loadCustomers(); }, []);

  async function loadCustomers() {
    try {
      const rows = await listCollection(CUSTOMERS, { where: [["IsDelete", "==", 0]] });
      setCustomers(
        rows.map((r) => ({
          CustomerCode: pick(r, "CustomerCode", "customercode"),
          CustomerName: pick(r, "CustomerName", "customername"),
        })).filter((c) => c.CustomerCode)
      );
    } catch (err) {
      console.error(err);
      alert("Unable to load customers");
    }
  }

  async function searchPO(value = "") {
    setLoadingPO(true);
    try {
      const [poRows, grnRows, soRows] = await Promise.all([
        listCollection(PO_COLL, { where: [["IsDelete", "==", 0]] }),
        listCollection(GRNS, { where: [["IsDelete", "==", 0]] }),
        listCollection(SALES_ORDERS),
      ]);

      // Received qty per PO + product from GRN items
      const receivedByKey = {};
      grnRows.forEach((g) => {
        const pono = String(pick(g, "PONo", "pono"));
        (g.items || []).forEach((it) => {
          const key = `${pono}::${it.ProductCode}`;
          receivedByKey[key] = (receivedByKey[key] || 0) + toNum(it.Qty);
        });
      });

      // Already-sold qty per PO + product from SO items
      const soldByKey = {};
      soRows.forEach((so) => {
        (so.items || []).forEach((it) => {
          const key = `${it.pono}::${it.productCode}`;
          soldByKey[key] = (soldByKey[key] || 0) + toNum(it.qty);
        });
      });

      const q = value.trim().toLowerCase();

      const mapped = poRows
        .map((row) => {
          const pono = pick(row, "pono", "PONo");
          const productcode = pick(row, "productcode", "ProductCode");
          const productname = pick(row, "productname", "ProductName");
          const suppliername = pick(row, "suppliername", "SupplierName");
          const suppliercode = pick(row, "suppliercode", "SupplierCode");
          const sellingprice = toNum(pick(row, "sellingprice", "SellingPrice"));
          const qty = toNum(pick(row, "qty", "POQty"));
          const disc = toNum(pick(row, "fixeddiscountpercentage", "FixedDiscountPercentage"));
          const key = `${pono}::${productcode}`;
          const received = receivedByKey[key] || 0;
          const sold = soldByKey[key] || 0;
          const available = Math.max(received - sold, 0);

          return {
            poID: row.id,
            pono, productcode, productname, suppliername, suppliercode,
            sellingprice, qty, receivedqty: received, AvailableQty: available,
            fixeddiscountpercentage: disc,
          };
        })
        .filter((r) => {
          if (r.AvailableQty <= 0) return false;
          if (!q) return true;
          const text = `${r.pono} ${r.productcode} ${r.productname} ${r.suppliername} ${r.suppliercode}`.toLowerCase();
          return text.includes(q);
        });

      setPOItems(mapped.map((it) => ({ ...it, selected: false, saleQty: Number(it.AvailableQty) })));
    } catch (err) {
      console.error(err);
      alert("Unable to load purchase orders");
    } finally {
      setLoadingPO(false);
    }
  }

  function openPOModal() { setShowPOModal(true); setPOSearch(""); searchPO(); }
  function closePOModal() { setShowPOModal(false); setPOItems([]); setPOSearch(""); }

  function togglePOItem(index) {
    setPOItems((cur) => { const c = [...cur]; c[index] = { ...c[index], selected: !c[index].selected }; return c; });
  }
  function updatePOQty(index, value) {
    setPOItems((cur) => {
      const c = [...cur];
      let qty = Number(value); if (Number.isNaN(qty)) qty = 0;
      const avail = Number(c[index].AvailableQty);
      if (qty < 0) qty = 0;
      if (qty > avail) qty = avail;
      c[index] = { ...c[index], saleQty: qty };
      return c;
    });
  }
  function selectAllPO() { setPOItems((cur) => cur.map((it) => ({ ...it, selected: true }))); }
  function clearAllPO() { setPOItems((cur) => cur.map((it) => ({ ...it, selected: false }))); }

  function addPOItems() {
    const selected = poItems.filter((it) => it.selected && Number(it.saleQty) > 0);
    if (selected.length === 0) { alert("Please select at least one product"); return; }
    setItems((cur) => {
      const upd = [...cur];
      selected.forEach((it) => {
        const ex = upd.findIndex((x) => x.productCode === it.productcode && x.poID === it.poID);
        if (ex >= 0) upd[ex] = { ...upd[ex], qty: Number(upd[ex].qty) + Number(it.saleQty) };
        else upd.push({
          poID: it.poID, pono: it.pono, productCode: it.productcode, productName: it.productname,
          qty: Number(it.saleQty), sellingPrice: Number(it.sellingprice),
          discountPercentage: Number(it.fixeddiscountpercentage || 0),
        });
      });
      return upd;
    });
    closePOModal();
  }

  function updateItem(index, field, value) {
    setItems((cur) => {
      const c = [...cur];
      let nv = value;
      if (field === "qty" || field === "sellingPrice" || field === "discountPercentage") {
        nv = Number(value); if (Number.isNaN(nv)) nv = 0;
      }
      c[index] = { ...c[index], [field]: nv };
      return c;
    });
  }
  function removeItem(index) { setItems((cur) => cur.filter((_, i) => i !== index)); }

  const subTotal = useMemo(() => items.reduce((sum, it) => {
    const gross = Number(it.qty) * Number(it.sellingPrice);
    const disc = (gross * Number(it.discountPercentage || 0)) / 100;
    return sum + gross - disc;
  }, 0), [items]);
  const grandTotal = subTotal - Number(discount || 0);

  async function saveSalesOrder() {
    if (!customerCode) { alert("Please select customer"); return; }
    if (items.length === 0) { alert("Please add at least one product"); return; }
    for (const it of items) if (Number(it.qty) <= 0) { alert(`Invalid quantity for ${it.productName}`); return; }

    try {
      setSaving(true);
      // Generate SO number
      const existing = await listCollection(SALES_ORDERS);
      let max = 0;
      existing.forEach((r) => {
        const m = String(pick(r, "SoNo", "SONo", "sono") || "").match(/(\d+)$/);
        if (m) { const n = Number(m[1]); if (n > max) max = n; }
      });
      const soNo = `SO${String(max + 1).padStart(5, "0")}`;

      const batch = writeBatch(db);
      const ref = doc(collection(db, SALES_ORDERS));
      batch.set(ref, {
        SoNo: soNo, SoDate: soDate,
        CustomerCode: customerCode, CustomerName: customerName,
        Discount: Number(discount || 0), Remark: remark || "",
        GrandTotal: grandTotal,
        items: items.map((it) => ({
          poID: it.poID, pono: it.pono, productCode: it.productCode, productName: it.productName,
          qty: Number(it.qty), sellingPrice: Number(it.sellingPrice),
          discountPercentage: Number(it.discountPercentage || 0),
        })),
        CreatedAt: serverTimestamp(),
        IsDelete: 0,
      });
      await batch.commit();

      alert(`Sales Order ${soNo} saved successfully`);
      setItems([]); setDiscount(0); setRemark("");
    } catch (err) {
      console.error(err);
      alert(err.message || "Unable to save Sales Order");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Sales Order</h1>
          <p className="mt-1 text-sm text-slate-500">Create a new sales order</p>
        </div>
        <button type="button" onClick={openPOModal}
          className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700">
          <span className="text-lg">+</span> Recall From PO
        </button>
      </div>

      <div className="mb-6 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="grid grid-cols-1 gap-5 md:grid-cols-3">
          <div>
            <label className="mb-1.5 block text-sm font-medium text-slate-700">SO Date</label>
            <input type="date" value={soDate} onChange={(e) => setSoDate(e.target.value)}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100" />
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-slate-700">Customer</label>
            <select value={customerCode} onChange={(e) => {
              const code = e.target.value;
              const c = customers.find((x) => x.CustomerCode === code);
              setCustomerCode(code); setCustomerName(c?.CustomerName || "");
            }}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100">
              <option value="">Select Customer</option>
              {customers.map((c) => (<option key={c.CustomerCode} value={c.CustomerCode}>{c.CustomerCode} - {c.CustomerName}</option>))}
            </select>
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-slate-700">Remark</label>
            <input type="text" value={remark} onChange={(e) => setRemark(e.target.value)} placeholder="Optional remark"
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100" />
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
          <div>
            <h2 className="font-semibold text-slate-800">Order Items</h2>
            <p className="text-xs text-slate-500">{items.length} item{items.length !== 1 ? "s" : ""}</p>
          </div>
          <button type="button" onClick={openPOModal}
            className="rounded-lg border border-blue-200 bg-blue-50 px-4 py-2 text-sm font-medium text-blue-700 hover:bg-blue-100">
            + Recall From PO
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-[1100px] w-full text-sm">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>
                <th className="px-4 py-3 text-left">#</th>
                <th className="px-4 py-3 text-left">PO No</th>
                <th className="px-4 py-3 text-left">Product Code</th>
                <th className="px-4 py-3 text-left">Product</th>
                <th className="px-4 py-3 text-right">Qty</th>
                <th className="px-4 py-3 text-right">Price</th>
                <th className="px-4 py-3 text-right">Disc %</th>
                <th className="px-4 py-3 text-right">Disc</th>
                <th className="px-4 py-3 text-right">Total</th>
                <th className="px-4 py-3 text-center">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {items.length === 0 ? (
                <tr><td colSpan="10" className="px-4 py-16 text-center">
                  <div className="text-slate-400">
                    <div className="mb-2 text-4xl">🛒</div>
                    <p className="font-medium">No products added</p>
                    <p className="mt-1 text-sm">Click "Recall From PO" to add products</p>
                  </div>
                </td></tr>
              ) : items.map((item, index) => {
                const gross = Number(item.qty) * Number(item.sellingPrice);
                const disc = (gross * Number(item.discountPercentage || 0)) / 100;
                const total = gross - disc;
                return (
                  <tr key={`${item.poID}-${item.productCode}-${index}`} className="hover:bg-slate-50">
                    <td className="px-4 py-3 text-slate-500">{index + 1}</td>
                    <td className="px-4 py-3"><span className="rounded-md bg-blue-50 px-2 py-1 text-xs font-medium text-blue-700">{item.pono}</span></td>
                    <td className="px-4 py-3 font-medium text-slate-700">{item.productCode}</td>
                    <td className="max-w-[250px] px-4 py-3 text-slate-700">{item.productName}</td>
                    <td className="px-4 py-3"><input type="number" min="0" step="0.001" value={item.qty}
                      onChange={(e) => updateItem(index, "qty", e.target.value)}
                      className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" /></td>
                    <td className="px-4 py-3"><input type="number" min="0" step="0.01" value={item.sellingPrice}
                      onChange={(e) => updateItem(index, "sellingPrice", e.target.value)}
                      className="w-28 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" /></td>
                    <td className="px-4 py-3"><input type="number" min="0" max="100" step="0.01" value={item.discountPercentage}
                      onChange={(e) => updateItem(index, "discountPercentage", e.target.value)}
                      className="w-20 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" /></td>
                    <td className="px-4 py-3 text-right text-slate-600">{disc.toFixed(2)}</td>
                    <td className="px-4 py-3 text-right font-semibold text-slate-800">{total.toFixed(2)}</td>
                    <td className="px-4 py-3 text-center">
                      <button type="button" onClick={() => removeItem(index)}
                        className="rounded-md p-2 text-red-500 hover:bg-red-50 hover:text-red-700" title="Remove">🗑</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="mt-6 flex flex-col-reverse gap-5 lg:flex-row lg:items-end lg:justify-between">
        <div className="text-sm text-slate-500">
          <p>Customer: <span className="ml-1 font-medium text-slate-700">{customerName || "Not selected"}</span></p>
          <p className="mt-1">Products: <span className="ml-1 font-medium text-slate-700">{items.length}</span></p>
        </div>
        <div className="w-full max-w-md rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex items-center justify-between py-2 text-sm">
            <span className="text-slate-500">Sub Total</span>
            <span className="font-medium text-slate-800">{subTotal.toFixed(2)}</span>
          </div>
          <div className="flex items-center justify-between py-2 text-sm">
            <span className="text-slate-500">Order Discount</span>
            <input type="number" min="0" value={discount} onChange={(e) => setDiscount(e.target.value)}
              className="w-28 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500" />
          </div>
          <div className="my-3 border-t border-slate-200" />
          <div className="flex items-center justify-between">
            <span className="text-lg font-semibold text-slate-800">Grand Total</span>
            <span className="text-2xl font-bold text-blue-600">{grandTotal.toFixed(2)}</span>
          </div>
          <button type="button" disabled={saving} onClick={saveSalesOrder}
            className="mt-5 w-full rounded-lg bg-green-600 px-5 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-green-700 disabled:cursor-not-allowed disabled:bg-slate-400">
            {saving ? "Saving..." : "Save Sales Order"}
          </button>
        </div>
      </div>

      {showPOModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 md:p-6">
          <div className="flex max-h-[92vh] w-full max-w-[1500px] flex-col overflow-hidden rounded-xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <div>
                <h2 className="text-lg font-bold text-slate-800">Recall Products From PO</h2>
                <p className="text-xs text-slate-500">Select products from an open purchase order</p>
              </div>
              <button type="button" onClick={closePOModal} className="rounded-lg p-2 text-2xl leading-none text-slate-400 hover:bg-slate-100 hover:text-slate-700">×</button>
            </div>
            <div className="border-b border-slate-200 bg-slate-50 p-4">
              <div className="flex flex-col gap-3 md:flex-row">
                <div className="relative flex-1">
                  <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
                  <input autoFocus type="text" value={poSearch} onChange={(e) => { const v = e.target.value; setPOSearch(v); searchPO(v); }}
                    placeholder="Search PO No, product code, product name or supplier..."
                    className="w-full rounded-lg border border-slate-300 bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" />
                </div>
                <button type="button" onClick={selectAllPO} className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100">Select All</button>
                <button type="button" onClick={clearAllPO} className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100">Clear</button>
              </div>
            </div>
            <div className="flex-1 overflow-auto">
              {loadingPO ? (
                <div className="flex h-48 items-center justify-center">
                  <div className="text-center">
                    <div className="mx-auto mb-3 h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-600" />
                    <p className="text-sm text-slate-500">Loading purchase orders...</p>
                  </div>
                </div>
              ) : poItems.length === 0 ? (
                <div className="flex h-48 items-center justify-center">
                  <div className="text-center text-slate-400">
                    <div className="mb-2 text-3xl">📦</div>
                    <p className="font-medium">No available PO products</p>
                  </div>
                </div>
              ) : (
                <table className="min-w-[1200px] w-full text-sm">
                  <thead className="sticky top-0 z-10 bg-slate-100 text-xs uppercase text-slate-500">
                    <tr>
                      <th className="w-12 px-3 py-3 text-center">Select</th>
                      <th className="px-3 py-3 text-left">PO No</th>
                      <th className="px-3 py-3 text-left">Supplier</th>
                      <th className="px-3 py-3 text-left">Product Code</th>
                      <th className="px-3 py-3 text-left">Product</th>
                      <th className="px-3 py-3 text-right">PO Qty</th>
                      <th className="px-3 py-3 text-right">Received</th>
                      <th className="px-3 py-3 text-right">Available</th>
                      <th className="px-3 py-3 text-right">Sale Qty</th>
                      <th className="px-3 py-3 text-right">Price</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {poItems.map((item, index) => (
                      <tr key={`${item.poID}-${item.productcode}`} className={item.selected ? "bg-blue-50" : "hover:bg-slate-50"}>
                        <td className="px-3 py-3 text-center">
                          <input type="checkbox" checked={item.selected} onChange={() => togglePOItem(index)}
                            className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                        </td>
                        <td className="px-3 py-3"><span className="rounded-md bg-blue-100 px-2 py-1 text-xs font-semibold text-blue-700">{item.pono}</span></td>
                        <td className="px-3 py-3">
                          <div className="font-medium text-slate-700">{item.suppliername}</div>
                          <div className="text-xs text-slate-400">{item.suppliercode}</div>
                        </td>
                        <td className="px-3 py-3 font-medium text-slate-700">{item.productcode}</td>
                        <td className="px-3 py-3 text-slate-700">{item.productname}</td>
                        <td className="px-3 py-3 text-right">{item.qty}</td>
                        <td className="px-3 py-3 text-right text-slate-500">{item.receivedqty}</td>
                        <td className="px-3 py-3 text-right">
                          <span className="rounded-full bg-green-100 px-2.5 py-1 text-xs font-semibold text-green-700">{item.AvailableQty}</span>
                        </td>
                        <td className="px-3 py-3 text-right">
                          <input type="number" min="0" max={item.AvailableQty} step="0.001" value={item.saleQty}
                            onChange={(e) => updatePOQty(index, e.target.value)}
                            className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" />
                        </td>
                        <td className="px-3 py-3 text-right font-medium">{Number(item.sellingprice).toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
            <div className="flex flex-col-reverse gap-3 border-t border-slate-200 bg-slate-50 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
              <div className="text-sm text-slate-500">
                Selected: <span className="font-semibold text-slate-800">{poItems.filter((x) => x.selected).length}</span> products
              </div>
              <div className="flex gap-3">
                <button type="button" onClick={closePOModal} className="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-100">Cancel</button>
                <button type="button" onClick={addPOItems} className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">Add Selected Products</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}