// PrintChecks.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - CheckBooks       (one doc per check book)
//   - Accounts         (bank / cash accounts)
//   - CheckTemplates   (check print layouts)
//   - Suppliers        (for supplier payment selection)
//   - Checks           (issued checks; one doc per check)
//
// Multi-doc operation:
//   - handleCreateCheck() → transaction:
//       1. Read CheckBook, verify NextCheckNumber
//       2. Create Checks doc
//       3. Increment CheckBook.NextCheckNumber
// ============================================================

import React, {
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  doc,
  collection,
  serverTimestamp,
  updateDoc,
} from "firebase/firestore";

import { db } from "../firebase.js";
import {
  COLLECTIONS,
  listCollection,
  getDocById,
  runFirestoreTransaction,
} from "../lib/firestore.js";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS  (falls back to defaults if not in COLLECTIONS)
====================================================== */

const CHECK_BOOKS = COLLECTIONS?.CHECK_BOOKS ?? "CheckBooks";
const ACCOUNTS = COLLECTIONS?.ACCOUNTS ?? "Accounts";
const CHECK_TEMPLATES = COLLECTIONS?.CHECK_TEMPLATES ?? "CheckTemplates";
const SUPPLIERS = COLLECTIONS?.SUPPLIERS ?? "Suppliers";
const CHECKS = COLLECTIONS?.CHECKS ?? "Checks";

/* ======================================================
   CONSTANTS
====================================================== */

const EMPTY_FORM = {
  checkBookID: "",
  checkNumber: "",
  payee: "",
  supplier: "",
  payType: "",
  bankAccountID: "",
  issueDate: new Date().toISOString().slice(0, 10),
  checkDate: new Date().toISOString().slice(0, 10),
  amount: "",
  crossed: false,
  memo: "",
};

const DEFAULT_TEMPLATE = {
  TemplateID: "",
  TemplateName: "Default",
  BankName: "",
  CheckWidth: 210,
  CheckHeight: 102,
  StubWidth: 30,
  ShowCounterfoil: true,

  DateFontSize: 14,
  PayeeFontSize: 14,
  AmountWordsFontSize: 10,
  AmountWordsLineHeight: 1.4,
  AmountNumbersFontSize: 16,

  DateX: 160,
  DateY: 12,

  PayeeX: 60,
  PayeeY: 32,

  AmountWordsX: 60,
  AmountWordsY: 45,

  AmountX: 160,
  AmountY: 60,

  PayeeLabel: "Pay",
  AmountLabel: "Amount",
};

/* ======================================================
   HELPERS
====================================================== */

function formatMoney(value) {
  const number = Number(value || 0);
  return number.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function formatDate(value) {
  if (!value) return "";

  const text = String(value).slice(0, 10);
  const parts = text.split("-");

  if (parts.length === 3) {
    return `${parts[2]}${parts[1]}${parts[0]}`
      .split("")
      .join(" ");
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const year = String(date.getFullYear());

  return `${day}${month}${year}`.split("").join(" ");
}

function formatCheckNumber(value, prefix = "") {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  return `${prefix || ""}${value}`;
}

function statusClass(status) {
  switch (String(status || "").toLowerCase()) {
    case "printed":
      return "bg-green-100 text-green-700 border-green-200";
    case "pending":
      return "bg-yellow-100 text-yellow-700 border-yellow-200";
    case "cancelled":
      return "bg-red-100 text-red-700 border-red-200";
    default:
      return "bg-gray-100 text-gray-700 border-gray-200";
  }
}

/* ======================================================
   NORMALIZERS  (accept both Firestore doc id and legacy field)
====================================================== */

function normalizeAccount(account) {
  const id =
    account.BankAccountID ??
    account.CashAccountID ??
    account.AccountID ??
    account.id ??
    "";

  return {
    ...account,

    BankAccountID: id,
    CashAccountID: id,
    AccountID: account.AccountID ?? id,

    AccountName: account.AccountName ?? account.name ?? "",
    AccountNumber:
      account.AccountNumber ?? account.accountNumber ?? "",
    AccountType: account.AccountType ?? account.type ?? "",
    DetailType: account.DetailType ?? account.detailType ?? "",
    Description: account.Description ?? account.description ?? "",
    StoredBalance:
      account.StoredBalance ?? account.balance ?? 0,
  };
}

function normalizeTemplate(template) {
  if (!template) {
    return { ...DEFAULT_TEMPLATE };
  }

  return {
    ...DEFAULT_TEMPLATE,
    ...template,

    TemplateID:
      template.TemplateID ??
      template.templateId ??
      template.id ??
      "",

    TemplateName:
      template.TemplateName ??
      template.templateName ??
      "Unnamed Template",

    BankName:
      template.BankName ?? template.bankName ?? "",

    CheckWidth: Number(
      template.CheckWidth ??
        template.checkWidth ??
        DEFAULT_TEMPLATE.CheckWidth
    ),

    CheckHeight: Number(
      template.CheckHeight ??
        template.checkHeight ??
        DEFAULT_TEMPLATE.CheckHeight
    ),

    StubWidth: Number(
      template.StubWidth ??
        template.stubWidth ??
        DEFAULT_TEMPLATE.StubWidth
    ),

    ShowCounterfoil: Boolean(
      template.ShowCounterfoil ??
        template.showCounterfoil ??
        DEFAULT_TEMPLATE.ShowCounterfoil
    ),

    DateFontSize: Number(
      template.DateFontSize ??
        template.dateFontSize ??
        DEFAULT_TEMPLATE.DateFontSize
    ),

    PayeeFontSize: Number(
      template.PayeeFontSize ??
        template.payeeFontSize ??
        DEFAULT_TEMPLATE.PayeeFontSize
    ),

    AmountWordsFontSize: Number(
      template.AmountWordsFontSize ??
        template.amountWordsFontSize ??
        DEFAULT_TEMPLATE.AmountWordsFontSize
    ),

    AmountWordsLineHeight: Number(
      template.AmountWordsLineHeight ??
        template.amountWordsLineHeight ??
        DEFAULT_TEMPLATE.AmountWordsLineHeight
    ),

    AmountNumbersFontSize: Number(
      template.AmountNumbersFontSize ??
        template.amountNumbersFontSize ??
        DEFAULT_TEMPLATE.AmountNumbersFontSize
    ),

    DateX: Number(
      template.DateX ?? template.dateX ?? DEFAULT_TEMPLATE.DateX
    ),
    DateY: Number(
      template.DateY ?? template.dateY ?? DEFAULT_TEMPLATE.DateY
    ),

    PayeeX: Number(
      template.PayeeX ?? template.payeeX ?? DEFAULT_TEMPLATE.PayeeX
    ),
    PayeeY: Number(
      template.PayeeY ?? template.payeeY ?? DEFAULT_TEMPLATE.PayeeY
    ),

    AmountWordsX: Number(
      template.AmountWordsX ??
        template.amountWordsX ??
        DEFAULT_TEMPLATE.AmountWordsX
    ),
    AmountWordsY: Number(
      template.AmountWordsY ??
        template.amountWordsY ??
        DEFAULT_TEMPLATE.AmountWordsY
    ),

    AmountX: Number(
      template.AmountX ?? template.amountX ?? DEFAULT_TEMPLATE.AmountX
    ),
    AmountY: Number(
      template.AmountY ?? template.amountY ?? DEFAULT_TEMPLATE.AmountY
    ),

    PayeeLabel:
      template.PayeeLabel ??
      template.payeeLabel ??
      DEFAULT_TEMPLATE.PayeeLabel,

    AmountLabel:
      template.AmountLabel ??
      template.amountLabel ??
      DEFAULT_TEMPLATE.AmountLabel,
  };
}

function normalizeCheckBook(book) {
  if (!book) return null;

  return {
    ...book,
    CheckBookID: book.CheckBookID ?? book.checkBookID ?? book.id ?? "",
    BookName: book.BookName ?? book.bookName ?? "",
    Prefix: book.Prefix ?? book.prefix ?? "",
    StartNumber: Number(book.StartNumber ?? book.startNumber ?? 0),
    EndNumber: Number(book.EndNumber ?? book.endNumber ?? 0),
    NextCheckNumber: Number(
      book.NextCheckNumber ?? book.nextCheckNumber ?? 0
    ),
    BankAccountID:
      book.BankAccountID ??
      book.bankAccountID ??
      book.CashAccountID ??
      "",
    Status: book.Status ?? book.status ?? "Inactive",
  };
}

function normalizeSupplier(supplier) {
  return {
    ...supplier,
    id:
      supplier.SupplierID ??
      supplier.id ??
      supplier.VendorID ??
      supplier.vendorId ??
      "",
    name:
      supplier.SupplierName ??
      supplier.name ??
      supplier.VendorName ??
      supplier.vendorName ??
      "",
  };
}

function normalizeCheck(check) {
  if (!check) return null;

  return {
    ...check,
    CheckID: check.CheckID ?? check.checkID ?? check.id ?? "",
  };
}

/* ======================================================
   COMPONENT
====================================================== */

export default function PrintChecks() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  /* ---------- DATA ---------- */

  const [checks, setChecks] = useState([]);
  const [checkBooks, setCheckBooks] = useState([]);
  const [accounts, setAccounts] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [templates, setTemplates] = useState([]);

  /* ---------- UI ---------- */

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [showCreate, setShowCreate] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [showTemplateSelector, setShowTemplateSelector] =
    useState(false);

  const [selectedCheck, setSelectedCheck] = useState(null);
  const [selectedTemplateId, setSelectedTemplateId] = useState("");
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [loadingTemplate, setLoadingTemplate] = useState(false);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");

  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [form, setForm] = useState(EMPTY_FORM);

  /* ======================================================
     INITIAL LOAD
  ====================================================== */

  useEffect(() => {
    loadAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function loadAll() {
    setLoading(true);
    setError("");

    try {
      const [
        booksRows,
        accountsRows,
        templatesRows,
        suppliersRows,
      ] = await Promise.all([
        listCollection(CHECK_BOOKS),
        listCollection(ACCOUNTS),
        listCollection(CHECK_TEMPLATES),
        listCollection(SUPPLIERS),
      ]);

      setCheckBooks(booksRows.map(normalizeCheckBook).filter(Boolean));

      setAccounts(accountsRows.map(normalizeAccount));

      setTemplates(templatesRows.map(normalizeTemplate));

      setSuppliers(
        suppliersRows
          .map(normalizeSupplier)
          .filter((s) => s.id && s.name)
      );

      await loadChecks();
    } catch (err) {
      console.error("LOAD ALL ERROR:", err);
      setError(err.message || "Failed to load check data.");
    } finally {
      setLoading(false);
    }
  }

  /* ======================================================
     LOAD TEMPLATES (refresh)
  ====================================================== */

  async function loadTemplates() {
    try {
      const rows = await listCollection(CHECK_TEMPLATES);
      const normalized = rows.map(normalizeTemplate);
      setTemplates(normalized);
      return normalized;
    } catch (err) {
      console.error("LOAD TEMPLATES ERROR:", err);
      setTemplates([]);
      throw err;
    }
  }

  /* ======================================================
     LOAD CHECK REPORT
     ------------------------------------------------------
     Status is filtered server-side via Firestore `where`;
     date range is filtered client-side to avoid requiring
     a composite index on (Status, IssueDate).
  ====================================================== */

  async function loadChecks() {
    try {
      const options =
        statusFilter !== "All"
          ? { where: [["Status", "==", statusFilter]] }
          : {};

      const rows = await listCollection(CHECKS, options);

      let filtered = rows.map(normalizeCheck);

      if (fromDate) {
        filtered = filtered.filter((c) => {
          const d = String(c.IssueDate || "").slice(0, 10);
          return d && d >= fromDate;
        });
      }

      if (toDate) {
        filtered = filtered.filter((c) => {
          const d = String(c.IssueDate || "").slice(0, 10);
          return d && d <= toDate;
        });
      }

      setChecks(filtered);
    } catch (err) {
      console.error("LOAD CHECKS ERROR:", err);
      setError(err.message || "Failed to load checks.");
    }
  }

  /* ======================================================
     SEARCH / FILTER
  ====================================================== */

  const filteredChecks = useMemo(() => {
    const value = search.trim().toLowerCase();

    return checks.filter((check) => {
      if (statusFilter !== "All") {
        if (
          String(check.Status || "").toLowerCase() !==
          statusFilter.toLowerCase()
        ) {
          return false;
        }
      }

      if (!value) return true;

      const searchable = [
        check.CheckID,
        check.CheckBookID,
        check.CheckNumber,
        check.Payee,
        check.Supplier,
        check.PayType,
        check.AccountName,
        check.AccountNumber,
        check.BookName,
        check.Prefix,
        check.Memo,
        check.Status,
      ]
        .filter((item) => item !== null && item !== undefined)
        .join(" ")
        .toLowerCase();

      return searchable.includes(value);
    });
  }, [checks, search, statusFilter]);

  /* ======================================================
     SUMMARY
  ====================================================== */

  const summary = useMemo(() => {
    const total = filteredChecks.length;

    const pending = filteredChecks.filter(
      (x) => String(x.Status || "").toLowerCase() === "pending"
    ).length;

    const printed = filteredChecks.filter(
      (x) => String(x.Status || "").toLowerCase() === "printed"
    ).length;

    const cancelled = filteredChecks.filter(
      (x) => String(x.Status || "").toLowerCase() === "cancelled"
    ).length;

    const amount = filteredChecks.reduce(
      (sum, item) => sum + Number(item.Amount || 0),
      0
    );

    return { total, pending, printed, cancelled, amount };
  }, [filteredChecks]);

  /* ======================================================
     FORM
  ====================================================== */

  function handleChange(event) {
    const { name, value, type, checked } = event.target;

    setForm((previous) => ({
      ...previous,

      [name]: type === "checkbox" ? checked : value,

      ...(name === "payType" && value !== "supplierpayment"
        ? { supplier: "" }
        : {}),
    }));
  }

  /* ======================================================
     CHECK BOOK → read NextCheckNumber from Firestore
  ====================================================== */

  async function handleCheckBookChange(event) {
    const checkBookID = event.target.value;

    if (!checkBookID) {
      setForm((previous) => ({
        ...previous,
        checkBookID: "",
        checkNumber: "",
        bankAccountID: "",
      }));
      return;
    }

    try {
      setError("");

      const book = await getDocById(CHECK_BOOKS, String(checkBookID));

      if (!book) {
        throw new Error("Check book not found.");
      }

      const normalized = normalizeCheckBook(book);

      setForm((previous) => ({
        ...previous,
        checkBookID,
        checkNumber: normalized.NextCheckNumber,
        bankAccountID: normalized.BankAccountID,
      }));
    } catch (err) {
      console.error("NEXT CHECK NUMBER ERROR:", err);
      setError(
        err.message || "Unable to get next check number."
      );
    }
  }

  /* ======================================================
     CREATE CHECK  (transaction)
  ====================================================== */

  async function handleCreateCheck(event) {
    event.preventDefault();

    setError("");
    setSuccess("");

    if (!form.checkBookID) {
      setError("Please select a check book.");
      return;
    }

    if (!form.checkNumber) {
      setError("Check number is required.");
      return;
    }

    if (!form.payee.trim()) {
      setError("Payee is required.");
      return;
    }

    if (form.payType === "supplierpayment" && !form.supplier) {
      setError("Please select a supplier.");
      return;
    }

    if (!form.payType) {
      setError("Please select a payment type.");
      return;
    }

    if (!form.bankAccountID) {
      setError("Bank account is required.");
      return;
    }

    if (!form.issueDate) {
      setError("Issue date is required.");
      return;
    }

    if (!form.checkDate) {
      setError("Check date is required.");
      return;
    }

    if (!form.amount || Number(form.amount) <= 0) {
      setError("Amount must be greater than zero.");
      return;
    }

    setSaving(true);

    try {
      const result = await runFirestoreTransaction(async (tx) => {
        /* ---- 1. Re-read the check book ---- */

        const bookRef = doc(db, CHECK_BOOKS, String(form.checkBookID));
        const bookSnap = await tx.get(bookRef);

        if (!bookSnap.exists()) {
          throw new Error("Selected check book not found.");
        }

        const book = bookSnap.data();
        const nextNumber = Number(book.NextCheckNumber);
        const endNumber = Number(book.EndNumber);
        const providedNumber = Number(form.checkNumber);

        if (!Number.isFinite(nextNumber) || nextNumber <= 0) {
          throw new Error(
            "Check book has an invalid NextCheckNumber."
          );
        }

        if (
          Number.isFinite(providedNumber) &&
          providedNumber !== nextNumber
        ) {
          throw new Error(
            `Check number changed from ${providedNumber} to ${nextNumber}. Please refresh and try again.`
          );
        }

        if (
          Number.isFinite(endNumber) &&
          endNumber > 0 &&
          nextNumber > endNumber
        ) {
          throw new Error("Check book has been exhausted.");
        }

        /* ---- 2. Create the check ---- */

        const checkRef = doc(collection(db, CHECKS));

        tx.set(checkRef, {
          CheckBookID: String(form.checkBookID),
          CheckNumber: nextNumber,
          Payee: form.payee.trim(),

          // Backend expects Supplier as NAME (string), not ID
          Supplier: form.supplier || null,

          PayType: form.payType,
          BankAccountID: Number(form.bankAccountID),
          IssueDate: form.issueDate,
          CheckDate: form.checkDate,
          Amount: Number(form.amount),
          Crossed: Boolean(form.crossed),
          Memo: form.memo.trim() || null,
          Status: "Pending",

          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        /* ---- 3. Increment the check book ---- */

        tx.update(bookRef, {
          NextCheckNumber: nextNumber + 1,
          UpdatedAt: serverTimestamp(),
          UpdatedBy: username,
        });

        return {
          checkId: checkRef.id,
          checkNumber: nextNumber,
        };
      });

      setSuccess(
        `Check ${formatCheckNumber(
          result.checkNumber
        )} created successfully.`
      );

      setShowCreate(false);

      setForm({
        ...EMPTY_FORM,
        issueDate: new Date().toISOString().slice(0, 10),
        checkDate: new Date().toISOString().slice(0, 10),
      });

      await loadChecks();

      // Refresh check books (NextCheckNumber advanced)
      const refreshedBooks = await listCollection(CHECK_BOOKS);
      setCheckBooks(
        refreshedBooks.map(normalizeCheckBook).filter(Boolean)
      );
    } catch (err) {
      console.error("CREATE CHECK ERROR:", err);
      setError(err.message || "Failed to create check.");
    } finally {
      setSaving(false);
    }
  }

  /* ======================================================
     TEMPLATE SELECTOR
  ====================================================== */

  async function openTemplateSelector(check) {
    if (!check) return;

    const status = String(check.Status || "").toLowerCase();

    if (status === "cancelled") {
      setError("Cancelled checks cannot be printed.");
      return;
    }

    setSelectedCheck(check);
    setSelectedTemplateId("");
    setSelectedTemplate(null);
    setShowTemplateSelector(true);
    setError("");

    try {
      await loadTemplates();
    } catch (err) {
      console.error(err);
    }
  }

  async function handleTemplateContinue() {
    if (!selectedCheck) return;

    if (!selectedTemplateId) {
      setError("Please select a check template.");
      return;
    }

    setLoadingTemplate(true);
    setError("");

    try {
      const row = await getDocById(
        CHECK_TEMPLATES,
        String(selectedTemplateId)
      );

      if (!row) {
        throw new Error("Template not found.");
      }

      const normalized = normalizeTemplate({
        ...row,
        TemplateID: row.TemplateID ?? row.id,
      });

      setSelectedTemplate(normalized);
      setShowTemplateSelector(false);
      setShowPreview(true);
    } catch (err) {
      console.error("LOAD TEMPLATE DETAIL ERROR:", err);
      setError(
        err.message ||
          "Failed to load the selected check template."
      );
    } finally {
      setLoadingTemplate(false);
    }
  }

  /* ======================================================
     PREVIEW
  ====================================================== */

  function openPreview(check) {
    setSelectedCheck(check);
    setSelectedTemplate(null);
    setSelectedTemplateId("");
    setShowPreview(true);
    setError("");
  }

  /* ======================================================
     PRINT
  ====================================================== */

  async function handlePrint() {
    if (!selectedCheck) return;

    const status = String(selectedCheck.Status || "").toLowerCase();

    if (status === "cancelled") {
      setError("Cancelled checks cannot be printed.");
      return;
    }

    if (!selectedTemplate) {
      setError("Please select a check template before printing.");
      setShowTemplateSelector(true);
      return;
    }

    setError("");

    // Browser print dialog
    window.print();

    if (status !== "printed") {
      try {
        await updateDoc(
          doc(db, CHECKS, String(selectedCheck.CheckID)),
          {
            Status: "Printed",
            PrintedAt: serverTimestamp(),
            PrintedBy: username,
            UpdatedAt: serverTimestamp(),
            UpdatedBy: username,
          }
        );

        setSuccess("Check marked as Printed.");

        await loadChecks();

        const refreshed = await getDocById(
          CHECKS,
          String(selectedCheck.CheckID)
        );

        if (refreshed) {
          setSelectedCheck(normalizeCheck(refreshed));
        }
      } catch (err) {
        console.error(err);
        setError(
          err.message ||
            "Check was sent to print, but the status could not be updated."
        );
      }
    }
  }

  /* ======================================================
     CANCEL
  ====================================================== */

  async function handleCancel(check) {
    if (!check) return;

    const status = String(check.Status || "").toLowerCase();

    if (status === "printed") {
      setError("A printed check cannot be cancelled.");
      return;
    }

    if (status === "cancelled") return;

    const confirmed = window.confirm(
      `Cancel check ${formatCheckNumber(
        check.CheckNumber,
        check.Prefix
      )}?`
    );

    if (!confirmed) return;

    setError("");
    setSuccess("");

    try {
      await updateDoc(doc(db, CHECKS, String(check.CheckID)), {
        Status: "Cancelled",
        CancelledAt: serverTimestamp(),
        CancelledBy: username,
        UpdatedAt: serverTimestamp(),
        UpdatedBy: username,
      });

      setSuccess("Check cancelled successfully.");

      await loadChecks();

      if (
        selectedCheck &&
        String(selectedCheck.CheckID) === String(check.CheckID)
      ) {
        setShowPreview(false);
        setSelectedCheck(null);
        setSelectedTemplate(null);
      }
    } catch (err) {
      console.error(err);
      setError(err.message || "Failed to cancel check.");
    }
  }

  /* ======================================================
     FILTERS / NEW
  ====================================================== */

  function clearFilters() {
    setSearch("");
    setStatusFilter("All");
    setFromDate("");
    setToDate("");
    setTimeout(() => loadChecks(), 0);
  }

  function openCreate() {
    setError("");
    setSuccess("");

    setForm({
      ...EMPTY_FORM,
      issueDate: new Date().toISOString().slice(0, 10),
      checkDate: new Date().toISOString().slice(0, 10),
    });

    setShowCreate(true);
  }

  /* ======================================================
     SELECTED BOOK / ACCOUNT
  ====================================================== */

  const selectedBook = useMemo(() => {
    if (!form.checkBookID) return null;
    return (
      checkBooks.find(
        (book) =>
          String(book.CheckBookID) === String(form.checkBookID)
      ) || null
    );
  }, [checkBooks, form.checkBookID]);

  const selectedAccount = useMemo(() => {
    if (!form.bankAccountID) return null;
    return (
      accounts.find(
        (account) =>
          String(
            account.BankAccountID ??
              account.CashAccountID ??
              account.AccountID ??
              account.id
          ) === String(form.bankAccountID)
      ) || null
    );
  }, [accounts, form.bankAccountID]);

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      {/* PRINT CSS */}
      <style>{`
        @media print {
          @page { size: auto; margin: 0; }
          html, body {
            margin: 0 !important;
            padding: 0 !important;
            background: white !important;
          }
          body * { visibility: hidden !important; }
          #check-print, #check-print * {
            visibility: visible !important;
          }
          #check-print {
            position: absolute !important;
            left: 0 !important;
            top: 0 !important;
            margin: 0 !important;
            box-shadow: none !important;
          }
        }
      `}</style>

      {/* HEADER */}
      <div className="mb-6 flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">
            Print Checks
          </h1>
          <p className="mt-1 text-sm text-slate-500">
            Create, manage, print and track issued checks.
          </p>
        </div>

        <button
          type="button"
          onClick={openCreate}
          className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700 active:scale-[0.98]"
        >
          <span className="text-lg leading-none">+</span>
          New Check
        </button>
      </div>

      {/* ALERTS */}
      {error && (
        <div className="mb-4 flex items-start justify-between gap-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          <div>
            <div className="font-semibold">Error</div>
            <div className="mt-1">{error}</div>
          </div>
          <button
            type="button"
            onClick={() => setError("")}
            className="text-red-500 hover:text-red-700"
          >
            ✕
          </button>
        </div>
      )}

      {success && (
        <div className="mb-4 flex items-start justify-between gap-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
          <div>
            <div className="font-semibold">Success</div>
            <div className="mt-1">{success}</div>
          </div>
          <button
            type="button"
            onClick={() => setSuccess("")}
            className="text-green-500 hover:text-green-700"
          >
            ✕
          </button>
        </div>
      )}

      {/* SUMMARY */}
      <div className="mb-6 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-5">
        <SummaryCard title="Total Checks" value={summary.total} icon="▣" />
        <SummaryCard title="Pending" value={summary.pending} icon="◷" />
        <SummaryCard title="Printed" value={summary.printed} icon="✓" />
        <SummaryCard
          title="Cancelled"
          value={summary.cancelled}
          icon="×"
        />
        <SummaryCard
          title="Total Amount"
          value={formatMoney(summary.amount)}
          icon="Rs"
        />
      </div>

      {/* FILTERS */}
      <div className="mb-5 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-5">
          <div className="xl:col-span-2">
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
              Search
            </label>
            <div className="relative">
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Check no, payee, supplier, account..."
                className="w-full rounded-lg border border-slate-300 bg-white px-4 py-2.5 pr-10 text-sm text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              />
              <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                🔍
              </span>
            </div>
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
              Status
            </label>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            >
              <option value="All">All</option>
              <option value="Pending">Pending</option>
              <option value="Printed">Printed</option>
              <option value="Cancelled">Cancelled</option>
            </select>
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
              From Date
            </label>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            />
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
              To Date
            </label>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            />
          </div>
        </div>

        <div className="mt-4 flex flex-wrap gap-2">
          <button
            type="button"
            onClick={loadChecks}
            className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700"
          >
            Search
          </button>
          <button
            type="button"
            onClick={clearFilters}
            className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
          >
            Clear
          </button>
          <button
            type="button"
            onClick={loadAll}
            className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
          >
            ↻ Refresh
          </button>
        </div>
      </div>

      {/* CHECK TABLE */}
      <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-2 border-b border-slate-200 px-4 py-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="font-semibold text-slate-800">
              Check Register
            </h2>
            <p className="text-xs text-slate-500">
              {filteredChecks.length} check
              {filteredChecks.length === 1 ? "" : "s"} found
            </p>
          </div>

          <div className="text-sm text-slate-500">
            Amount:{" "}
            <span className="font-semibold text-slate-800">
              {formatMoney(summary.amount)}
            </span>
          </div>
        </div>

        {loading ? (
          <div className="flex min-h-[300px] items-center justify-center">
            <div className="flex flex-col items-center gap-3 text-slate-500">
              <div className="h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-600" />
              <span className="text-sm">Loading checks...</span>
            </div>
          </div>
        ) : filteredChecks.length === 0 ? (
          <div className="flex min-h-[300px] flex-col items-center justify-center px-4 text-center">
            <div className="mb-3 flex h-14 w-14 items-center justify-center rounded-full bg-slate-100 text-2xl text-slate-400">
              ▣
            </div>
            <h3 className="font-semibold text-slate-700">
              No checks found
            </h3>
            <p className="mt-1 max-w-md text-sm text-slate-500">
              There are no checks matching the current search and
              filter conditions.
            </p>
            <button
              type="button"
              onClick={openCreate}
              className="mt-4 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700"
            >
              Create New Check
            </button>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-[1200px] w-full text-left">
              <thead className="bg-slate-50">
                <tr className="border-b border-slate-200">
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Check No
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Check Book
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Payee
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Bank Account
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Issue Date
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-500">
                    Check Date
                  </th>
                  <th className="px-4 py-3 text-right text-xs font-bold uppercase tracking-wide text-slate-500">
                    Amount
                  </th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase tracking-wide text-slate-500">
                    Crossed
                  </th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase tracking-wide text-slate-500">
                    Status
                  </th>
                  <th className="px-4 py-3 text-center text-xs font-bold uppercase tracking-wide text-slate-500">
                    Actions
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-slate-100">
                {filteredChecks.map((check) => {
                  const status = String(
                    check.Status || ""
                  ).toLowerCase();

                  const isCancelled = status === "cancelled";
                  const isPrinted = status === "printed";

                  return (
                    <tr
                      key={check.CheckID}
                      className="transition hover:bg-slate-50"
                    >
                      <td className="px-4 py-3">
                        <div className="font-mono text-sm font-bold text-slate-800">
                          {formatCheckNumber(
                            check.CheckNumber,
                            check.Prefix
                          )}
                        </div>
                        <div className="text-xs text-slate-400">
                          ID: {check.CheckID}
                        </div>
                      </td>

                      <td className="px-4 py-3">
                        <div className="text-sm font-medium text-slate-700">
                          {check.BookName || "-"}
                        </div>
                        <div className="text-xs text-slate-400">
                          Book #{check.CheckBookID}
                        </div>
                      </td>

                      <td className="px-4 py-3">
                        <div className="max-w-[220px] truncate text-sm font-medium text-slate-800">
                          {check.Payee || "-"}
                        </div>
                        {check.Supplier && (
                          <div className="max-w-[220px] truncate text-xs text-slate-400">
                            Supplier: {check.Supplier}
                          </div>
                        )}
                      </td>

                      <td className="px-4 py-3">
                        <div className="text-sm text-slate-700">
                          {check.AccountName || "-"}
                        </div>
                        <div className="text-xs text-slate-400">
                          {check.AccountNumber || ""}
                        </div>
                      </td>

                      <td className="px-4 py-3 text-sm text-slate-600">
                        {formatDate(check.IssueDate)}
                      </td>

                      <td className="px-4 py-3 text-sm text-slate-600">
                        {formatDate(check.CheckDate)}
                      </td>

                      <td className="px-4 py-3 text-right">
                        <span className="font-semibold text-slate-800">
                          {formatMoney(check.Amount)}
                        </span>
                      </td>

                      <td className="px-4 py-3 text-center">
                        {check.Crossed ? (
                          <span className="inline-flex rounded-full bg-blue-100 px-2.5 py-1 text-xs font-semibold text-blue-700">
                            A/C Payee
                          </span>
                        ) : (
                          <span className="text-xs text-slate-400">
                            No
                          </span>
                        )}
                      </td>

                      <td className="px-4 py-3 text-center">
                        <span
                          className={`inline-flex rounded-full border px-2.5 py-1 text-xs font-semibold ${statusClass(
                            check.Status
                          )}`}
                        >
                          {check.Status || "Unknown"}
                        </span>
                      </td>

                      <td className="px-4 py-3">
                        <div className="flex items-center justify-center gap-2">
                          {!isPrinted && !isCancelled && (
                            <button
                              type="button"
                              onClick={() =>
                                openTemplateSelector(check)
                              }
                              disabled={isCancelled}
                              className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition ${
                                isCancelled
                                  ? "cursor-not-allowed bg-slate-100 text-slate-400"
                                  : "bg-blue-50 text-blue-700 hover:bg-blue-100"
                              }`}
                            >
                              Print
                            </button>
                          )}

                          <button
                            type="button"
                            onClick={() => openPreview(check)}
                            className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-slate-600 hover:bg-slate-50"
                          >
                            View
                          </button>

                          {!isPrinted && !isCancelled && (
                            <button
                              type="button"
                              onClick={() => handleCancel(check)}
                              className="rounded-lg bg-red-50 px-3 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-100"
                            >
                              Cancel
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* CREATE CHECK MODAL */}
      {showCreate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 p-4">
          <div className="max-h-[95vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white shadow-2xl">
            <div className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-200 bg-white px-6 py-4">
              <div>
                <h2 className="text-lg font-bold text-slate-800">
                  Create New Check
                </h2>
                <p className="text-xs text-slate-500">
                  Enter the check details below.
                </p>
              </div>
              <button
                type="button"
                onClick={() => setShowCreate(false)}
                className="flex h-9 w-9 items-center justify-center rounded-lg text-xl text-slate-400 hover:bg-slate-100 hover:text-slate-700"
              >
                ×
              </button>
            </div>

            <form onSubmit={handleCreateCheck} className="p-6">
              <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                {/* CHECK BOOK */}
                <div className="md:col-span-2">
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Check Book
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <select
                    name="checkBookID"
                    value={form.checkBookID}
                    onChange={handleCheckBookChange}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="">-- Select Check Book --</option>
                    {checkBooks
                      .filter(
                        (book) =>
                          String(book.Status || "").toLowerCase() ===
                          "active"
                      )
                      .map((book) => (
                        <option
                          key={book.CheckBookID}
                          value={book.CheckBookID}
                        >
                          {book.BookName}
                          {book.Prefix ? ` (${book.Prefix})` : ""} -{" "}
                          {book.StartNumber} to {book.EndNumber}
                        </option>
                      ))}
                  </select>
                </div>

                {/* BOOK INFO */}
                {selectedBook && (
                  <div className="md:col-span-2 rounded-lg border border-blue-100 bg-blue-50 p-4">
                    <div className="grid grid-cols-2 gap-4 text-sm md:grid-cols-5">
                      <InfoItem
                        label="Book"
                        value={selectedBook.BookName}
                      />
                      <InfoItem
                        label="Prefix"
                        value={selectedBook.Prefix || "-"}
                      />
                      <InfoItem
                        label="Start"
                        value={selectedBook.StartNumber}
                      />
                      <InfoItem
                        label="End"
                        value={selectedBook.EndNumber}
                      />
                      <InfoItem
                        label="Next"
                        value={selectedBook.NextCheckNumber}
                      />
                    </div>
                  </div>
                )}

                {/* CHECK NUMBER */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Check Number
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="checkNumber"
                    value={form.checkNumber}
                    readOnly
                    className="w-full rounded-lg border border-slate-200 bg-slate-100 px-3 py-2.5 font-mono text-sm font-bold text-slate-700 outline-none"
                  />
                </div>

                {/* ACCOUNT */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Bank / Cash Account
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <select
                    name="bankAccountID"
                    value={form.bankAccountID}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="">-- Select Account --</option>
                    {accounts.map((account) => {
                      const accountId =
                        account.BankAccountID ??
                        account.CashAccountID ??
                        account.AccountID ??
                        account.id;

                      return (
                        <option key={accountId} value={accountId}>
                          {account.AccountName || "Unnamed Account"}
                          {account.AccountNumber
                            ? ` - ${account.AccountNumber}`
                            : ""}
                        </option>
                      );
                    })}
                  </select>
                  {selectedAccount && (
                    <p className="mt-1 text-xs text-slate-400">
                      {selectedAccount.AccountType}
                    </p>
                  )}
                </div>

                {/* PAYEE */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Payee
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="payee"
                    value={form.payee}
                    onChange={handleChange}
                    maxLength={200}
                    placeholder="Enter payee name"
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* PAYMENT TYPE */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Payment Type
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <select
                    name="payType"
                    value={form.payType}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="">-- Select Payment Type --</option>
                    <option value="supplierpayment">
                      Supplier Payment
                    </option>
                    <option value="expenses payment">
                      Expenses Payment
                    </option>
                    <option value="banktransfer">Bank Transfer</option>
                    <option value="manualentry">Manual Entry</option>
                  </select>
                </div>

                {/* SUPPLIER */}
                {form.payType === "supplierpayment" && (
                  <div>
                    <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                      Supplier
                      <span className="ml-1 text-red-500">*</span>
                    </label>
                    <select
                      name="supplier"
                      value={form.supplier}
                      onChange={handleChange}
                      className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                    >
                      <option value="">-- Select Supplier --</option>
                      {suppliers.map((supplier) => (
                        <option key={supplier.id} value={supplier.name}>
                          {supplier.name}
                        </option>
                      ))}
                    </select>
                    {suppliers.length === 0 && (
                      <p className="mt-1 text-xs text-amber-600">
                        No suppliers available.
                      </p>
                    )}
                  </div>
                )}

                {/* ISSUE DATE */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Issue Date
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    name="issueDate"
                    value={form.issueDate}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* CHECK DATE */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Check Date
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    name="checkDate"
                    value={form.checkDate}
                    onChange={handleChange}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* AMOUNT */}
                <div>
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Amount
                    <span className="ml-1 text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    name="amount"
                    value={form.amount}
                    onChange={handleChange}
                    min="0"
                    step="0.01"
                    placeholder="0.00"
                    className="w-full rounded-lg border border-slate-300 px-3 py-2.5 text-right text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>

                {/* CROSSED */}
                <div className="flex items-center">
                  <label className="flex cursor-pointer items-center gap-3 rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
                    <input
                      type="checkbox"
                      name="crossed"
                      checked={form.crossed}
                      onChange={handleChange}
                      className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    />
                    <div>
                      <div className="text-sm font-semibold text-slate-700">
                        Crossed Check
                      </div>
                      <div className="text-xs text-slate-400">
                        Print A/C PAYEE ONLY
                      </div>
                    </div>
                  </label>
                </div>

                {/* MEMO */}
                <div className="md:col-span-2">
                  <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                    Memo
                  </label>
                  <textarea
                    name="memo"
                    value={form.memo}
                    onChange={handleChange}
                    maxLength={500}
                    rows={3}
                    placeholder="Optional notes or payment description"
                    className="w-full resize-none rounded-lg border border-slate-300 px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
                  />
                </div>
              </div>

              <div className="mt-6 flex flex-col-reverse gap-3 border-t border-slate-200 pt-5 sm:flex-row sm:justify-end">
                <button
                  type="button"
                  onClick={() => setShowCreate(false)}
                  disabled={saving}
                  className="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50"
                >
                  Close
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {saving ? "Saving..." : "Create Check"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* TEMPLATE SELECTOR */}
      {showTemplateSelector && selectedCheck && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/70 p-4">
          <div className="w-full max-w-lg rounded-2xl bg-white shadow-2xl">
            <div className="border-b border-slate-200 px-6 py-5">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-lg font-bold text-slate-800">
                    Select Check Template
                  </h2>
                  <p className="mt-1 text-sm text-slate-500">
                    Choose the template to use when printing this
                    check.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => setShowTemplateSelector(false)}
                  className="flex h-9 w-9 items-center justify-center rounded-lg text-xl text-slate-400 hover:bg-slate-100 hover:text-slate-700"
                >
                  ×
                </button>
              </div>
            </div>

            <div className="p-6">
              <div className="mb-5 rounded-xl border border-blue-100 bg-blue-50 p-4">
                <div className="text-xs font-semibold uppercase tracking-wide text-blue-500">
                  Check
                </div>
                <div className="mt-1 font-mono text-lg font-bold text-slate-800">
                  {formatCheckNumber(
                    selectedCheck.CheckNumber,
                    selectedCheck.Prefix
                  )}
                </div>
                <div className="mt-1 text-sm text-slate-600">
                  {selectedCheck.Payee || "-"}
                </div>
                <div className="mt-1 text-sm font-semibold text-slate-700">
                  Rs. {formatMoney(selectedCheck.Amount)}
                </div>
              </div>

              <label className="mb-1.5 block text-sm font-semibold text-slate-700">
                Check Template
                <span className="ml-1 text-red-500">*</span>
              </label>

              <select
                value={selectedTemplateId}
                onChange={(e) =>
                  setSelectedTemplateId(e.target.value)
                }
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-3 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              >
                <option value="">-- Select Check Template --</option>
                {templates.map((template) => (
                  <option
                    key={template.TemplateID}
                    value={template.TemplateID}
                  >
                    {template.TemplateName}
                    {template.BankName ? ` - ${template.BankName}` : ""}
                  </option>
                ))}
              </select>

              {templates.length === 0 && (
                <div className="mt-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-600">
                  No check templates are available. Please create a
                  check template first.
                </div>
              )}

              <div className="mt-6 flex justify-end gap-3">
                <button
                  type="button"
                  onClick={() => {
                    setShowTemplateSelector(false);
                    setSelectedTemplateId("");
                  }}
                  className="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50"
                >
                  Cancel
                </button>
                <button
                  type="button"
                  disabled={!selectedTemplateId || loadingTemplate}
                  onClick={handleTemplateContinue}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {loadingTemplate ? "Loading Template..." : "Continue"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* PREVIEW */}
      {showPreview && selectedCheck && (
        <div className="fixed inset-0 z-50 overflow-auto bg-slate-950/70 p-4">
          <div className="mx-auto mb-4 flex max-w-6xl flex-col gap-3 rounded-xl bg-white p-4 shadow-xl print:hidden sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="font-bold text-slate-800">
                Check Preview
              </h2>
              <p className="text-xs text-slate-500">
                Check No:{" "}
                <span className="font-mono font-semibold">
                  {formatCheckNumber(
                    selectedCheck.CheckNumber,
                    selectedCheck.Prefix
                  )}
                </span>
                {selectedTemplate && (
                  <>
                    {" "}
                    • Template:{" "}
                    <span className="font-semibold text-blue-600">
                      {selectedTemplate.TemplateName}
                    </span>
                  </>
                )}
              </p>
            </div>

            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                onClick={() => setShowPreview(false)}
                className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
              >
                Close
              </button>
              <button
                type="button"
                onClick={() => openTemplateSelector(selectedCheck)}
                className="rounded-lg border border-blue-200 bg-blue-50 px-4 py-2 text-sm font-semibold text-blue-700 hover:bg-blue-100"
              >
                Change Template
              </button>
              {String(selectedCheck.Status || "").toLowerCase() !==
                "cancelled" && (
                <button
                  type="button"
                  onClick={handlePrint}
                  disabled={!selectedTemplate}
                  className="rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  🖨 Print Check
                </button>
              )}
            </div>
          </div>

          <div className="flex justify-center">
            <div
              id="check-print"
              style={{
                width: `${
                  selectedTemplate?.CheckWidth ||
                  DEFAULT_TEMPLATE.CheckWidth
                }mm`,
                height: `${
                  selectedTemplate?.CheckHeight ||
                  DEFAULT_TEMPLATE.CheckHeight
                }mm`,
              }}
              className="relative shrink-0 overflow-hidden bg-white shadow-2xl print:shadow-none"
            >
              {renderCheckPaper(
                selectedCheck,
                selectedTemplate || DEFAULT_TEMPLATE
              )}
            </div>
          </div>

          <div className="mx-auto mt-4 max-w-6xl rounded-xl bg-white p-4 shadow-xl print:hidden">
            <div className="grid grid-cols-2 gap-4 md:grid-cols-5">
              <InfoItem
                label="Check Number"
                value={formatCheckNumber(
                  selectedCheck.CheckNumber,
                  selectedCheck.Prefix
                )}
              />
              <InfoItem
                label="Payee"
                value={selectedCheck.Payee || "-"}
              />
              <InfoItem
                label="Amount"
                value={`Rs. ${formatMoney(selectedCheck.Amount)}`}
              />
              <InfoItem
                label="Template"
                value={selectedTemplate?.TemplateName || "Not selected"}
              />
              <InfoItem
                label="Status"
                value={selectedCheck.Status || "-"}
              />
            </div>

            <div className="mt-4 flex flex-wrap gap-2 border-t border-slate-200 pt-4">
              {String(selectedCheck.Status || "").toLowerCase() !==
                "cancelled" && (
                <button
                  type="button"
                  onClick={handlePrint}
                  disabled={!selectedTemplate}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  🖨 Print Check
                </button>
              )}

              {String(selectedCheck.Status || "").toLowerCase() !==
                "printed" &&
                String(selectedCheck.Status || "").toLowerCase() !==
                  "cancelled" && (
                  <button
                    type="button"
                    onClick={() => handleCancel(selectedCheck)}
                    className="rounded-lg bg-red-50 px-5 py-2.5 text-sm font-semibold text-red-600 hover:bg-red-100"
                  >
                    Cancel Check
                  </button>
                )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ===========================================================
   CHECK PAPER
=========================================================== */

function renderCheckPaper(check, template) {
  const checkWidth = Number(
    template.CheckWidth || DEFAULT_TEMPLATE.CheckWidth
  );

  const checkHeight = Number(
    template.CheckHeight || DEFAULT_TEMPLATE.CheckHeight
  );

  const dateX = Number(template.DateX ?? DEFAULT_TEMPLATE.DateX);
  const dateY = Number(template.DateY ?? DEFAULT_TEMPLATE.DateY);

  const payeeX = Number(template.PayeeX ?? DEFAULT_TEMPLATE.PayeeX);
  const payeeY = Number(template.PayeeY ?? DEFAULT_TEMPLATE.PayeeY);

  const amountWordsX = Number(
    template.AmountWordsX ?? DEFAULT_TEMPLATE.AmountWordsX
  );
  const amountWordsY = Number(
    template.AmountWordsY ?? DEFAULT_TEMPLATE.AmountWordsY
  );

  const amountX = Number(template.AmountX ?? DEFAULT_TEMPLATE.AmountX);
  const amountY = Number(template.AmountY ?? DEFAULT_TEMPLATE.AmountY);

  const dateFontSize = Number(
    template.DateFontSize ?? DEFAULT_TEMPLATE.DateFontSize
  );
  const payeeFontSize = Number(
    template.PayeeFontSize ?? DEFAULT_TEMPLATE.PayeeFontSize
  );
  const amountWordsFontSize = Number(
    template.AmountWordsFontSize ?? DEFAULT_TEMPLATE.AmountWordsFontSize
  );
  const amountNumbersFontSize = Number(
    template.AmountNumbersFontSize ??
      DEFAULT_TEMPLATE.AmountNumbersFontSize
  );
  const amountWordsLineHeight = Number(
    template.AmountWordsLineHeight ??
      DEFAULT_TEMPLATE.AmountWordsLineHeight
  );

  const payeeLabel = template.PayeeLabel || "Pay";
  const amountLabel = template.AmountLabel || "Amount";

  return (
    <>
      <div
        className="absolute border-2 border-white-800"
        style={{
          left: "3mm",
          top: "3mm",
          right: "3mm",
          bottom: "3mm",
        }}
      >
        <div
          className="absolute font-mono font-bold text-slate-800 print:hidden"
          style={{
            right: "5mm",
            top: "4mm",
            fontSize: "12px",
          }}
        >
          {formatCheckNumber(check.CheckNumber, check.Prefix)}
        </div>

        <div
          className="absolute print:hidden"
          style={{ left: "8mm", top: "7mm" }}
        >
          <div className="text-xl font-bold uppercase tracking-wide text-slate-900">
            {check.AccountName || template.BankName || "BANK"}
          </div>
          {check.AccountNumber && (
            <div className="mt-1 font-mono text-xs text-slate-500 print:hidden">
              A/C No: {check.AccountNumber}
            </div>
          )}
        </div>

        <div
          className="absolute flex items-center gap-2"
          style={{
            left: `${dateX}mm`,
            top: `${dateY}mm`,
          }}
        >
          <span className="font-semibold text-slate-600">Date:</span>
          <span
            className="px-3 pb-1 font-medium"
            style={{ fontSize: `${dateFontSize}px` }}
          >
            {formatDate(check.CheckDate)}
          </span>
        </div>

        {check.Crossed && (
          <div
            className="absolute border-2 border-slate-700 px-4 py-1 font-bold tracking-wider text-slate-800"
            style={{ left: "8mm", top: "30mm", fontSize: "10px" }}
          >
            A/C PAYEE ONLY
          </div>
        )}

        <div
          className="absolute"
          style={{
            left: `${payeeX}mm`,
            top: `${payeeY}mm`,
            right: "10mm",
          }}
        >
          <div className="flex items-end gap-3">
            <span
              className="whitespace-nowrap font-semibold text-slate-700"
              style={{ fontSize: `${payeeFontSize}px` }}
            >
              {payeeLabel}
            </span>
            <div
              className="flex-1 pb-1 font-medium text-slate-900"
              style={{ fontSize: `${payeeFontSize}px` }}
            >
              {check.Payee || ""}
            </div>
          </div>
        </div>

        <div
          className="absolute no-print-check-element"
          style={{
            left: `${amountWordsX}mm`,
            top: `${amountWordsY}mm`,
            right: "60mm",
          }}
        >
          <div
            className="pb-1 text-slate-700"
            style={{
              fontSize: `${amountWordsFontSize}px`,
              lineHeight: amountWordsLineHeight,
            }}
          >
            {numberToWords(Number(check.Amount || 0))}
          </div>
        </div>

        <div
          className="absolute"
          style={{
            left: `${amountX}mm`,
            top: `${amountY}mm`,
          }}
        >
          <div className="flex min-w-[45mm] items-center justify-end gap-2 px-3 py-2">
            <span className="text-sm font-semibold">Rs.</span>
            <span
              className="font-mono font-bold"
              style={{ fontSize: `${amountNumbersFontSize}px` }}
            >
              {formatMoney(check.Amount)}
            </span>
          </div>
        </div>

        {check.Memo && (
          <div
            className="absolute"
            style={{ left: "10mm", right: "10mm", bottom: "18mm" }}
          >
            <div className="text-xs text-slate-400">Memo</div>
            <div className="border-b border-slate-400 pb-1 text-xs text-slate-700">
              {check.Memo}
            </div>
          </div>
        )}

        <div
          className="absolute text-center"
          style={{ right: "10mm", bottom: "8mm", width: "50mm" }}
        >
          <div className="mb-1 border-b border-slate-700 print:hidden" />
          <div className="text-xs font-semibold text-slate-600 print:hidden">
            Authorized Signature
          </div>
        </div>

        <div
          className="absolute print:hidden"
          style={{ left: "10mm", bottom: "8mm" }}
        >
          <div className="text-[10px] uppercase text-slate-400 print:hidden">
            Issue Date
          </div>
          <div className="text-xs font-medium text-slate-700 print:hidden">
            {formatDate(check.IssueDate)}
          </div>
        </div>
      </div>

      {template.ShowCounterfoil &&
        Number(template.StubWidth || 0) > 0 && (
          <div
            className="absolute bottom-0 left-0 top-0 border-r border-dashed border-slate-400 print:hidden"
            style={{ width: `${Number(template.StubWidth)}mm` }}
          >
            <div
              className="absolute text-[9px] font-bold uppercase tracking-wider text-slate-400"
              style={{
                left: "3mm",
                top: "50%",
                transform: "rotate(-90deg) translateX(-50%)",
                transformOrigin: "left top",
                whiteSpace: "nowrap",
              }}
            >
              Counterfoil
            </div>
          </div>
        )}
    </>
  );
}

