/* ===========================================================
   NUMBER TO WORDS
=========================================================== */

function numberToWords(number) {
  if (!Number.isFinite(number)) return "";
  if (number === 0) return "Zero Rupees Only";

  const rounded = Math.round(number * 100) / 100;
  const rupees = Math.floor(rounded);
  const cents = Math.round((rounded - rupees) * 100);

  let result = `${convertIndianNumber(rupees)} Rupees`;

  if (cents > 0) {
    result += ` and ${convertIndianNumber(cents)} Cents`;
  }

  return `${result} Only`;
}

function convertIndianNumber(number) {
  if (number === 0) return "Zero";

  const parts = [];

  const crore = Math.floor(number / 10000000);
  if (crore > 0) {
    parts.push(`${convertIndianNumber(crore)} Crore`);
    number %= 10000000;
  }

  const lakh = Math.floor(number / 100000);
  if (lakh > 0) {
    parts.push(`${convertIndianNumber(lakh)} Lakh`);
    number %= 100000;
  }

  const thousand = Math.floor(number / 1000);
  if (thousand > 0) {
    parts.push(`${convertIndianNumber(thousand)} Thousand`);
    number %= 1000;
  }

  const hundred = Math.floor(number / 100);
  if (hundred > 0) {
    parts.push(`${convertIndianNumber(hundred)} Hundred`);
    number %= 100;
  }

  if (number > 0) {
    parts.push(convertBelowHundred(number));
  }

  return parts.join(" ");
}

function convertBelowHundred(number) {
  const ones = [
    "",
    "One",
    "Two",
    "Three",
    "Four",
    "Five",
    "Six",
    "Seven",
    "Eight",
    "Nine",
  ];

  const teens = [
    "Ten",
    "Eleven",
    "Twelve",
    "Thirteen",
    "Fourteen",
    "Fifteen",
    "Sixteen",
    "Seventeen",
    "Eighteen",
    "Nineteen",
  ];

  const tens = [
    "",
    "",
    "Twenty",
    "Thirty",
    "Forty",
    "Fifty",
    "Sixty",
    "Seventy",
    "Eighty",
    "Ninety",
  ];

  if (number < 10) return ones[number];
  if (number < 20) return teens[number - 10];

  const ten = Math.floor(number / 10);
  const one = number % 10;

  return `${tens[ten]}${one ? ` ${ones[one]}` : ""}`;
}